        if not getattr(qlib, "_initialized", False):
            if self.qlib_dir:
                qlib.init(provider_uri=self.qlib_dir)
            else:
                qlib.init()

        df = D.features(
            instruments=list(symbols),
            fields=["$close"],
            start_time=start,
            end_time=end,
        )

        if isinstance(df.index, pd.MultiIndex):
            prices = df["$close"].unstack(level="instrument")
        else:
            prices = df

        prices = prices.dropna()
        validate_market_data(prices, symbols)
        return prices

"""Typed high-level API for multivariate Dynamic Resonance Geometry."""

from __future__ import annotations

from dataclasses import asdict, dataclass
from typing import Dict, Optional, Tuple

import numpy as np

from .cross_resonance import (
    CollectiveResonanceModes,
    CrossResonanceTensor,
    collective_modes,
    estimate_cross_resonance,
)


@dataclass(frozen=True)
class StructuralResonanceFingerprint:
    """Canonical, serialization-friendly system state for one trailing window."""

    timestamp: object
    collective_mode_strength: float
    effective_resonance_rank: float
    synchronization_entropy: float
    algorithm_version: str = "cross-resonance-v1"

    def to_dict(self) -> Dict[str, object]:
        return asdict(self)


@dataclass(frozen=True)
class ResonanceGeometryResult:
    cross_resonance: CrossResonanceTensor
    collective_modes: CollectiveResonanceModes
    fingerprint: StructuralResonanceFingerprint
    parameters: Dict[str, object]


class DynamicResonanceGeometry:
    """Additive facade that leaves the established DRR API unchanged."""

    def __init__(self, sampling_rate: float = 1.0, nperseg: Optional[int] = None):
        if sampling_rate <= 0:
            raise ValueError("sampling_rate must be positive")
        self.sampling_rate = sampling_rate
        self.nperseg = nperseg

    def analyze(
        self,
        data: np.ndarray,
        timestamp: object = None,
        column_names: Optional[Tuple[str, ...]] = None,
        frequency_band: Tuple[float, Optional[float]] = (0.0, None),
    ) -> ResonanceGeometryResult:
        tensor = estimate_cross_resonance(
            data,
            sampling_rate=self.sampling_rate,
            nperseg=self.nperseg,
            column_names=column_names,
        )
        coupling = tensor.band_coupling(*frequency_band)
        modes = collective_modes(coupling)
        fingerprint = StructuralResonanceFingerprint(
            timestamp=timestamp,
            collective_mode_strength=modes.dominant_mode_strength,
            effective_resonance_rank=modes.effective_rank,
            synchronization_entropy=modes.synchronization_entropy,
        )
        return ResonanceGeometryResult(
            tensor,
            modes,
            fingerprint,
            {
                "sampling_rate": self.sampling_rate,
                "nperseg": tensor.nperseg,
                "frequency_band": frequency_band,
                "column_names": tensor.column_names,
            },
        )

    def rolling(
        self, data: np.ndarray, window: int, step: int = 1
    ) -> Tuple[ResonanceGeometryResult, ...]:
        """Analyze trailing windows; every result at endpoint ``t`` uses ``[:t]`` only."""
        values = np.asarray(data, dtype=float)
        if window < 8 or step < 1 or len(values) < window:
            raise ValueError("invalid window, step, or data length")
        return tuple(
            self.analyze(values[end - window : end], timestamp=end - 1)
            for end in range(window, len(values) + 1, step)
        )

"""Positive-semidefinite kernels from structural resonance loadings."""

from __future__ import annotations

import numpy as np


def resonance_risk_kernel(loadings: np.ndarray, center: bool = False) -> np.ndarray:
    """Return a unit-diagonal Gram kernel describing shared DRR exposures."""
    features = np.asarray(loadings, dtype=float)
    if features.ndim != 2 or not np.all(np.isfinite(features)):
        raise ValueError("loadings must be a finite asset-by-feature matrix")
    if center:
        features = features - features.mean(axis=0, keepdims=True)
    norms = np.linalg.norm(features, axis=1, keepdims=True)
    normalized = np.divide(features, norms, out=np.zeros_like(features), where=norms > 0)
    return normalized @ normalized.T


def resonance_regularized_covariance(
    covariance: np.ndarray, kernel: np.ndarray, strength: float
) -> np.ndarray:
    """Add ``strength * D K D`` while preserving covariance units and PSD."""
    sigma, kernel = np.asarray(covariance, float), np.asarray(kernel, float)
    if sigma.shape != kernel.shape or sigma.ndim != 2 or sigma.shape[0] != sigma.shape[1]:
        raise ValueError("covariance and kernel must be equal-size square matrices")
    if strength < 0 or not np.allclose(kernel, kernel.T):
        raise ValueError("strength must be non-negative and kernel symmetric")
    if np.linalg.eigvalsh(kernel).min() < -1e-10:
        raise ValueError("kernel must be positive semidefinite")
    sigma = 0.5 * (sigma + sigma.T)
    volatility = np.sqrt(np.maximum(np.diag(sigma), 0.0))
    adjusted = sigma + strength * (volatility[:, None] * kernel * volatility[None, :])
    return 0.5 * (adjusted + adjusted.T)

"""Paired rooting comparisons with frozen calibration and known synthetic truth.

The simple baselines threshold the largest absolute lagged correlation across
all directed pairs. One uses raw samples; the other first fits and removes one
AR(1) coefficient per channel. Thresholds are learned on separate independent
white-noise trials and never retuned on the evaluation cases. Their behavior
under long memory or a regime switch is an empirical transfer test.

Scores and surrogate p-values are not probabilities that an edge is true.
Wilson intervals describe Monte Carlo variation across independent trials,
not uncertainty about an individual edge or physical causation.
"""

from __future__ import annotations

import hashlib
import json
import math
import platform
from typing import Any, Callable, Dict, List, Mapping, Optional, Sequence, Tuple

import numpy as np

from .calibration import binomial_rate
from .dependent_noise import simulate_fractional_gaussian_noise
from .modules import RootingAnalyzer

SCHEMA_VERSION = "drr-robustness-benchmark-v1"
BASELINES = ("raw_correlation", "ar1_residual_correlation")
METHODS = BASELINES + ("drr_circular_shift", "drr_phase_randomization")
METHOD_NOTES = {
    "raw_correlation": "Max-over-lags correlation; white-noise calibrated family maximum.",
    "ar1_residual_correlation": (
        "Per-window AR(1) residual correlation; separately white-noise calibrated family maximum."
    ),
    "drr_circular_shift": (
        "Existing RootingAnalyzer: circular-shift max-statistic p-values and candidate-edge gate."
    ),
    "drr_phase_randomization": (
        "Existing RootingAnalyzer: phase-randomization max-statistic p-values and candidate-edge gate."
    ),
}

DEFAULT_CONFIG: Dict[str, Any] = {
