}


def config_digest(config: Mapping[str, Any]) -> str:
    return hashlib.sha256(
        json.dumps(config, sort_keys=True, separators=(",", ":"), allow_nan=False).encode("utf-8")
    ).hexdigest()


def validate_config(config: Mapping[str, Any]) -> None:
    for key in ("seed", "n_samples", "max_lag", "lag", "n_surrogates", "n_calibration", "n_trials"):
        value = config[key]
        if (
            isinstance(value, bool)
            or not isinstance(value, int)
            or value < (0 if key == "seed" else 1)
        ):
            raise ValueError(f"{key} must be an integer in its permitted range")
    alpha = config["alpha"]
    if isinstance(alpha, bool) or not isinstance(alpha, (float, int)) or not 0 < alpha < 1:
        raise ValueError("alpha must lie in (0, 1)")
    if config["n_samples"] < config["max_lag"] + 4 or config["lag"] > config["max_lag"]:
        raise ValueError("n_samples must support the lag search and lag must be <= max_lag")
    if 1.0 / (config["n_surrogates"] + 1) > alpha:
        raise ValueError("n_surrogates cannot resolve alpha")
    if math.ceil((config["n_calibration"] + 1) * (1 - alpha)) > config["n_calibration"]:
        raise ValueError("n_calibration cannot resolve alpha")
    cases = config["cases"]
    if not isinstance(cases, list) or not cases:
        raise ValueError("cases must be a nonempty list")
    names = set()
    for case in cases:
        name = case["id"]
        if not isinstance(name, str) or not name or name in names:
            raise ValueError("case identifiers must be nonempty and unique")
        names.add(name)
        if not 0 < case["hurst"] < 1 or not case["regimes"]:
            raise ValueError("each case requires a Hurst exponent in (0, 1) and regimes")
        for regime in case["regimes"]:
            if not 0 <= regime["coupling"] < 1 or not isinstance(regime["reverse"], bool):
                raise ValueError("regimes require coupling in [0, 1) and a boolean reverse flag")


def _seed(config: Mapping[str, Any], *parts: Any) -> int:
    material = json.dumps([config["seed"], *parts], separators=(",", ":")).encode("utf-8")
    return int.from_bytes(hashlib.sha256(material).digest()[:8], "little")


def _data_digest(data: np.ndarray) -> str:
    return hashlib.sha256(np.ascontiguousarray(data, dtype="<f8").tobytes()).hexdigest()


def correlation_edges(data: np.ndarray, max_lag: int) -> Tuple[np.ndarray, np.ndarray]:
    """Conventional Pearson correlations, independently of the DRR implementation."""
    data = np.asarray(data, dtype=float)
    if data.ndim != 2 or data.shape[1] < 2 or len(data) < max_lag + 3 or max_lag < 1:
        raise ValueError("data must support a multivariate lag search")
    if not np.all(np.isfinite(data)) or np.any(np.std(data, axis=0) == 0):
        raise ValueError("data must be finite with nonconstant channels")
    n_variables = data.shape[1]
    scores = np.zeros((n_variables, n_variables))
    lags = np.zeros((n_variables, n_variables), dtype=int)
    for lag in range(1, max_lag + 1):
        correlation = np.abs(np.corrcoef(data[:-lag].T, data[lag:].T)[:n_variables, n_variables:])
        if not np.all(np.isfinite(correlation)):
            raise ValueError("lagged samples must have nonconstant channels")
        np.fill_diagonal(correlation, 0.0)
        improved = correlation > scores
        scores[improved] = correlation[improved]
        lags[improved] = lag
    return scores, lags


def ar1_residuals(data: np.ndarray) -> np.ndarray:
    """Fit each channel separately inside the observation window; discard its first row."""
    centered = np.asarray(data, dtype=float) - np.mean(data, axis=0)
    previous, current = centered[:-1], centered[1:]
    denominator = np.sum(previous**2, axis=0)
    coefficients = np.divide(
        np.sum(previous * current, axis=0),
        denominator,
        out=np.zeros_like(denominator),
        where=denominator > 0,
    )
    return current - previous * coefficients


def calibrate_baselines(config: Mapping[str, Any]) -> Dict[str, Any]:
    """Freeze family-maximum thresholds using only separate white-noise draws.

    Reject strictly above order statistic ceil((m+1)*(1-alpha)). The rank rule
    is conservative for one exchangeable future family maximum, including ties.
    It is not a guarantee after transferring to a different noise distribution.
    """
    validate_config(config)
    maxima: Dict[str, List[float]] = {method: [] for method in BASELINES}
    hashes = []
    for trial in range(config["n_calibration"]):
        rng = np.random.default_rng(_seed(config, "calibration", trial))
        data = rng.standard_normal((config["n_samples"], 3))
        hashes.append(_data_digest(data))
        for method, samples in zip(BASELINES, (data, ar1_residuals(data))):
            scores, _ = correlation_edges(samples, config["max_lag"])
            maxima[method].append(float(scores.max()))
    rank = math.ceil((config["n_calibration"] + 1) * (1 - config["alpha"]))
    return {
        "reference": "independent standard Gaussian channels; separate seeds; no evaluation data",
        "rank": rank,
        "input_sha256": hashes,
        "methods": {
            method: {"threshold": sorted(values)[rank - 1], "family_maxima": values}
            for method, values in maxima.items()
        },
    }


def simulate_regimes(
    config: Mapping[str, Any], case: Mapping[str, Any], trial: int
) -> List[np.ndarray]:
    """Continuous fGn noise with one complete analysis window per declared regime.

    Drop a lag-length buffer at each boundary, so no scored observation obtains
    its source from a differently labeled regime. No analysis window straddles
    the switch. This measures before/after recovery, not change-detection delay.
    """
    n_samples, lag = config["n_samples"], config["lag"]
    length = n_samples + lag
    rng = np.random.default_rng(_seed(config, "evaluation", case["id"], trial))
    base = simulate_fractional_gaussian_noise(length * len(case["regimes"]), 3, case["hurst"], rng)
    windows = []
    for index, regime in enumerate(case["regimes"]):
        start = index * length
        data = base[start + lag : start + length].copy()
        source, target = (1, 0) if regime["reverse"] else (0, 1)
        coupling = regime["coupling"]
        data[:, target] = (
            coupling * base[start : start + n_samples, source]
            + np.sqrt(1 - coupling**2) * data[:, target]
        )
        windows.append(data)
    return windows


def _truth(config: Mapping[str, Any], regime: Mapping[str, Any]) -> List[List[int]]:
    if regime["coupling"] == 0:
        return []
    source, target = (1, 0) if regime["reverse"] else (0, 1)
    return [[source, target, config["lag"]]]


def evaluate_trial(
    config: Mapping[str, Any], case: Mapping[str, Any], trial: int, calibration: Mapping[str, Any]
) -> List[Dict[str, Any]]:
    """All methods see the same windows; the seed schedule permits prefix replay."""
    records = []
    for index, data in enumerate(simulate_regimes(config, case, trial)):
        outcomes = {}
        for method, samples in zip(BASELINES, (data, ar1_residuals(data))):
            scores, lags = correlation_edges(samples, config["max_lag"])
            threshold = calibration["methods"][method]["threshold"]
            outcomes[method] = [
                [int(source), int(target), int(lags[source, target])]
                for source, target in zip(*np.where(scores > threshold))
            ]
        for method in METHODS[2:]:
            result = RootingAnalyzer().analyze(
                data,
                max_lag=config["max_lag"],
                n_surrogates=config["n_surrogates"],
                alpha=config["alpha"],
                surrogate_method=method[4:],
                random_state=_seed(config, "surrogates", case["id"], trial, index, method),
            )
            outcomes[method] = [
                [
                    int(edge["source"].split("_")[-1]),
                    int(edge["target"].split("_")[-1]),
                    int(edge["lag"]),
                ]
                for edge in result["significant_edges"]
            ]
        records.append(
            {
                "case": case["id"],
                "trial": trial,
                "window": index,
                "input_sha256": _data_digest(data),
                "truth": _truth(config, case["regimes"][index]),
                "methods": outcomes,
            }
        )
    return records


def summarize_records(
    records: Sequence[Mapping[str, Any]], config: Mapping[str, Any]
) -> List[Dict[str, Any]]:
    """Rebuild every reported proportion from retained per-trial decisions."""
    grouped: Dict[Tuple[str, int], List[Mapping[str, Any]]] = {}
    seen = set()
    cases = {case["id"]: case for case in config["cases"]}
    for record in records:
        case, trial, window = record["case"], record["trial"], record["window"]
        if type(trial) is not int or type(window) is not int:
            raise ValueError("trial and window identities must be integers")
        digest = record["input_sha256"]
        if (
            not isinstance(digest, str)
            or len(digest) != 64
            or any(c not in "0123456789abcdef" for c in digest)
        ):
            raise ValueError("invalid input SHA-256")
        if case not in cases or not 0 <= trial < config["n_trials"]:
            raise ValueError("unknown case or trial")
        if not 0 <= window < len(cases[case]["regimes"]):
            raise ValueError("unknown window")
        identity = (case, trial, window)
        if identity in seen:
            raise ValueError("duplicate trial/window record")
        seen.add(identity)
        if record["truth"] != _truth(config, cases[case]["regimes"][window]):
            raise ValueError("record truth differs from the protocol")
        if set(record["methods"]) != set(METHODS):
            raise ValueError("missing or unknown method")
        for edges in record["methods"].values():
            if len({tuple(edge) for edge in edges}) != len(edges):
                raise ValueError("duplicate edge")
            for source, target, lag in edges:
                if any(type(value) is not int for value in (source, target, lag)):
                    raise ValueError("edge endpoints and lag must be integers")
                if source not in range(3) or target not in range(3) or source == target:
                    raise ValueError("invalid edge endpoints")
                if lag not in range(1, config["max_lag"] + 1):
                    raise ValueError("invalid edge lag")
        grouped.setdefault((case, window), []).append(record)
    expected = config["n_trials"] * sum(len(case["regimes"]) for case in cases.values())
    if len(seen) != expected:
        raise ValueError("incomplete trial/window records")
    summaries = []
    for case in config["cases"]:
        for window, regime in enumerate(case["regimes"]):
            batch = grouped[(case["id"], window)]
            truth = _truth(config, regime)
            for method in METHODS:
                detections, false_edges, exact, any_lag = 0, 0, 0, 0
                for record in batch:
                    edges = record["methods"][method]
                    detections += bool(edges)
                    false_edges += any(not truth or edge[:2] != truth[0][:2] for edge in edges)
                    exact += bool(truth and truth[0] in edges)
                    any_lag += bool(truth and any(edge[:2] == truth[0][:2] for edge in edges))
                false_rate = binomial_rate(false_edges, len(batch))
                assessment = None
                if not truth:
                    low, high = false_rate["ci95"]
                    assessment = (
                        "inflated"
                        if low > config["alpha"]
                        else (
                            "upper_bound_at_or_below_alpha"
                            if high <= config["alpha"]
                            else "inconclusive"
                        )
                    )
                summaries.append(
                    {
                        "case": case["id"],
                        "window": window,
                        "hurst": case["hurst"],
                        "coupling": regime["coupling"],
                        "truth": truth,
                        "method": method,
                        "any_detection": binomial_rate(detections, len(batch)),
                        "any_non_injected_direction": false_rate,
                        "true_edge_any_lag": binomial_rate(any_lag, len(batch)) if truth else None,
                        "true_edge_exact_lag": binomial_rate(exact, len(batch)) if truth else None,
                        "null_assessment": assessment,
                    }
                )
    return summaries


def run_robustness_benchmark(
    config: Optional[Mapping[str, Any]] = None,
    progress: Optional[Callable[[str], None]] = None,
) -> Dict[str, Any]:
    cfg = json.loads(json.dumps(DEFAULT_CONFIG if config is None else config, allow_nan=False))
    validate_config(cfg)
    calibration = calibrate_baselines(cfg)
    records = []
    for case in cfg["cases"]:
        for trial in range(cfg["n_trials"]):
            records.extend(evaluate_trial(cfg, case, trial, calibration))
        if progress is not None:
            progress(case["id"])
    return {
        "schema_version": SCHEMA_VERSION,
        "config": cfg,
        "config_sha256": config_digest(cfg),
        "environment": {"python": platform.python_version(), "numpy": np.__version__},
        "method_notes": METHOD_NOTES,
        "calibration": calibration,
        "records": records,
        "summary": summarize_records(records, cfg),
    }


def render_robustness_report(artifact: Mapping[str, Any]) -> str:
    def rate(value: Optional[Mapping[str, Any]]) -> str:
        if value is None:
            return "n/a (no injected edge)"
        low, high = value["ci95"]
        return f"{value['rate']:.3f} [{low:.3f}, {high:.3f}]"

    config = artifact["config"]
    lines = [
        "# DRR robustness benchmark",
        "",
        f"Schema: `{artifact['schema_version']}`. Config SHA-256: `{artifact['config_sha256']}`.",
        f"{config['n_trials']} independent trials per case; {config['n_samples']} samples per window;",
        f"lags 1-{config['max_lag']}; {config['n_surrogates']} surrogates; alpha {config['alpha']}.",
        "",
        "![Null false alarms and injected-lag recovery across noise-memory strengths](comparison.png)",
        "",
        "## Frozen calibration",
        "",
        f"Baselines use {config['n_calibration']} separate white-noise trials. Reject strictly above",
        f"order statistic {artifact['calibration']['rank']} of the family maxima. No evaluation data",
        "selects a threshold. Both baselines search the same directed pairs and lags.",
        "",
    ]
    for method in BASELINES:
        threshold = artifact["calibration"]["methods"][method]["threshold"]
        lines.append(f"- `{method}`: threshold {threshold:.6f}.")
    lines += ["", "## Methods", ""]
    lines += [f"- `{method}`: {artifact['method_notes'][method]}" for method in METHODS]
    lines += [
        "",
        "## Trial-level results",
        "",
        "Rates have pointwise Wilson 95% intervals across trials. Windows within a trial are paired;",
        "they are never pooled as independent replicates. Non-injected directions include the reverse",
        "and distractor pairs. Under coupling, autocorrelation can induce additional associations;",
        "these are off-target relative to the generator, not necessarily false statistical relationships.",
        "On uncoupled windows every reported direction is a family-wise false alarm.",
        "",
        "| Case | Window | Method | Injected direction + lag | Any non-injected direction | Null assessment |",
        "| --- | ---: | --- | --- | --- | --- |",
    ]
    for row in artifact["summary"]:
        lines.append(
            f"| {row['case']} | {row['window']} | {row['method']} |"
            f" {rate(row['true_edge_exact_lag'])} | {rate(row['any_non_injected_direction'])} |"
            f" {row['null_assessment'] or 'n/a (coupled)'} |"
        )
    lines += [
        "",
        "## Interpretation and limits",
        "",
        "- All data are synthetic. No physical or domain-transfer validity is established.",
        "- White-noise calibration does not establish error control under long memory or switches.",
        "- A null row is inflated when its interval lower bound exceeds alpha. An interval crossing",
        "  alpha is inconclusive; failure to detect inflation does not establish control.",
        "- Intervals are pointwise, not simultaneous. No global winner or superiority test is declared.",
        "- Rate intervals condition on the retained baseline thresholds; they do not include",
        "  variation from drawing a new calibration set.",
        "- Regime windows do not straddle switches; a lag-length buffer is discarded at each boundary.",
        "  These are before/after comparisons, not measurements of online change-detection delay.",
        "- Correlation scores and p-values are not calibrated probabilities that an edge is true.",
        "- This is a fixed exploratory benchmark, not an independently registered confirmatory study.",
        "- JSON retains calibration maxima, data hashes and all trial decisions for replay and audit.",
        "",
    ]
    return "\n".join(lines)

"""Semantic adapter over the existing DRR facade; no replacement of core methods."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Optional

import numpy as np
import pandas as pd

from .common import canonical, DECISION_BOUNDARY


@dataclass(frozen=True)
class DRRConfig:
    lookback: int = 24
    minimum_observations: int = 16
    window_size: int = 12
    rooting_method: str = "lagged_correlation"
    rooting_max_lag: int = 2
    rooting_n_surrogates: int = 99
    rooting_correction: str = "max_statistic"
    seed: int = 42
    standardize: bool = True
    transformation: str = "level"
    topology_threshold: float = 0.25

    def __post_init__(self):
        if (
            self.minimum_observations < 8
            or self.lookback < self.minimum_observations
            or self.window_size < 4
            or self.rooting_max_lag < 1
            or self.rooting_n_surrogates < 0
        ):
            raise ValueError("Invalid DRR history/inference configuration")
        if (
            self.transformation not in {"level", "diff", "pct_change"}
            or self.rooting_method not in {"lagged_correlation", "transfer_entropy"}
            or self.rooting_correction not in {"max_statistic", "none"}
        ):
            raise ValueError("Unsupported DRR specification")
        if not 0 <= self.topology_threshold <= 1:
            raise ValueError("Topology threshold must be in [0,1]")


class LFBORegimeAnalyzer:
    def __init__(self, config=None):
        self.config = config or DRRConfig()

    def analyze(self, dataset, *, previous=None):
        config = self.config
        base = dict(
            status="unavailable",
            variables=list(dataset.variable_names),
            as_of=dataset.available_as_of,
            config=canonical(config),
            decision_boundary=DECISION_BOUNDARY,
            structural_alert=False,
        )
        for metric in dataset.variable_names:
            records = [o for o in dataset.observations if o.metric == metric][-config.lookback :]
            if len({(o.unit, o.definition_version, o.perimeter_version) for o in records}) > 1:
                return dict(
                    base,
                    limitation="Comparability break in the DRR window; segment the series before analysis",
                )
        try:
            values = dataset.to_drr_input()[-config.lookback :]
        except ValueError as exc:
            return dict(base, limitation=str(exc))
        if config.transformation == "diff":
            values = np.diff(values, axis=0)
        elif config.transformation == "pct_change":
            if np.any(values[:-1] == 0):
                return dict(base, limitation="Percent changes undefined for zero denominator")
            values = np.diff(values, axis=0) / np.abs(values[:-1]) * 100
        if len(values) < config.minimum_observations:
            return dict(
                base,
                limitation=f"{len(values)} complete quarters available; {config.minimum_observations} required",
            )
        if config.standardize:
            # Fit on prior rows: the current observation does not calibrate its own scale.
            mean, std = values[:-1].mean(axis=0), values[:-1].std(axis=0)
            values = (values - mean) / np.where(std > 0, std, 1.0)
        from ..analysis import DynamicResonanceRooting
        from ..structural_surprise import structural_surprise
        from ..topology_dynamics import topology_drift, root_migration, summarize_topology
        from ..reporting import serialize_analysis_results

        drr = DynamicResonanceRooting(sampling_rate=dataset.sampling_rate)
        result = drr.analyze_system(
            values,
            multivariate=len(dataset.variable_names) > 1,
            window_size=config.window_size,
            rooting_method=config.rooting_method,
            rooting_max_lag=config.rooting_max_lag,
            rooting_n_surrogates=config.rooting_n_surrogates,
            rooting_random_state=config.seed,
            rooting_correction=config.rooting_correction,
        )
        names = {f"dim_{i}": name for i, name in enumerate(dataset.variable_names)}

        def rename(value):
            if isinstance(value, dict):
                return {names.get(k, k): rename(v) for k, v in value.items()}
            if isinstance(value, (list, tuple)):
                return [rename(v) for v in value]
            return names.get(value, value) if isinstance(value, str) else value

        result = rename(serialize_analysis_results(result))
        rooting = result.get("rooting_analysis", {})
        surprise = structural_surprise(
            values, min_history=max(8, len(values) // 2), feature_names=dataset.variable_names
        )
        finite = surprise.score[:-1][np.isfinite(surprise.score[:-1])]
        threshold = float(np.quantile(finite, 0.975)) if len(finite) >= 4 else None
        surprise_flag = bool(
            threshold is not None
            and float(surprise.score[-1]) > threshold
            and float(surprise.score[-1]) > 3.0
        )
        matrix = rooting.get("score_matrix")
        drift = migration = None
        topology = None
        if matrix is not None:
            topology = canonical(summarize_topology(np.asarray(matrix)))
            if (
                previous
                and previous.get("variables") == base["variables"]
                and previous.get("config") == base["config"]
            ):
                prior = previous.get("rooting", {}).get("score_matrix")
                if prior is not None:
                    drift = topology_drift(np.asarray(prior), np.asarray(matrix))
                    migration = root_migration(np.asarray(prior), np.asarray(matrix))
        inference_error = rooting.get("error")
        return dict(
            base,
            status="partial" if inference_error else "available",
            limitation=inference_error,
            observation_count=len(values),
            frequency_unit="cycles per year (quarterly sampling)",
            resonance_depth=result.get("resonance_depths", {}),
            resonance_persistence=result.get("resonance_depth_details", {}),
            frequencies={
                k: v.get("dominant_freq") for k, v in result.get("resonances", {}).items()
            },
            rooting=rooting,
            rooting_backend=rooting.get("method"),
            state_space=result.get("state_space_analysis", {}).get("diagnostics", {}),
            structural_surprise={
                "score": float(surprise.score[-1]),
                "prior_threshold": threshold,
                "threshold_history": len(finite),
                "flagged": surprise_flag,
            },
            topology=topology,
            topology_drift=drift,
            root_migration=migration,
            structural_alert=surprise_flag
            or bool(drift is not None and drift >= config.topology_threshold),
            limitations=[
                "Quarterly histories are short; spectral and dependence estimates can be unstable.",
                "State-space fit/smoothing describe this as-of window; smoothed historical states are retrospective.",
                "Structural surprise and topology thresholds are exploratory heuristics, not calibrated distress probabilities.",
            ],
        )

"""Deterministic analyst briefs; all numerical claims come from structured evidence."""

from __future__ import annotations

from .common import DECISION_BOUNDARY
from .judgment import display_policy_outcome


def generate_morning_brief(result):
    delta, attention = result["delta"], result["attention"]
    lines = [
        "# Morning Monitoring Brief",
        "",
        f"As of: {result['as_of']} · {result['scope']}",
        "",
        "## Since Last Review",
        "",
    ]
    lines += [
        f"- {len(delta['new_observations'])} newly available observations; {len(delta['changed_observations'])} revised observations.",
        f"- {len(delta['new_signals'])} new signals; {len(delta['strengthened'])} strengthened; {len(delta['weakened'])+len(delta['disappeared'])} weakened or disappeared.",
        f"- {len(delta['new_exceptions'])} new data-quality exceptions; {len(delta['resolved_exceptions'])} resolved exceptions.",
        f"- {len(delta['new_policy_events'])} new potentially relevant policy/reporting events.",
        f"- {len(result.get('perspectives', {}).get('disagreements', []))} documented perspective divergences remain visible.",
        "",
        "## Review First",
        "",
    ]
    if attention["review_first"]:
        for item in attention["review_first"]:
            s = item["signal"]
            lines += [
                f"- **{s['claim']}** — {item['novelty']}. Materiality {s['materiality']:.0f}/100; data confidence {s['confidence']:.0%}. [Why am I seeing this?](evidence/{s['evidence_id']}.md)"
            ]
            overlay = ((result.get("judgment") or {}).get("overlays") or {}).get(s["evidence_id"])
            if overlay:
                lines.append(
                    "  - Typed judgment policy: "
                    + display_policy_outcome(overlay.get("policy_outcome"))
                    + ". This is not the analytical score and it is not an analyst disposition."
                )
    elif any(e["severity"] == "important" for e in result["quality"]):
        lines.append(
            "No material signal cleared the review queue. Data-quality blockers require attention before interpreting this as a quiet period."
        )
    elif attention["deferred"]:
        lines.append("Material items were deferred by the configured attention budget.")
    else:
        lines.append(
            "Nothing material changed among the eligible observations and configured review thresholds."
        )
    if attention["deferred"]:
        lines += [
            "",
            f"{len(attention['deferred'])} additional items are deferred by the attention budget and remain visible in the queue.",
        ]
    lines += ["", "## Filing Revisions", ""]
    for revision in result.get("observation_revisions", []):
        old, new = revision["previous"], revision["current"]
        label = revision["observation_key"]
        if old and new:
            label = f"{new['institution_id']} · {new['form']} · {new['metric']} · {new['reporting_period']}"
            lines.append(
                f"- {label}: {old['value']} {old['unit']} → {new['value']} {new['unit']} "
                f"({old['source_vintage']} → {new['source_vintage']}). "
                f"Comparison: {revision['comparison_status']}. {revision['limitation']}"
            )
        else:
            lines.append(f"- {label}: {revision['limitation']}")
        for transition in revision["concurrent_signal_changes"]:
            lines.append(
                f"  - Concurrent signal change: {transition['transition'].replace('_', ' ')} — {transition['claim']}."
            )
    if not result.get("observation_revisions"):
        lines.append("No same-period filing revisions among the compared observations.")
    lines += ["", "## Deprioritized", ""]
    for s in attention["deprioritized"]:
        revised = any(
            k.startswith(s["institution"] + "|") and ("|" + s["metric"] + "|") in k
            for k in delta["changed_observations"]
        )
        reason = "Evidence weakened, disappeared, or was dispositioned"
        if revised:
            reason += "; the underlying filing was revised"
        lines.append(f"- {s['claim']}: {reason}.")
    if not attention["deprioritized"]:
        lines.append("None.")
    lines += ["", "## Data Quality", ""]
    new = set(delta["new_exceptions"])
    issues = [
        e for e in result["quality"] if e["required_analyst_review"] and e["exception_id"] in new
    ]
    lines += [
        f"- {e['institution']} · {e['metric']} · {e['period']}: {e['issue_type'].replace('_',' ')}. {e['likely_explanation'] or ''}"
        for e in issues
    ] or ["No new exceptions requiring review."]
    lines += ["", "## Policy / Reporting Changes", ""]
    events = [e for e in result["policy"] if e["identifier"]]
    from .common import stable_id

    events = [e for e in events if stable_id(e) in set(delta["new_policy_events"])]
    lines += [
        f"- [{e['title']}]({e['source']}) — {e['status']}; {e['applicability'].replace('_',' ')}."
        for e in events
    ] or ["No new relevant events in the supplied public event inventory."]
    lines += ["", DECISION_BOUNDARY, ""]
    return "\n".join(lines)


def generate_lfbo_monitoring_brief(result, institution):
    analyses = [a for a in result["analyses"] if a["institution"] == institution]
    if not analyses:
        raise ValueError("No eligible institution analysis")
    entries = {oid: p for oid, p in result["evidence"].items() if p["institution"] == institution}
    selected = [
        item
        for item in result["attention"]["review_first"]
        if item["signal"]["institution"] == institution
    ][:5]
    lines = [
        "# LFBO Monitoring Brief",
        "",
        f"Institution: {analyses[0]['name']} ({institution})",
        f"Reporting period: {', '.join(sorted({a['period'] for a in analyses}))}",
        f"As of: {result['as_of']}",
        f"Data vintage: {', '.join(sorted({v for a in analyses for v in a['filing_vintages']}))}",
        f"Peer group: {(result['passport'].get('peer_definition') or {}).get('name','Not configured')}",
        "",
        "## Executive View",
        "",
    ]
    lines += ["- " + i["signal"]["claim"] for i in selected] or [
        "No new material observations selected for this institution."
    ]
    lines += ["", "## Changes Since Previous Review", ""]
    changed = [
        k for k in result["delta"]["changed_observations"] if k.startswith(institution + "|")
    ]
    lines.append(
        f"{len(changed)} revised observations since the prior review. Only new or changed signals enter the morning queue."
    )
    perspectives = result.get("perspectives", {})
    relevant_perspectives = [
        p
        for p in perspectives.get("perspectives", [])
        if not p.get("institution_ids") or institution in p["institution_ids"]
    ]
    relevant_ids = {p["perspective_id"] for p in relevant_perspectives}
    all_disagreements = perspectives.get("disagreements", [])
    disagreements = [
        d for d in all_disagreements if set(d.get("perspective_ids", ())) <= relevant_ids
    ]
    lines += ["", "## Representation Scope", ""]
    lines.append(
        "Perspectives retain their population, scale, horizon, and evidence boundaries. "
        "A difference between perspectives is informative and is not resolved by authority or confidence."
    )
    lines += [
        f"- {p['kind']}: {p['claim']} ({p['population']}; {p['scale']}; {p['dimension']}; support {p['support_assessment']} by {p['support_assessor']})."
        for p in relevant_perspectives
    ]
    if disagreements:
        lines += [f"- Documented divergence: {d['interpretation']}" for d in disagreements]
    elif all_disagreements:
        lines.append(
            "No institution-specific documented divergence; broader system-level records remain visible in the Perspectives panel."
        )
    else:
        lines.append("No documented perspective divergence in the supplied inventory.")
    for title, domains in (
        ("Capital", ("capital",)),
        ("Liquidity / Funding", ("funding", "liquidity")),
        ("Balance Sheet / Exposure", ("balance_sheet",)),
    ):
        lines += ["", "## " + title, ""]
        rows = [(oid, p) for oid, p in entries.items() if p.get("domain") in domains]
        lines += [f"- {p['claim']} ([evidence](evidence/{oid}.md))." for oid, p in rows] or [
            "No selected material evidence in this domain; absence of an alert is not an assessment of safety."
        ]
    lines += [
        "",
        "## Governance / Controls Context",
        "",
        "No governance assessment is inferred from balance-sheet observations. Only sourced public context and analyst-entered interpretation belong here.",
    ]
    for title, field in (
        ("Peer / Horizontal Context", "peer_context"),
        ("Structural / DRR Evidence", "drr_evidence"),
        ("Robustness", "robustness"),
        ("Contradictory Evidence", "contradictory_evidence"),
        ("Policy / Reporting Context", "policy_context"),
        ("Data Quality", "data_limitations"),
    ):
        lines += ["", "## " + title, ""]
        if not entries:
            lines.append("No selected evidence to summarize.")
        for oid, p in entries.items():
            data = p[field]
            if field == "peer_context":
                text = f"{data.get('context','unavailable')}; percentile {data.get('percentile','unavailable')}; {len(data.get('included',[]))} comparable peers"
            elif field == "drr_evidence":
                text = f"DRR {data.get('status','unavailable')}; incremental alert {data.get('incremental_alert',False)}. This does not establish incremental usefulness."
            elif field == "robustness":
                text = f"{data.get('classification','not evaluated')}; {data.get('percentage_surviving')}% of {data.get('planned_count',0)} planned specifications survived"
            else:
                text = (
                    "; ".join(str(v) for v in data)
                    if data
                    else "None in the supplied evidence inventory."
                )
            lines.append(f"- {p['metric']}: {text} ([details](evidence/{oid}.md)).")
    lines += ["", "## Questions for Analyst Review", ""]
    lines += [
        f"- For {p['metric']} at {p['period']}, does the filing narrative explain the observed movement, and are the selected peers still comparable?"
        for p in entries.values()
    ] or ["- Does the current data coverage meet the intended monitoring scope?"]
    lines += ["", "## Evidence", ""] + [f"- [{oid}](evidence/{oid}.md)" for oid in entries]
    lines += ["", "## Analytical Boundary", "", DECISION_BOUNDARY, ""]
    return "\n".join(lines)

"""Conventional econometric challenge models with explicit historical information sets.

These research outputs are separate from scalar ``BaselineResult`` records and
analyst judgment. No coefficient inference, causal interpretation, automatic
specification search, regularization fallback, or outcome imputation is performed.
"""

from __future__ import annotations

import json
import math
import warnings
from dataclasses import dataclass
from datetime import timedelta
from importlib import import_module
from importlib.metadata import PackageNotFoundError, version as distribution_version
from typing import Any, Dict, List, Optional, Tuple, Union

import numpy as np
import pandas as pd

from ..datasets import RegulatoryAnalysisDataset, SupervisoryPanelDataset
from .common import canonical, canonical_json, day, instant, stable_id


def _text(value, name):
    if not isinstance(value, str) or not value.strip():
        raise ValueError(f"{name} must be nonempty text")


def _integer(value, name, minimum=1):
    if isinstance(value, bool) or not isinstance(value, int) or value < minimum:
        raise ValueError(f"{name} must be an integer >= {minimum}")


def _positive(value, name):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValueError(f"{name} must be finite and positive")
    if not math.isfinite(value) or value <= 0:
        raise ValueError(f"{name} must be finite and positive")


def _names(values, name, minimum=1):
    if isinstance(values, str):
        raise ValueError(f"{name} must be a sequence of names")
    try:
        values = tuple(values)
    except TypeError as exc:
        raise ValueError(f"{name} must be a sequence of names") from exc
    for value in values:
        _text(value, name)
    if len(values) < minimum or len(set(values)) != len(values):
        raise ValueError(f"{name} must contain >= {minimum} unique names")
    return values


def _quarter(value):
    value = day(value)
    period = pd.Period(value, freq="Q")
    if value != period.end_time.date().isoformat():
        raise ValueError("reporting_period must be a calendar quarter end")
    return period


def _periods(end, count):
    return tuple(p.end_time.date().isoformat() for p in pd.period_range(end=end, periods=count))


@dataclass(frozen=True)
class ChallengeReview:
    as_of: str
    reporting_period: str

    def __post_init__(self):
        object.__setattr__(self, "as_of", instant(self.as_of).isoformat())
        object.__setattr__(self, "reporting_period", day(self.reporting_period))
        _quarter(self.reporting_period)
        if self.reporting_period > day(self.as_of):
            raise ValueError("Review cannot precede the current reporting period")


@dataclass(frozen=True)
class LaggedFeature:
    metric: str
    lag: int = 1

    def __post_init__(self):
        _text(self.metric, "metric")
        _integer(self.lag, "lag")

    @property
    def name(self):
        return f"L{self.lag}.{self.metric}"


@dataclass(frozen=True)
class BinaryEventLabel:
    """Explicit event/non-event *in this quarter*, separately sourced from features.

    ``None`` means unknown. A zero must be an explicitly ascertained non-event
    under ``definition``; absence from an event list is never converted to zero.
    Multiple vintages are selected by availability, with conflicts rejected.
    """

    institution_id: str
    reporting_period: str
    value: Optional[int]
    available_as_of: str
    definition: str
    source: str
    event_at: Optional[str] = None

    def __post_init__(self):
        for name in ("institution_id", "definition", "source"):
            _text(getattr(self, name), name)
        object.__setattr__(self, "reporting_period", day(self.reporting_period))
        _quarter(self.reporting_period)
        object.__setattr__(self, "available_as_of", instant(self.available_as_of).isoformat())
        if self.value is not None:
            if not isinstance(self.value, (bool, int)) or self.value not in (0, 1):
                raise ValueError("Label value must be explicit 0, 1 or None (unknown)")
            object.__setattr__(self, "value", int(self.value))
        if instant(self.available_as_of) < instant(self.reporting_period):
            raise ValueError("A quarterly outcome cannot be known before the quarter ends")
        if self.event_at is not None:
            object.__setattr__(self, "event_at", instant(self.event_at).isoformat())
            if (
                self.value != 1
                or pd.Period(day(self.event_at), freq="Q") != _quarter(self.reporting_period)
                or instant(self.event_at) > instant(self.available_as_of)
            ):
                raise ValueError("event_at requires a positive label in the same reporting quarter")

    @property
    def label_id(self):
        return stable_id(self)


@dataclass(frozen=True)
class VARChallengeConfig:
    institution_id: str
    form: str
    variables: Tuple[str, ...]
    registered_at: str
    training_periods: int = 24
    lag_order: int = 1
    minimum_residual_df: int = 8
    max_condition_number: float = 1e8
    warning_threshold: float = 3.0

    def __post_init__(self):
        _text(self.institution_id, "institution_id")
        _text(self.form, "form")
        object.__setattr__(self, "variables", _names(self.variables, "variables", 2))
        object.__setattr__(self, "registered_at", instant(self.registered_at).isoformat())
        for name in ("training_periods", "lag_order", "minimum_residual_df"):
            _integer(getattr(self, name), name)
        for name in ("max_condition_number", "warning_threshold"):
            _positive(getattr(self, name), name)
        if self.max_condition_number <= 1:
            raise ValueError("max_condition_number must exceed 1")


@dataclass(frozen=True)
class PanelLogitConfig:
    institutions: Tuple[str, ...]
    form: str
    features: Tuple[LaggedFeature, ...]
    event_definition: str
    registered_at: str
    training_periods: int = 24
    minimum_observations: int = 40
    minimum_institutions: int = 2
    minimum_events: int = 5
    minimum_nonevents: int = 5
    max_condition_number: float = 1e8
    max_iterations: int = 100
    convergence_tolerance: float = 1e-8
    warning_threshold: float = 0.5

    def __post_init__(self):
        object.__setattr__(self, "institutions", _names(self.institutions, "institutions"))
        try:
            object.__setattr__(self, "features", tuple(self.features))
        except TypeError as exc:
            raise ValueError("features must contain LaggedFeature records") from exc
        if not self.features or any(not isinstance(f, LaggedFeature) for f in self.features):
            raise ValueError("features must contain LaggedFeature records")
        if len(set(self.features)) != len(self.features):
            raise ValueError("features must be unique")
        if any(f.metric in {"institution_id", "reporting_period"} for f in self.features):
            raise ValueError("Feature metrics cannot use panel identity-column names")
        _text(self.form, "form")
        _text(self.event_definition, "event_definition")
        object.__setattr__(self, "registered_at", instant(self.registered_at).isoformat())
        for name in (
            "training_periods",
            "minimum_observations",
            "minimum_institutions",
            "minimum_events",
            "minimum_nonevents",
            "max_iterations",
        ):
            _integer(getattr(self, name), name)
        for name in ("max_condition_number", "convergence_tolerance", "warning_threshold"):
            _positive(getattr(self, name), name)
        if self.max_condition_number <= 1 or self.warning_threshold > 1:
            raise ValueError("Invalid conditioning tolerance or probability threshold")
        if self.minimum_institutions > len(self.institutions):
            raise ValueError("minimum_institutions exceeds the configured institution scope")


@dataclass(frozen=True)
class ConventionalChallengeResult:
    """Immutable envelope; method-specific fit and audit data return fresh JSON copies.

    VAR scores are residual-standardized forecast errors. Logit scores are fitted
    conditional probabilities. Neither is a scalar trailing ``BaselineResult``.
    """

    method: str
    institution_id: str
    review: ChallengeReview
    config: Union[VARChallengeConfig, PanelLogitConfig]
    status: str
    score: Optional[float]
    withholding_reason: Optional[str]
    information_set_json: str
    fit_json: str = "{}"
    limitations: Tuple[str, ...] = ()
    evidence_class: str = "CONVENTIONAL_ECONOMETRIC_EVIDENCE"

    @property
    def information_set(self):
        return json.loads(self.information_set_json)

    @property
    def fit(self):
        return json.loads(self.fit_json)

    @property
    def flagged(self):
        return None if self.score is None else self.score >= self.config.warning_threshold

    @property
    def result_id(self):
        return stable_id(self)


def _reviews(reviews, config):
    reviews = tuple(reviews)
    if not reviews or any(not isinstance(r, ChallengeReview) for r in reviews):
        raise ValueError("reviews must contain ChallengeReview records")
    if any(
        instant(b.as_of) <= instant(a.as_of) or b.reporting_period <= a.reporting_period
        for a, b in zip(reviews, reviews[1:])
    ):
        raise ValueError("Review times and reporting periods must be unique and increasing")
    if instant(config.registered_at) >= instant(reviews[0].as_of):
        raise ValueError("The specification must be registered before the first review")
    return reviews


def _labels_as_of(labels, definition, cutoff):
    selected = {}
    for label in labels:
        if not isinstance(label, BinaryEventLabel):
            raise ValueError("labels must contain BinaryEventLabel records")
        if instant(label.available_as_of) > instant(cutoff):
            continue
        if label.definition != definition:
            raise ValueError("Event label definition differs from the registered design")
        key = (label.institution_id, label.reporting_period)
        old = selected.get(key)
        if old is None or instant(old.available_as_of) < instant(label.available_as_of):
            selected[key] = label
        elif old.available_as_of == label.available_as_of and old != label:
            raise ValueError(f"Conflicting event labels for {key}")
    return selected


def _load_statsmodels():
    # Import lazily: the base installation can still run all existing baselines.
    package = import_module("statsmodels")
    api = import_module("statsmodels.api")
    return api, package.__version__


def _package_version(name):
    try:
        return distribution_version(name)
    except PackageNotFoundError:
        return None


@dataclass(frozen=True)
class _WindowedStore:
    """Restrict dataset validation while retaining the original vintage/lineage rules."""

    store: object
    dates: Tuple[str, ...]

    def as_of(self, cutoff):
        return tuple(o for o in self.store.as_of(cutoff) if o.reporting_period in self.dates)


def _snapshot(store, registry, institution, form, variables, dates, cutoff, allow_synthetic):
    """Reconstruct immutable records, never use a caller-mutated display DataFrame."""
    dataset = RegulatoryAnalysisDataset.from_vintage_store(
        _WindowedStore(store, tuple(dates)),
        registry,
        institution_id=institution,
        form=form,
        as_of=cutoff,
        metrics=variables,
        allow_synthetic=allow_synthetic,
    )
    records = tuple(o for o in dataset.observations if o.reporting_period in dates)
    frame = pd.DataFrame(index=dates, columns=variables, dtype=float)
    for record in records:
        frame.loc[record.reporting_period, record.metric] = record.value
    definitions = tuple(
        registry.resolve(
            form,
            o.metric,
            o.reporting_period,
            as_of=cutoff,
            version=o.definition_version,
            allow_synthetic=allow_synthetic,
        )
        for o in records
    )
    definitions = tuple({stable_id(d): d for d in definitions}.values())
    return frame, records, definitions


def _comparability(records, variables, policy, cutoff, form, dates, institution_class):
    reasons, events = [], {}
    for variable in variables:
        metric_records = [o for o in records if o.metric == variable]
        if len({(o.unit, o.definition_version, o.perimeter_version) for o in metric_records}) > 1:
            reasons.append(f"Definition/unit/perimeter break: {variable}")
        if any(o.perimeter_version == "unspecified" for o in metric_records):
            reasons.append(f"Unspecified reporting perimeter: {variable}")
        if policy is not None:
            for event in policy.relevant(
                as_of=cutoff, form=form, metric=variable, institution_class=institution_class
            ):
                if event.comparability_break:
                    effective = (
                        pd.Period(day(event.effective_date), freq="Q").end_time.date().isoformat()
                    )
                    if dates[0] <= effective <= dates[-1]:
                        events[event.event_id] = event
                        reasons.append(f"Known comparability breakpoint: {event.identifier}")
    return tuple(sorted(set(reasons))), tuple(events[k] for k in sorted(events))


def _information(review, config, cutoff, dates, records, definitions, *, labels=(), events=()):
    records = tuple(sorted(records, key=lambda o: o.key))
    return dict(
        review=canonical(review),
        configuration_id=stable_id(config),
        observation_cutoff_exclusive=review.as_of,
        reconstruction_cutoff=cutoff,
        training_periods=dates,
        training_start=dates[0],
        training_end=dates[-1],
        source_observations=canonical(records),
        source_ids=tuple(o.observation_id for o in records),
        source_vintages=tuple(sorted({o.source_vintage for o in records})),
        input_hash=stable_id(records),
        semantic_definitions=canonical(definitions),
        training_labels=canonical(labels),
        training_label_ids=tuple(label.label_id for label in labels),
        policy_events=canonical(events),
        threshold_mode="pre_specified",
        threshold=config.warning_threshold,
        registration_basis="caller declaration; timestamp is not proof of external registration",
        preprocessing="raw levels; training-only centering/scaling; no peers or interpolation",
        numerical_library_versions={
            "numpy": np.__version__,
            "pandas": pd.__version__,
            "scipy": _package_version("scipy"),
            "drr-framework": _package_version("drr-framework"),
        },
    )


def _result(method, institution, review, config, info, fit, reason=None, score=None):
    limitations = (
        "Descriptive fitted parameters only; no coefficient p-values or causal claims.",
        "Short histories and sparse events limit estimation and outcomes analysis.",
        "Ingestion-constrained reconstruction cannot establish what another system knew.",
        "Independent conceptual-soundness and intended-use review remain pending.",
    )
    if method == "panel_logit":
        limitations += (
            "Pooled common slopes; institution effects, serial/cross-firm dependence and rare-event bias are not modeled.",
            "Class counts refer to labeled institution-quarters, not necessarily independent economic episodes.",
            "Unknown labels remain excluded and counted; label selection can bias the observed sample.",
        )
    else:
        limitations += (
            "Fixed-lag linear VAR in levels assumes a stable specification; stationarity is not established.",
            "Forecast-error scores describe unusual observations, not event probabilities.",
        )
    return ConventionalChallengeResult(
        method,
        institution,
        review,
        config,
        "withheld" if reason else "available",
        score,
        reason,
        canonical_json(info),
        canonical_json(fit),
        limitations,
    )


def _design_diagnostics(design, max_condition):
    rank = int(np.linalg.matrix_rank(design))
    condition = float(np.linalg.cond(design))
    diagnostics = dict(
        design_rank=rank, design_columns=design.shape[1], design_condition_number=condition
    )
    reason = None
    if rank < design.shape[1]:
        reason = "Numerically unidentified design"
    elif not np.isfinite(condition) or condition > max_condition:
        reason = "Design exceeds configured condition-number tolerance"
    return diagnostics, reason


def walk_forward_var(
    store,
    registry,
    *,
    reviews,
    config: VARChallengeConfig,
    policy_context=None,
    institution_class=None,
    allow_synthetic=False,
):
    """Refit a fixed VAR on exactly ``training_periods`` lagged target quarters.

    Each fit uses that many target rows plus ``lag_order`` initial observations.
    The current quarter is scored only after fitting; it never calibrates the
    model, residual variance, normalization, lag order, or alert threshold.
    """
    reviews = _reviews(reviews, config)
    results = []
    for review in reviews:
        cutoff = (instant(review.as_of) - timedelta(microseconds=1)).isoformat()
        target = _quarter(review.reporting_period)
        training_dates = _periods(target - 1, config.training_periods)
        dates = _periods(target, config.training_periods + config.lag_order + 1)
        records: Tuple[Any, ...] = ()
        definitions: Tuple[Any, ...] = ()
        events: Tuple[Any, ...] = ()
        reason = None
        values = np.full((len(dates), len(config.variables)), np.nan)
        try:
            frame, records, definitions = _snapshot(
                store,
                registry,
                config.institution_id,
                config.form,
                config.variables,
                dates,
                cutoff,
                allow_synthetic,
            )
            values = frame.to_numpy(dtype=float)
            breaks, events = _comparability(
                records,
                config.variables,
                policy_context,
                cutoff,
                config.form,
                dates,
                institution_class,
            )
            reason = "; ".join(breaks) or None
        except ValueError as exc:
            reason = f"Data unavailable: {exc}"
        info = _information(
            review, config, cutoff, training_dates, records, definitions, events=events
        )
        info.update(
            lag_history_start=dates[0],
            variables=config.variables,
            allow_synthetic=allow_synthetic,
            institution_class=institution_class,
            training_source_ids=tuple(
                o.observation_id for o in records if o.reporting_period < review.reporting_period
            ),
            scoring_source_ids=tuple(
                o.observation_id for o in records if o.reporting_period == review.reporting_period
            ),
        )
        fit: Dict[str, Any] = dict(
            selected_lag_order=config.lag_order,
            lag_selection="pre_specified_fixed",
            training_count=config.training_periods,
            finite_history_periods=int(np.isfinite(values[:-1]).all(axis=1).sum()),
            missing_cells=int((~np.isfinite(values)).sum()),
            coefficient_inference="not_reported",
            package="statsmodels",
            package_version=None,
            score_definition="sqrt(mean((current - forecast)**2 / training_residual_variance))",
        )
        if reason is None and not np.isfinite(values).all():
            reason = "Insufficient history or missing/non-finite observations in the exact configured window"
        df = config.training_periods - (1 + config.lag_order * len(config.variables))
        fit["residual_df"] = df
        if reason is None and df < config.minimum_residual_df:
            reason = "Insufficient residual degrees of freedom for the configured VAR"
        if reason:
            results.append(_result("var", config.institution_id, review, config, info, fit, reason))
            continue
        score = None
        try:
            api, version = _load_statsmodels()
            fit["package_version"] = version
            with np.errstate(over="raise", invalid="raise", divide="raise"):
                training = values[:-1]
                center, scale = training.mean(axis=0), training.std(axis=0, ddof=0)
                if np.any(scale <= 0):
                    raise ValueError("Constant configured VAR variable; no variable was removed")
                z = (training - center) / scale
                p = config.lag_order
                design = np.column_stack(
                    [np.ones(config.training_periods)]
                    + [z[p - lag : len(z) - lag] for lag in range(1, p + 1)]
                )
                diagnostics, reason = _design_diagnostics(design, config.max_condition_number)
                fit.update(diagnostics, normalization_mean=center, normalization_scale=scale)
                if reason is None:
                    with warnings.catch_warnings(record=True) as caught:
                        warnings.simplefilter("always")
                        model = api.tsa.VAR(z, missing="raise").fit(maxlags=p, ic=None, trend="c")
                    fit["warnings"] = tuple(f"{w.category.__name__}: {w.message}" for w in caught)
                    covariance = np.asarray(model.sigma_u)
                    condition = float(np.linalg.cond(covariance))
                    fit.update(
                        coefficients=model.params,
                        coefficient_rows=("intercept",)
                        + tuple(f"L{lag}.{v}" for lag in range(1, p + 1) for v in config.variables),
                        coefficient_columns=config.variables,
                        coefficient_units="training-standardized variables",
                        residuals=model.resid,
                        residual_covariance=covariance,
                        residual_condition_number=condition,
                        residual_mean=np.mean(model.resid, axis=0),
                        residual_rmse=np.sqrt(np.mean(model.resid**2, axis=0)),
                        stable_linear_dynamics=bool(model.is_stable()),
                    )
                    if (
                        not np.isfinite(covariance).all()
                        or not np.isfinite(model.params).all()
                        or np.linalg.matrix_rank(covariance) < len(config.variables)
                        or np.linalg.eigvalsh(covariance).min() <= np.finfo(float).eps
                        or not np.isfinite(condition)
                        or condition > config.max_condition_number
                    ):
                        reason = "Singular or materially ill-conditioned VAR residual covariance"
                    elif any(issubclass(w.category, RuntimeWarning) for w in caught):
                        reason = "VAR numerical warning: " + "; ".join(fit["warnings"])
                    else:
                        forecast = model.forecast(z[-p:], steps=1)[0] * scale + center
                        error = values[-1] - forecast
                        residual_sd = np.sqrt(np.diag(covariance)) * scale
                        score = float(np.sqrt(np.mean((error / residual_sd) ** 2)))
                        if not np.isfinite(score) or not np.isfinite(forecast).all():
                            raise ValueError("Non-finite VAR forecast or score")
                        fit.update(
                            forecast=forecast,
                            observed=values[-1],
                            forecast_error=error,
                            training_residual_sd=residual_sd,
                            forecast_lag_values=training[-p:],
                        )
        except ImportError as exc:
            reason = f"Optional econometrics dependency unavailable: {exc}"
        except (ValueError, np.linalg.LinAlgError, FloatingPointError, OverflowError) as exc:
            reason = f"VAR estimation withheld: {type(exc).__name__}: {exc}"
        results.append(
            _result(
                "var",
                config.institution_id,
                review,
                config,
                info,
                fit,
                reason,
                None if reason else score,
            )
        )
    return tuple(results)


def _panel_predictors(panel: SupervisoryPanelDataset, keys, features):
    """Exact calendar lags on a raw as-of panel; never shift over missing quarters."""
    frame = panel.frame.set_index([panel.institution_column, panel.date_column])
    rows = []
    for institution, date in keys:
        rows.append(
            [
                frame.loc[
                    (institution, (_quarter(date) - feature.lag).end_time.date().isoformat()),
                    feature.metric,
                ]
                for feature in features
            ]
        )
    return np.asarray(rows, dtype=float).reshape(len(rows), len(features))


def _fit_logit(panel, keys, outcomes, score_keys, config, fit):
    """Pooled binary logit fitted by statsmodels; all scale parameters are training-only."""
    api, version = _load_statsmodels()
    fit["package_version"] = version
    x = _panel_predictors(panel, keys, config.features)
    current = _panel_predictors(panel, score_keys, config.features)
    with np.errstate(over="raise", invalid="raise", divide="raise"):
        center, scale = x.mean(axis=0), x.std(axis=0, ddof=0)
        fit.update(normalization_mean=center, normalization_scale=scale)
        if np.any(scale <= 0):
            return None, "Constant configured logit feature; no feature was removed"
        design = np.column_stack((np.ones(len(x)), (x - center) / scale))
        score_design = np.column_stack((np.ones(len(current)), (current - center) / scale))
        diagnostics, reason = _design_diagnostics(design, config.max_condition_number)
        fit.update(diagnostics)
        if reason:
            return None, reason
        with warnings.catch_warnings(record=True) as caught:
            warnings.simplefilter("always")
            fit["fit_attempted"] = True
            model = api.Logit(
                np.asarray(outcomes, dtype=float), design, missing="raise", check_rank=True
            )
            result = model.fit(
                method="newton",
                maxiter=config.max_iterations,
                tol=config.convergence_tolerance,
                disp=False,
                full_output=True,
            )
        fit["warnings"] = tuple(f"{w.category.__name__}: {w.message}" for w in caught)
        fit["converged"] = bool(result.mle_retvals.get("converged", False))
        fit["iterations"] = result.mle_retvals.get("iterations")
        if not fit["converged"]:
            return None, "Logit failed to converge under the registered iteration budget"
        if any(
            issubclass(w.category, RuntimeWarning)
            or w.category.__name__
            in {"PerfectSeparationWarning", "ConvergenceWarning", "HessianInversionWarning"}
            for w in caught
        ):
            return None, "Logit numerical/convergence warning: " + "; ".join(fit["warnings"])
        information = -np.asarray(model.hessian(result.params))
        condition = float(np.linalg.cond(information))
        eigenvalues = np.linalg.eigvalsh(information)
        fit.update(
            information_condition_number=condition,
            information_minimum_eigenvalue=float(eigenvalues.min()),
        )
        if (
            not np.isfinite(result.params).all()
            or not np.isfinite(information).all()
            or not np.isfinite(condition)
            or condition > config.max_condition_number
            or eigenvalues.min() <= np.finfo(float).eps * max(1.0, eigenvalues.max())
        ):
            return None, "Logit information matrix is unidentified or materially ill-conditioned"
        scores = np.asarray(result.predict(score_design))
        if not np.isfinite(scores).all():
            return None, "Non-finite logit probabilities"
        fit.update(
            coefficients=result.params,
            coefficient_rows=("intercept",) + tuple(f.name for f in config.features),
            coefficient_units="training-standardized predictors; log-odds",
            scoring_predictors=current,
            log_likelihood=float(result.llf),
        )
        return scores, None


def walk_forward_panel_logit(
    store,
    registry,
    *,
    reviews,
    labels,
    config: PanelLogitConfig,
    policy_context=None,
    institution_classes=None,
    allow_synthetic=False,
):
    """Build raw ``SupervisoryPanelDataset`` snapshots and refit at every review.

    The fixed institution scope and calendar window are never shortened to make
    fitting succeed. Only explicitly labeled earlier target quarters whose labels
    were available *before* this review can enter the likelihood. Missing labels
    are counted, not inferred. No current-quarter outcomes enter training.
    """
    reviews = _reviews(reviews, config)
    labels = tuple(labels)
    results = []
    variables = tuple(dict.fromkeys(f.metric for f in config.features))
    for review in reviews:
        cutoff = (instant(review.as_of) - timedelta(microseconds=1)).isoformat()
        target = _quarter(review.reporting_period)
        training_dates = _periods(target - 1, config.training_periods)
        source_dates = _periods(
            target - 1, config.training_periods + max(f.lag for f in config.features)
        )
        label_map = _labels_as_of(labels, config.event_definition, cutoff)
        keys = tuple((i, d) for i in config.institutions for d in training_dates)
        used_labels = tuple(
            label_map[k] for k in keys if k in label_map and label_map[k].value is not None
        )
        used_keys = tuple((label.institution_id, label.reporting_period) for label in used_labels)
        outcomes = tuple(label.value for label in used_labels)
        records: List[Any] = []
        definitions: List[Any] = []
        events: List[Any] = []
        frames: List[Any] = []
        reasons: List[str] = []
        for institution in config.institutions:
            try:
                frame, facts, meanings = _snapshot(
                    store,
                    registry,
                    institution,
                    config.form,
                    variables,
                    source_dates + (review.reporting_period,),
                    cutoff,
                    allow_synthetic,
                )
                records.extend(facts)
                definitions.extend(meanings)
                breaks, relevant = _comparability(
                    facts,
                    variables,
                    policy_context,
                    cutoff,
                    config.form,
                    source_dates + (review.reporting_period,),
                    (institution_classes or {}).get(institution),
                )
                reasons.extend(f"{institution}: {r}" for r in breaks)
                events.extend(relevant)
            except ValueError as exc:
                reasons.append(f"{institution}: data unavailable: {exc}")
                frame = pd.DataFrame(index=source_dates, columns=variables, dtype=float)
            frame = frame.copy()
            frame = frame.reindex(source_dates)
            frame["institution_id"] = institution
            frame["reporting_period"] = source_dates
            frames.append(frame)
        # Direct construction avoids the legacy adapter's retrospective cleaning.
        panel = SupervisoryPanelDataset(
            frame=pd.concat(frames, ignore_index=True),
            institution_column="institution_id",
            date_column="reporting_period",
            metric_columns=variables,
            peer_group_column=None,
            sampling_rate=4.0,
            metadata={
                "as_of": cutoff,
                "standardize": False,
                "interpolate": False,
                "transform": "level",
            },
        )
        unique_definitions = tuple({stable_id(d): d for d in definitions}.values())
        unique_events = tuple({e.event_id: e for e in events}.values())
        pooling_breaks, _ = _comparability(
            records, variables, None, cutoff, config.form, source_dates, None
        )
        reasons.extend(f"Panel pooling: {reason}" for reason in pooling_breaks)
        info = _information(
            review,
            config,
            cutoff,
            training_dates,
            records,
            unique_definitions,
            labels=used_labels,
            events=unique_events,
        )
        info.update(
            institutions=config.institutions,
            features=canonical(config.features),
            lag_history_start=source_dates[0],
            training_row_keys=used_keys,
            allow_synthetic=allow_synthetic,
            institution_classes=tuple(
                (i, (institution_classes or {}).get(i)) for i in config.institutions
            ),
        )
        missing = ~np.isfinite(panel.frame[list(variables)].to_numpy(dtype=float))
        # A rectangular panel includes padding for features whose lags differ.
        # Only cells referenced by the fixed training/scoring designs are required.
        required_dates = {
            metric: {
                (_quarter(date) - feature.lag).end_time.date().isoformat()
                for feature in config.features
                if feature.metric == metric
                for date in training_dates + (review.reporting_period,)
            }
            for metric in variables
        }
        required = np.asarray(
            [
                [date in required_dates[metric] for metric in variables]
                for date in panel.frame[panel.date_column]
            ],
            dtype=bool,
        )
        missing_required = missing & required
        n, positives = len(outcomes), int(sum(outcomes))
        fit: Dict[str, Any] = dict(
            package="statsmodels",
            package_version=None,
            link="logit",
            optimizer="newton",
            coefficient_inference="not_reported",
            configured_training_rows=len(keys),
            labeled_observation_count=n,
            event_count=positives,
            nonevent_count=n - positives,
            event_fraction=positives / n if n else None,
            unlabeled_observation_count=len(keys) - n,
            usable_observation_count=0,
            usable_institution_count=0,
            missing_cells=int(missing_required.sum()),
            missing_cells_by_metric=dict(zip(variables, missing_required.sum(axis=0).tolist())),
            unused_missing_cells=int((missing & ~required).sum()),
            converged=None,
            iterations=None,
            fit_attempted=False,
        )
        x = _panel_predictors(panel, used_keys, config.features)
        complete = np.isfinite(x).all(axis=1)
        fit["usable_observation_count"] = int(complete.sum())
        fit["usable_institution_count"] = len({k[0] for k, ok in zip(used_keys, complete) if ok})
        if missing_required.any():
            reasons.append(
                "Insufficient history or missing/non-finite required features in the exact configured panel window"
            )
        if n < max(config.minimum_observations, len(config.features) + 2):
            reasons.append("Too few usable labeled observations")
        if positives < config.minimum_events or n - positives < config.minimum_nonevents:
            reasons.append("Too few explicitly labeled events or non-events")
        if fit["usable_institution_count"] < config.minimum_institutions:
            reasons.append("Too few usable institutions")
        reason = "; ".join(reasons) or None
        scores = None
        score_keys = tuple((i, review.reporting_period) for i in config.institutions)
        if reason is None:
            try:
                scores, reason = _fit_logit(panel, used_keys, outcomes, score_keys, config, fit)
            except ImportError as exc:
                reason = f"Optional econometrics dependency unavailable: {exc}"
            except (ValueError, np.linalg.LinAlgError, FloatingPointError, OverflowError) as exc:
                if fit["fit_attempted"]:
                    fit["converged"] = False
                reason = f"Logit estimation withheld: {type(exc).__name__}: {exc}"
            # PerfectSeparationError inherits Exception rather than ValueError.
            except Exception as exc:
                if type(exc).__name__ != "PerfectSeparationError":
                    raise
                fit["converged"] = False
                reason = f"Logit separation: {exc}"
        for index, institution in enumerate(config.institutions):
            results.append(
                _result(
                    "panel_logit",
                    institution,
                    review,
                    config,
                    info,
                    fit,
                    reason,
                    None if reason or scores is None else float(scores[index]),
                )
            )
    return tuple(results)

"""Local CLI and loopback-only analyst review server. No telemetry or cloud service."""

from __future__ import annotations

import argparse
