            "false": "Contradictory evidence is absent or not materially important to interpreting the stated claim.",
        },
    ),
    _question(
        "review_complexity",
        "choice",
        "How complex is this evidence packet for a human analyst to review?",
        {
            "routine": "A trained analyst can review this packet with ordinary effort.",
            "moderate": "The packet needs careful reading across several evidence sections.",
            "complex": "The packet is dense, multi-part, or difficult for a human analyst to review carefully.",
        },
    ),
    _question(
        "limitations_material",
        "noul",
        "The documented limitations materially constrain interpretation of this claim.",
        {
            "true": "The documented limitations materially constrain interpretation of the stated claim.",
            "false": "The documented limitations do not materially constrain interpretation of the stated claim.",
        },
    ),
    _question(
        "additional_review_needed",
        "noul",
        "The evidence contains enough ambiguity, disagreement, limitation, or uncertainty that additional human scrutiny is warranted.",
        {
            "true": "Ambiguity, disagreement, limitation, or uncertainty in the packet warrants additional human scrutiny.",
            "false": "The packet does not show enough ambiguity, disagreement, limitation, or uncertainty to warrant additional human scrutiny beyond ordinary review.",
        },
    ),
)
_QUESTIONS_BY_ID = {question.question_id: question for question in EVIDENCE_PACKET_QUESTIONS}


def question_api_payload(questions=EVIDENCE_PACKET_QUESTIONS):
    """Dict form accepted by ``TypeSafeClient.system_one``."""
    return {question.question_id: question.to_api() for question in questions}


@dataclass(frozen=True)
class JudgmentState:
    """Canonical, bounded packet for one evidence entry."""

    payload_json: str
    state_id: str
    evidence_id: str
    analysis_id: Optional[str]
    truncated: bool
    sendable: bool
    failure: Optional[str] = None

    def __post_init__(self):
        sha256_hex(self.state_id)
        if stable_id(json.loads(self.payload_json)) != self.state_id:
            raise ValueError("Judgment state hash does not match its payload")

    @property
    def payload(self):
        return json.loads(self.payload_json)


@dataclass(frozen=True)
class TypedAnswer:
    """One primitive answer. Noul carries no separate confidence."""

    question_id: str
    primitive: str
    choice: Optional[str] = None
    score: Optional[float] = None
    noul: Optional[float] = None
    probabilities: Optional[Tuple[Tuple[str, float], ...]] = None
    confidence: Optional[float] = None
    legend: Optional[Tuple[Tuple[str, object], ...]] = None

    def __post_init__(self):
        if self.primitive not in {"choice", "score", "noul"}:
            raise ValueError("Unsupported judgment primitive")
        if self.probabilities is not None:
            object.__setattr__(
                self,
                "probabilities",
                tuple((str(key), float(value)) for key, value in self.probabilities),
            )
        if self.legend is not None:
            object.__setattr__(
                self, "legend", tuple((str(key), value) for key, value in self.legend)
            )
        if self.primitive == "noul" and self.confidence is not None:
            raise ValueError("Noul answers do not carry a confidence value")


@dataclass(frozen=True)
class JudgmentResult:
    schema_version: str
    provider: str
    model: str
    provider_model_version: Optional[str]
    question_set_version: str
    evidence_id: str
    analysis_id: Optional[str]
    state_hash: str
    state_truncated: bool
    answers: Tuple[TypedAnswer, ...]
    requested_at: str
    completed_at: str
    latency_ms: float
    provider_status: str
    limitations: Tuple[str, ...]

    def __post_init__(self):
        sha256_hex(self.state_hash)
        if self.provider_status not in _PROVIDER_STATUSES:
            raise ValueError("Invalid judgment provider status")
        if not self.evidence_id or not self.schema_version:
            raise ValueError("Judgment result requires evidence and a schema version")
        object.__setattr__(self, "answers", tuple(self.answers))
        object.__setattr__(self, "limitations", tuple(str(item) for item in self.limitations))
        if any(not isinstance(answer, TypedAnswer) for answer in self.answers):
            raise ValueError("Judgment answers must be typed")
        try:
            latency = float(self.latency_ms)
        except (TypeError, ValueError):
            raise ValueError("Judgment latency must be finite") from None
        if isinstance(self.latency_ms, bool) or latency < 0 or latency != latency:
            raise ValueError("Judgment latency must be finite")
        object.__setattr__(self, "latency_ms", latency)

    @property
    def judgment_id(self):
        """Content hash. Timestamps and latency are audit fields, not identity."""
        body = canonical(self)
        for key in ("requested_at", "completed_at", "latency_ms"):
            body.pop(key, None)
        return stable_id(body)


@dataclass(frozen=True)
class JudgmentOverlay:
    evidence_id: str
    judgment_result: JudgmentResult
    review_complexity: Optional[str]
    warnings: Tuple[str, ...]
    policy_outcome: str
    policy_version: str

    def __post_init__(self):
        if self.evidence_id != self.judgment_result.evidence_id:
            raise ValueError("Judgment overlay is bound to one evidence record")
        allowed = _POLICY_OUTCOMES.get(self.policy_version)
        if allowed is None or self.policy_outcome not in allowed:
            raise ValueError("Invalid judgment policy outcome")
        if self.review_complexity not in {None, "routine", "moderate", "complex"}:
            raise ValueError("Invalid review complexity")
        object.__setattr__(self, "warnings", tuple(self.warnings))


class JudgmentResponseError(ValueError):
    def __init__(self, status, limitation):
        super().__init__(limitation)
        self.status = status
        self.limitation = limitation


def _pair_map(value):
    if not isinstance(value, Mapping) or not value:
        raise JudgmentResponseError("malformed_response", "Probabilities must be a nonempty object")
    pairs = []
    for key in sorted(value, key=str):
        try:
            number = float(value[key])
        except (TypeError, ValueError):
            raise JudgmentResponseError(
                "malformed_response", "Probability values must be numeric"
            ) from None
        if isinstance(value[key], bool) or not 0.0 <= number <= 1.0:
            raise JudgmentResponseError("malformed_response", "Probability values must be in [0,1]")
        pairs.append((str(key), number))
    return tuple(pairs)


def _confidence(value):
    try:
        number = float(value)
    except (TypeError, ValueError):
        raise JudgmentResponseError(
            "missing_fields", "Choice or score confidence is missing"
        ) from None
    if isinstance(value, bool) or not 0.0 <= number <= 1.0:
        raise JudgmentResponseError("malformed_response", "Confidence must be in [0,1]")
    return number


def _answer_dict(value):
    if isinstance(value, Mapping):
        return dict(value)
    if hasattr(value, "model_dump"):
        return value.model_dump()
    kind = getattr(value, "type", None)
    if kind == "choice":
        return {
            "type": "choice",
            "choice": getattr(value, "choice", None),
            "probabilities": getattr(value, "probabilities", None),
            "confidence": getattr(value, "confidence", None),
        }
    if kind == "score":
        return {
            "type": "score",
            "score": getattr(value, "score", None),
            "probabilities": getattr(value, "probabilities", None),
            "confidence": getattr(value, "confidence", None),
            "legend": getattr(value, "legend", None),
        }
    if kind == "noul":
        return {"type": "noul", "noul": getattr(value, "noul", None)}
    raise JudgmentResponseError("unsupported_primitive", "Answer primitive is not supported")


def parse_typed_answer(question_id, value, questions=_QUESTIONS_BY_ID):
    """Parse one official Choice, Score, or Noul answer without inventing fields."""
    body = _answer_dict(value)
    kind = body.get("type")
    expected = questions.get(question_id)
    if kind not in {"choice", "score", "noul"}:
        raise JudgmentResponseError("unsupported_primitive", "Answer primitive is not supported")
    if expected is not None and expected.primitive != kind:
        raise JudgmentResponseError(
            "unsupported_primitive", "Answer primitive does not match the question"
        )
    if kind == "noul":
        if "noul" not in body or body.get("noul") is None:
            raise JudgmentResponseError("missing_fields", "Noul answer is missing noul")
        try:
            probability = float(body["noul"])
        except (TypeError, ValueError):
            raise JudgmentResponseError("malformed_response", "Noul must be numeric") from None
        if isinstance(body["noul"], bool) or not 0.0 <= probability <= 1.0:
            raise JudgmentResponseError("malformed_response", "Noul must be in [0,1]")
        return TypedAnswer(question_id, "noul", noul=probability, confidence=None)
    if kind == "choice":
        if "choice" not in body or "probabilities" not in body or "confidence" not in body:
            raise JudgmentResponseError("missing_fields", "Choice answer is incomplete")
        probabilities = _pair_map(body["probabilities"])
        selected = body["choice"]
        if not isinstance(selected, str) or selected not in dict(probabilities):
            raise JudgmentResponseError("malformed_response", "Choice is outside its probabilities")
        if expected is not None and selected not in expected.criteria:
            raise JudgmentResponseError(
                "malformed_response", "Choice is outside the question criteria"
            )
        return TypedAnswer(
            question_id,
            "choice",
            choice=selected,
            probabilities=probabilities,
            confidence=_confidence(body["confidence"]),
        )
    if "score" not in body or "probabilities" not in body or "confidence" not in body:
        raise JudgmentResponseError("missing_fields", "Score answer is incomplete")
    try:
        score = float(body["score"])
    except (TypeError, ValueError):
        raise JudgmentResponseError("malformed_response", "Score must be numeric") from None
    if isinstance(body["score"], bool) or score != score:
        raise JudgmentResponseError("malformed_response", "Score must be numeric")
    legend = body.get("legend")
    legend_pairs = None
    if legend is not None:
        if not isinstance(legend, Mapping):
            raise JudgmentResponseError("malformed_response", "Score legend must be an object")
        legend_pairs = tuple((str(key), legend[key]) for key in sorted(legend, key=str))
    return TypedAnswer(
        question_id,
        "score",
        score=score,
        probabilities=_pair_map(body["probabilities"]),
        confidence=_confidence(body["confidence"]),
        legend=legend_pairs,
    )


def parse_system_one_response(payload, questions=EVIDENCE_PACKET_QUESTIONS):
    """Parse a System One response object or dict. Question ids stay with our code."""
    if hasattr(payload, "model") and hasattr(payload, "answers"):
        model = payload.model
        raw_answers = payload.answers
    elif isinstance(payload, Mapping):
        model = payload.get("model")
        raw_answers = payload.get("answers")
    else:
        raise JudgmentResponseError("malformed_response", "Response is not a System One object")
    if not isinstance(model, str) or not model.strip():
        raise JudgmentResponseError("missing_fields", "Response model version is missing")
    if not isinstance(raw_answers, Mapping):
        raise JudgmentResponseError("missing_fields", "Response answers are missing")
    expected = tuple(questions)
    missing = [
        question.question_id for question in expected if question.question_id not in raw_answers
    ]
    if missing:
        raise JudgmentResponseError("missing_fields", "Response is missing a requested answer")
    answers = tuple(
        parse_typed_answer(
            question.question_id, raw_answers[question.question_id], _QUESTIONS_BY_ID
        )
        for question in expected
    )
    return model, answers


def display_policy_outcome(outcome):
    """Human label for a policy token. Legacy v1 READY is shown as reviewable evidence."""
    token = "EVIDENCE_REVIEWABLE" if outcome == "READY" else (outcome or "JUDGMENT_UNAVAILABLE")
    return str(token).replace("_", " ")


def apply_judgment_policy(result, *, threshold=NOUL_MATERIAL_THRESHOLD):
    """Map typed answers to a presentation outcome. This does not rank attention."""
    if result.provider_status != "completed":
        return (
            "JUDGMENT_UNAVAILABLE",
            (f"provider_status={result.provider_status}",),
            None,
        )
    by_id = {answer.question_id: answer for answer in result.answers}
    if set(_QUESTIONS_BY_ID) - set(by_id):
        return ("JUDGMENT_UNAVAILABLE", ("incomplete question set",), None)
    adequacy = by_id["evidence_adequacy"]
    complexity = by_id["review_complexity"]
    if (
        adequacy.primitive != "choice"
        or adequacy.choice not in {"adequate", "limited", "insufficient"}
        or complexity.primitive != "choice"
        or complexity.choice not in {"routine", "moderate", "complex"}
    ):
        return ("JUDGMENT_UNAVAILABLE", ("invalid choice answer",), None)
    warnings = []
    for question_id in (
        "scope_overreach",
        "contradiction_material",
        "limitations_material",
        "additional_review_needed",
    ):
        answer = by_id[question_id]
        if answer.primitive != "noul" or answer.noul is None or answer.confidence is not None:
            return ("JUDGMENT_UNAVAILABLE", (f"invalid {question_id}",), None)
        if answer.noul > threshold:
            warnings.append(f"{question_id}={answer.noul:.4f} exceeds {threshold}")
    warning_text = tuple(warnings)
    if adequacy.choice == "insufficient":
        return ("INSUFFICIENT_EVIDENCE", warning_text, complexity.choice)
    if adequacy.choice == "limited" or warning_text:
        if adequacy.choice == "limited" and not warning_text:
            warning_text = ("evidence_adequacy=limited",)
        return ("REVIEW_CAREFULLY", warning_text, complexity.choice)
    return ("EVIDENCE_REVIEWABLE", (), complexity.choice)


def assemble_overlay(result):
    outcome, warnings, complexity = apply_judgment_policy(result)
    return JudgmentOverlay(
        result.evidence_id,
        result,
        complexity,
        warnings,
        outcome,
        JUDGMENT_POLICY_VERSION,
    )


def _safe_limitations(items, secrets):
    cleaned = []
    for item in items:
        text = _redact_text(str(item), secrets)
        if len(text) > 240:
            text = text[:240]
        cleaned.append(text)
    return tuple(cleaned)


def make_result(
    state,
    *,
    provider,
    model,
    provider_model_version,
    status,
    answers=(),
    limitations=(),
    requested_at,
    completed_at,
    latency_ms,
    secrets=(),
):
    return JudgmentResult(
        RESULT_SCHEMA_VERSION,
        provider,
        model,
        provider_model_version,
        QUESTION_SET_VERSION,
        state.evidence_id,
        state.analysis_id,
        state.state_id,
        state.truncated,
        tuple(sorted(answers, key=lambda answer: answer.question_id)),
        requested_at,
        completed_at,
        latency_ms,
        status,
        _safe_limitations(limitations, secrets),
    )


def classify_provider_failure(exc):
    """Map TypeSafe SDK failures by type or HTTP status. Messages are not retained."""
    name = type(exc).__name__
    status = getattr(exc, "status", None)
    if name == "TypeSafeAPITimeoutError" or isinstance(exc, TimeoutError):
        return "timeout"
    if name == "TypeSafeAuthenticationError" or status == 401:
        return "authentication_error"
    if name == "TypeSafeRateLimitError" or status == 429:
        return "rate_limit"
    if name == "TypeSafeAPIConnectionError" or isinstance(exc, ConnectionError):
        return "network_error"
    if name == "TypeSafeAPIResponseValidationError":
        return "missing_fields"
    if name in {"TypeSafeBadRequestError", "TypeSafeUnprocessableEntityError"} or status in {
        400,
        422,
    }:
        return "malformed_response"
    if name == "TypeSafeInternalServerError" or (isinstance(status, int) and 500 <= status <= 599):
        return "service_failure"
    if isinstance(exc, (json.JSONDecodeError, UnicodeError)):
        return "malformed_response"
    if name == "TypeSafeError":
        return "missing_credentials"
    return "service_failure"


_STATUS_LIMITATIONS = {
    "disabled": "Typed judgment provider is disabled.",
    "unavailable": "Typed judgment is unavailable.",
    "authentication_error": "Judgment provider authentication failed.",
    "timeout": "Judgment provider timed out.",
    "rate_limit": "Judgment provider rate limit was reached.",
    "network_error": "Judgment provider network request failed.",
    "service_failure": "Judgment provider failed.",
    "malformed_response": "Judgment provider returned a malformed response.",
    "missing_fields": "Judgment provider response is missing required fields.",
    "unsupported_primitive": "Judgment provider returned an unsupported primitive.",
    "oversized_state": "Judgment state exceeds the bounded packet size and was not sent.",
    "serialization_failure": "Judgment state could not be serialized and was not sent.",
    "missing_credentials": "TYPESAFE_API_KEY is missing or invalid.",
}


class JudgmentProvider:
    """Narrow evaluate interface. Workbench code depends on this, not on a vendor SDK."""

    name = "unspecified"

    def evaluate(self, state, questions):
        raise NotImplementedError


class DisabledJudgmentProvider(JudgmentProvider):
    name = "disabled"

    def __init__(self, clock: Callable[[], str] = _clock_now):
        self.clock = clock

    def evaluate(self, state, questions):
        moment = self.clock()
        return make_result(
            state,
            provider=self.name,
            model="",
            provider_model_version=None,
            status="disabled",
            limitations=(_STATUS_LIMITATIONS["disabled"],),
            requested_at=moment,
            completed_at=moment,
            latency_ms=0.0,
        )


class DeterministicMockJudgmentProvider(JudgmentProvider):
    """Offline answers that are a pure function of the state hash. Not a remote model."""

    name = "mock"

    def __init__(
        self,
        clock: Optional[Callable[[], str]] = None,
        script: Optional[Sequence[TypedAnswer]] = None,
    ):
        self.clock = clock if clock is not None else (lambda: "2026-01-15T00:00:00+00:00")
        self.script = None if script is None else tuple(script)
        self.calls: List[str] = []

    def evaluate(self, state, questions):
        self.calls.append(state.evidence_id)
        moment = self.clock()
        if not state.sendable:
            status = state.failure or "serialization_failure"
            return make_result(
                state,
                provider=self.name,
                model="deterministic-mock",
                provider_model_version="mock-v1",
                status=status,
                limitations=(_STATUS_LIMITATIONS.get(status, _STATUS_LIMITATIONS["unavailable"]),),
                requested_at=moment,
                completed_at=moment,
                latency_ms=0.0,
            )
        answers = self.script if self.script is not None else _mock_answers(state)
        return make_result(
            state,
            provider=self.name,
            model="deterministic-mock",
            provider_model_version="mock-v1",
            status="completed",
            answers=answers,
            limitations=("Deterministic offline stand-in. Not a TypeSafe model response.",),
            requested_at=moment,
            completed_at=moment,
            latency_ms=0.0,
        )


def _choice(question_id, selected, probabilities, confidence):
    ordered = tuple(sorted((str(key), float(value)) for key, value in probabilities.items()))
    return TypedAnswer(
        question_id,
        "choice",
        choice=selected,
        probabilities=ordered,
        confidence=confidence,
    )


def _noul(question_id, probability):
    return TypedAnswer(question_id, "noul", noul=probability, confidence=None)


def _mock_answers(state):
    nudge = int(state.state_id[:2], 16) / 10000.0
    probability = round(0.05 + nudge, 6)
    return (
        _choice(
            "evidence_adequacy",
            "adequate",
            {"adequate": 0.8, "insufficient": 0.05, "limited": 0.15},
            0.7,
        ),
        _noul("scope_overreach", probability),
        _noul("contradiction_material", probability),
        _choice(
            "review_complexity",
            "moderate",
            {"complex": 0.1, "moderate": 0.75, "routine": 0.15},
            0.66,
        ),
        _noul("limitations_material", probability),
        _noul("additional_review_needed", probability),
    )


class TypeSafeJudgmentProvider(JudgmentProvider):
    """Optional Jev client. Constructing it does not open a connection."""

    name = "typesafe"

    def __init__(
        self,
        *,
        model="jev-latest",
        timeout=10.0,
        client=None,
        clock: Callable[[], str] = _clock_now,
    ):
        if not isinstance(model, str) or not re.fullmatch(r"[A-Za-z0-9._-]{1,80}", model):
            raise ValueError("Invalid TypeSafe model alias")
        self.model = model
        self.timeout = timeout
        self.client = client
        self.clock = clock

    def evaluate(self, state, questions):
        requested = self.clock()
        started = time.perf_counter()
        secrets = active_secret_values()

        def finish(status, answers=(), model_version=None, limitations=None):
            if limitations is None:
                limitations = () if status == "completed" else (_STATUS_LIMITATIONS[status],)
            return make_result(
                state,
                provider=self.name,
                model=self.model,
                provider_model_version=model_version,
                status=status,
                answers=answers,
                limitations=limitations,
                requested_at=requested,
                completed_at=self.clock(),
                latency_ms=(time.perf_counter() - started) * 1000.0,
                secrets=secrets,
            )

        if not state.sendable:
            status = (
                state.failure if state.failure in _STATUS_LIMITATIONS else "serialization_failure"
            )
            return finish(status)
        client = self.client
        opened = False
        try:
            if client is None:
                if not secrets and not str(os.environ.get("TYPESAFE_API_KEY", "")).strip():
                    return finish("missing_credentials")
                try:
                    from typesafe_sdk import RetryPolicy, TypeSafeClient
                except ImportError:
                    return finish(
                        "unavailable",
                        limitations=(
                            "typesafe-sdk is not installed; the evidence packet was not sent.",
                        ),
                    )
                try:
                    client = TypeSafeClient(
                        model=self.model, timeout=self.timeout, retry=_no_retry(RetryPolicy)
                    )
                except Exception as exc:
                    return finish(classify_provider_failure(exc))
                opened = True
            response = client.system_one(
                state=state.payload,
                questions=question_api_payload(questions),
                model=self.model,
                timeout=self.timeout,
                retry=_retry_override(client),
            )
            model_version, answers = parse_system_one_response(response, questions)
        except JudgmentResponseError as exc:
            return finish(exc.status, limitations=(exc.limitation,))
        except Exception as exc:
            return finish(classify_provider_failure(exc))
        finally:
            if opened:
                client.close()
        return finish("completed", answers=answers, model_version=model_version, limitations=())


def _no_retry(retry_policy):
    return retry_policy(max_retries=0)


def _retry_override(client):
    """Disable SDK retries when the caller did not inject a client policy."""
    try:
        from typesafe_sdk import RetryPolicy
    except ImportError:
        return None
    if client is None:
        return None
    return RetryPolicy(max_retries=0)


def build_judgment_provider(config, *, client=None, clock=None):
    if config.judgment_provider == "disabled":
        return DisabledJudgmentProvider(clock=clock or _clock_now)
    if config.judgment_provider == "mock":
        return DeterministicMockJudgmentProvider(clock=clock)
    if config.judgment_provider == "typesafe":
        return TypeSafeJudgmentProvider(
            model=config.judgment_model,
            timeout=config.judgment_timeout_seconds,
            client=client,
            clock=clock or _clock_now,
        )
    raise ValueError("Unknown judgment provider")


def _section(payload, key, secrets):
    if key not in payload:
        return None
    return _scrub(payload[key], secrets)


def build_judgment_state(
    entry, *, analysis_id=None, as_of=None, max_characters=JUDGMENT_STATE_MAX_CHARACTERS
):
    """Serialize one evidence entry. Unrelated ledger rows and analyst reviews are not inputs."""
    secrets = active_secret_values()
    try:
        payload = entry.payload
        facts = []
        for fact in payload.get("source_facts", ()):
            row = {}
            for key in _FACT_KEYS:
                if key in fact and not _sensitive_key(key):
                    row[key] = _scrub(fact[key], secrets)
            facts.append(row)
        calculation = payload.get("calculation") or {}
        calculation_body = {
            key: _scrub(calculation[key], secrets)
            for key in _CALC_KEYS
            if key in calculation and not _sensitive_key(key)
        }
        state = {
            "schema_version": STATE_SCHEMA_VERSION,
            "evidence_id": entry.evidence_id,
            "analysis_id": analysis_id,
            "as_of": as_of or payload.get("evidence_available_as_of"),
            "source_ids": sorted(
                {row["observation_id"] for row in facts if row.get("observation_id")}
            ),
            "source_vintages": sorted(
                {row["source_vintage"] for row in facts if row.get("source_vintage")}
            ),
            "robustness_status": (
                (payload.get("robustness") or {}).get("classification")
                if isinstance(payload.get("robustness"), Mapping)
                else None
            ),
            "claim": _scrub(payload.get("claim"), secrets),
            "source_facts": facts,
            "calculation": calculation_body,
            "historical_context": _section(payload, "historical_context", secrets),
            "peer_context": _section(payload, "peer_context", secrets),
            "baseline_evidence": _section(payload, "baseline_evidence", secrets),
            "drr_evidence": _section(payload, "drr_evidence", secrets),
            "robustness": _section(payload, "robustness", secrets),
            "contradictory_evidence": _section(payload, "contradictory_evidence", secrets),
            "data_limitations": _section(payload, "data_limitations", secrets),
            "policy_context": _section(payload, "policy_context", secrets),
            "decision_boundary": _scrub(payload.get("decision_boundary"), secrets),
            "truncation": {
                "truncated": False,
                "max_characters": max_characters,
                "omitted": [],
            },
        }
        omitted = []
        if len(canonical_json(state)) > max_characters:
            for field in _TRUNCATE_FIELDS:
                if len(canonical_json(state)) <= max_characters:
                    break
                state[field] = {"truncated": True, "field": field}
                omitted.append(field)
            state["truncation"] = {
                "truncated": True,
                "max_characters": max_characters,
                "omitted": omitted,
            }
        encoded = canonical_json(state)
        try:
            assert_no_secrets(encoded, secrets)
        except ValueError:
            return _withheld_state(entry.evidence_id, analysis_id, "serialization_failure")
        sendable = len(encoded) <= max_characters
        failure = None if sendable else "oversized_state"
        return JudgmentState(
            encoded,
            stable_id(json.loads(encoded)),
            entry.evidence_id,
            analysis_id,
            bool(omitted) or not sendable,
            sendable,
            failure,
        )
    except (TypeError, KeyError) as exc:
        marker = {
            "schema_version": STATE_SCHEMA_VERSION,
            "evidence_id": getattr(entry, "evidence_id", ""),
            "analysis_id": analysis_id,
            "serialization": "serialization_failure",
            "reason": type(exc).__name__,
        }
        encoded = canonical_json(marker)
        return JudgmentState(
            encoded,
            stable_id(marker),
            marker["evidence_id"],
            analysis_id,
            False,
            False,
            "serialization_failure",
        )


def _withheld_state(evidence_id, analysis_id, failure):
    marker = {
        "schema_version": STATE_SCHEMA_VERSION,
        "evidence_id": evidence_id,
        "analysis_id": analysis_id,
        "serialization": failure,
    }
    encoded = canonical_json(marker)
    return JudgmentState(
        encoded,
        stable_id(marker),
        evidence_id,
        analysis_id,
        False,
        False,
        failure,
    )


def judge_selected_evidence(
    provider, attention_items, *, ledger, analysis_id, as_of, questions=EVIDENCE_PACKET_QUESTIONS
):
    """Judge attention selections only. Evidence must already exist in the ledger."""
    overlays = []
    for item in attention_items:
        signal = item.signal if hasattr(item, "signal") else item["signal"]
        evidence_id = (
            signal.evidence_id if hasattr(signal, "evidence_id") else signal["evidence_id"]
        )
        entry = ledger.get(evidence_id)
        state = build_judgment_state(entry, analysis_id=analysis_id, as_of=as_of)
        try:
            result = provider.evaluate(state, questions)
        except Exception:
            moment = _clock_now()
            result = make_result(
                state,
                provider=getattr(provider, "name", "unknown"),
                model="",
                provider_model_version=None,
                status="service_failure",
                limitations=(_STATUS_LIMITATIONS["service_failure"],),
                requested_at=moment,
                completed_at=moment,
                latency_ms=0.0,
            )
        if result.evidence_id != entry.evidence_id or result.state_hash != state.state_id:
            moment = result.completed_at
            result = make_result(
                state,
                provider=result.provider,
                model=result.model,
                provider_model_version=result.provider_model_version,
                status="malformed_response",
                limitations=("Judgment result did not bind to the supplied evidence state.",),
                requested_at=result.requested_at,
                completed_at=moment,
                latency_ms=result.latency_ms,
            )
        overlay = assemble_overlay(result)
        ledger.append_judgment(overlay)
        overlays.append(overlay)
    ordered = tuple(sorted(overlays, key=lambda overlay: overlay.evidence_id))
    return {
        "schema_version": BUNDLE_SCHEMA_VERSION,
        "enabled": True,
        "provider": getattr(provider, "name", "unknown"),
        "model": ordered[0].judgment_result.model if ordered else "",
        "question_set_version": QUESTION_SET_VERSION,
        "policy_version": JUDGMENT_POLICY_VERSION,
        "analysis_id": analysis_id,
        "evidence_ids": tuple(overlay.evidence_id for overlay in ordered),
        "artifact_hashes": tuple(overlay.judgment_result.judgment_id for overlay in ordered),
        "replay": _REPLAY_NOTE,
        "historical_use": POST_HOC_JUDGMENT_EVALUATION,
        "overlays": {overlay.evidence_id: canonical(overlay) for overlay in ordered},
    }


def typesafe_model_risk_extension(profile: ModelRiskProfile, *, model: str) -> ModelRiskProfile:
    """Record the optional remote dependency without assigning a risk tier or validation status."""
    from dataclasses import replace

    return replace(
        profile,
        foreseeable_misuse=profile.foreseeable_misuse
        + (
            "treating typed-judgment probabilities as statistical confidence, model validation, or a supervisory conclusion",
        ),
        limitations=profile.limitations
        + (
            "Optional typed judgment characterizes bounded questions about an evidence packet. It does not validate DRR, rate an institution, or authorize supervisory action.",
            "Remote judgment depends on the TypeSafe provider, the requested model alias, and the model version returned with the response.",
        ),
        use_boundaries=profile.use_boundaries
        + (
            "human interpretation remains authoritative over typed judgment",
            "remote judgment is unsupported for confidential supervisory information",
        ),
        monitoring_plan=profile.monitoring_plan
        + (
            "Compare recorded provider model versions when the judgment alias moves; do not treat a newer model as historical evidence.",
        ),
        change_control=profile.change_control
        + (
            "Question set evidence-packet-v1 and judgment policy v2 are explicit. Policy v2 names the adequate, no-material-Noul outcome EVIDENCE_REVIEWABLE. A provider model version change creates a distinct judgment record.",
        ),
        dependencies=profile.dependencies
        + ("typesafe-sdk optional extra; imported only when the TypeSafe provider runs",),
        third_party_products=profile.third_party_products
        + (
            f"TypeSafe Jev ({model}) optional remote typed judgment; not regulatory approval, independent validation, or a supervisory endorsement",
        ),
    )


def judgment_configuration(config):
    if config.judgment_provider == "typesafe":
        model = config.judgment_model
    elif config.judgment_provider == "mock":
        model = "deterministic-mock"
    else:
        model = "disabled"
    return {
        "enabled": True,
        "provider": config.judgment_provider,
        "model": model,
        "question_set_version": QUESTION_SET_VERSION,
        "policy_version": config.judgment_policy_version,
        "evaluated_after": "AttentionBudget.select",
        "artifact_location": (
            "append-only judgments table and result.judgment; excluded from the analytical monitoring hash"
        ),
        "replay": _REPLAY_NOTE,
    }


def replay_recorded_judgments(ledger, *, as_of=None, evidence_ids=None):
    """Return stored judgments. This function does not construct a provider or a network client."""
    return ledger.judgments(as_of=as_of, evidence_ids=evidence_ids)


def describe_post_hoc_judgment():
    return {
        "label": POST_HOC_JUDGMENT_EVALUATION,
        "historical_evidence": False,
        "note": (
            "A judgment produced after the review date is comparison material. It is not "
            "historical evidence unless a recorded judgment artifact existed at that review date."
        ),
    }


def _pairs(value):
    if value is None:
        return None
    return tuple((str(key), item) for key, item in value)


def judgment_result_from_dict(value):
    answers = tuple(
        TypedAnswer(
            answer["question_id"],
            answer["primitive"],
            answer.get("choice"),
            answer.get("score"),
            answer.get("noul"),
            _pairs(answer.get("probabilities")),
            answer.get("confidence"),
            _pairs(answer.get("legend")),
        )
        for answer in value["answers"]
    )
    return JudgmentResult(
        value["schema_version"],
        value["provider"],
        value["model"],
        value.get("provider_model_version"),
        value["question_set_version"],
        value["evidence_id"],
        value.get("analysis_id"),
        value["state_hash"],
        value["state_truncated"],
        answers,
        value["requested_at"],
        value["completed_at"],
        value["latency_ms"],
        value["provider_status"],
        tuple(value.get("limitations") or ()),
    )


def overlay_from_dict(value):
    result = (
        value["judgment_result"]
        if isinstance(value["judgment_result"], JudgmentResult)
        else judgment_result_from_dict(value["judgment_result"])
    )
    return JudgmentOverlay(
        value["evidence_id"],
        result,
        value.get("review_complexity"),
        tuple(value.get("warnings") or ()),
        value["policy_outcome"],
        value["policy_version"],
    )


def judgment_content(payload):
    """Identity comparison that ignores audit timestamps and latency."""
    data = canonical(payload)
    result = data.get("judgment_result", data)
    for key in ("requested_at", "completed_at", "latency_ms"):
        result.pop(key, None)
    return data

"""Review-state deltas and an explicit analyst attention budget."""

from __future__ import annotations

from dataclasses import dataclass, replace
from numbers import Integral
from typing import Optional, Tuple

from .common import canonical, instant, stable_id


@dataclass(frozen=True)
class MonitoringSignal:
    key: str
    institution: str
    metric: str
    period: str
    claim: str
    evidence_id: str
    materiality: float
    confidence: float
    persistence: int = 0
    peer_divergence: float = 0.0
    robustness: Optional[float] = None
    drr_incremental: bool = False
    disposition: str = "unresolved"
    review_complexity: Optional[str] = None

    def __post_init__(self):
        if not self.evidence_id or not self.key:
            raise ValueError("Analyst-facing signals require evidence")
        if (
            not 0 <= self.materiality <= 100
            or not 0 <= self.confidence <= 1
            or not 0 <= self.peer_divergence <= 1
        ):
            raise ValueError("Invalid signal score/confidence")
        if self.robustness is not None and not 0 <= self.robustness <= 1:
            raise ValueError("Robustness must be in [0,1]")


@dataclass(frozen=True)
class ReviewState:
    as_of: str
    observations: Tuple[Tuple[str, str], ...] = ()
    signals: Tuple[MonitoringSignal, ...] = ()
    exceptions: Tuple[str, ...] = ()
    policy_events: Tuple[str, ...] = ()
    entity_relationships: Tuple[str, ...] = ()
    drr_relationships: Tuple[str, ...] = ()
    failed_relationships: Tuple[str, ...] = ()

    def __post_init__(self):
        instant(self.as_of)
        for name in (
            "observations",
            "signals",
            "exceptions",
            "policy_events",
            "entity_relationships",
            "drr_relationships",
            "failed_relationships",
        ):
            object.__setattr__(self, name, tuple(getattr(self, name)))
        if len({s.key for s in self.signals}) != len(self.signals):
            raise ValueError("Duplicate signal key in review state")
        if any(
            not isinstance(row, (tuple, list))
            or len(row) != 2
            or any(not isinstance(value, str) or not value for value in row)
            for row in self.observations
        ):
            raise ValueError("Review observations require nonempty key/ID pairs")
        object.__setattr__(self, "observations", tuple(tuple(row) for row in self.observations))
        if len(dict(self.observations)) != len(self.observations):
            raise ValueError("Duplicate observation key in review state")

    @property
    def state_id(self):
        return stable_id(self)


@dataclass(frozen=True)
class MonitoringDelta:
    previous_as_of: Optional[str]
    current_as_of: str
    new_observations: Tuple[str, ...]
    changed_observations: Tuple[str, ...]
    new_signals: Tuple[MonitoringSignal, ...]
    strengthened: Tuple[MonitoringSignal, ...]
    weakened: Tuple[MonitoringSignal, ...]
    changed_evidence: Tuple[MonitoringSignal, ...]
    disappeared: Tuple[MonitoringSignal, ...]
    new_exceptions: Tuple[str, ...]
    resolved_exceptions: Tuple[str, ...]
    new_policy_events: Tuple[str, ...]
    entity_changes: Tuple[str, ...]
    new_relationships: Tuple[str, ...]
    failed_relationships: Tuple[str, ...]


def compare_review_states(previous_review_state, current_state):
    prev = previous_review_state or ReviewState(current_state.as_of)
    if instant(current_state.as_of) < instant(prev.as_of):
        raise ValueError("Current review precedes previous state")
    old, new = {s.key: s for s in prev.signals}, {s.key: s for s in current_state.signals}
    po, co = dict(prev.observations), dict(current_state.observations)

    def added(name):
        return tuple(sorted(set(getattr(current_state, name)) - set(getattr(prev, name))))

    return MonitoringDelta(
        previous_review_state.as_of if previous_review_state else None,
        current_state.as_of,
        tuple(sorted(k for k in co if k not in po)),
        tuple(sorted(k for k in co if k in po and co[k] != po[k])),
        tuple(new[k] for k in sorted(new.keys() - old.keys())),
        tuple(
            new[k]
            for k in sorted(new.keys() & old.keys())
            if new[k].materiality > old[k].materiality
        ),
        tuple(
            new[k]
            for k in sorted(new.keys() & old.keys())
            if new[k].materiality < old[k].materiality
        ),
        tuple(
            new[k]
            for k in sorted(new.keys() & old.keys())
            if new[k].evidence_id != old[k].evidence_id and new[k].materiality == old[k].materiality
        ),
        tuple(old[k] for k in sorted(old.keys() - new.keys())),
        added("exceptions"),
        tuple(sorted(set(prev.exceptions) - set(current_state.exceptions))),
        added("policy_events"),
        tuple(sorted(set(prev.entity_relationships) ^ set(current_state.entity_relationships))),
        added("drr_relationships"),
        added("failed_relationships"),
    )


@dataclass(frozen=True)
class AttentionItem:
    signal: MonitoringSignal
    priority: float
    components: Tuple[Tuple[str, float], ...]
    novelty: str


@dataclass(frozen=True)
class AttentionSelection:
    review_first: Tuple[AttentionItem, ...]
    deferred: Tuple[AttentionItem, ...]
    deprioritized: Tuple[MonitoringSignal, ...]


@dataclass(frozen=True)
class AttentionBudget:
    top_n: int = 5
    minimum_materiality: float = 20.0
    minimum_confidence: float = 0.5

    def __post_init__(self):
        if (
            isinstance(self.top_n, bool)
            or not isinstance(self.top_n, Integral)
            or self.top_n < 0
            or not 0 <= self.minimum_materiality <= 100
            or not 0 <= self.minimum_confidence <= 1
        ):
            raise ValueError("Invalid attention budget")

    def select(self, delta):
        candidates = []
        deprioritized = list(delta.weakened + delta.disappeared)
        for novelty, signals in (
            ("new", delta.new_signals),
            ("strengthened", delta.strengthened),
            ("evidence changed", delta.changed_evidence),
        ):
            for signal in signals:
                if (
                    signal.materiality < self.minimum_materiality
                    or signal.confidence < self.minimum_confidence
                    or signal.disposition in {"useful", "explained", "noisy", "dismissed"}
                ):
                    deprioritized.append(signal)
                    continue
                components = (
                    ("materiality", signal.materiality * 0.45),
                    ("novelty", 15.0 if novelty == "new" else 8.0),
                    ("persistence", min(signal.persistence, 4) * 2.0),
                    ("peer_divergence", signal.peer_divergence * 10),
                    ("robustness", (signal.robustness or 0) * 10),
                    ("data_confidence", signal.confidence * 10),
                    ("unresolved", 2.0 if signal.disposition == "unresolved" else 0),
                    ("incremental_information", 5.0 if signal.drr_incremental else 0),
                )
                candidates.append(
                    AttentionItem(signal, sum(v for _, v in components), components, novelty)
                )
        ranked = tuple(sorted(candidates, key=lambda item: (-item.priority, item.signal.key)))
        return AttentionSelection(ranked[: self.top_n], ranked[self.top_n :], tuple(deprioritized))


def build_review_activity(snapshot, reviews, *, as_of):
    """Project current human activity onto an immutable analytical snapshot.

    Rebuild the attention budget from its original candidates so resolving an item
    promotes the next deferred item and reopening it restores its original rank.
    Reviews of evidence outside this snapshot are deliberately excluded.
    """
    cutoff = instant(as_of)
    latest = {}
    allowed = set(snapshot["evidence"])
    for review in sorted(reviews, key=lambda r: (instant(r.reviewed_at), r.review_id)):
        if review.evidence_id in allowed and instant(review.reviewed_at) <= cutoff:
            latest[review.evidence_id] = review

    def signal(value, *, scoring=False):
        item = MonitoringSignal(**value)
        review = latest.get(item.evidence_id)
        if review is None:
            return item
        disposition = review.disposition.value
        # `investigate` is an active queue state, so it must retain the original
        # unresolved priority component while remaining visible as investigate in
        # the activity feed.
        if scoring and disposition == "investigate":
            disposition = "unresolved"
        return replace(item, disposition=disposition)

    delta = dict(snapshot["delta"])
    for name in ("new_signals", "strengthened", "weakened", "changed_evidence", "disappeared"):
        delta[name] = tuple(signal(s, scoring=True) for s in delta[name])
    attention = AttentionBudget(top_n=snapshot["config"]["top_n"]).select(MonitoringDelta(**delta))
    return canonical(
        {
            "analysis_id": snapshot["passport"]["analysis_id"],
            "analytical_as_of": snapshot["as_of"],
            "review_as_of": cutoff.isoformat(),
            "reviews": [
                dict(review_id=r.review_id, **canonical(r)) for _, r in sorted(latest.items())
            ],
            "signals": [signal(s) for s in snapshot["state"]["signals"]],
            "attention": attention,
        }
    )

"""Reproducible, hashable analysis manifests; hashes are not digital signatures."""

from __future__ import annotations

import importlib.metadata
import json
import subprocess
import hashlib
from dataclasses import dataclass
from pathlib import Path

from .common import canonical_json, sha256_hex, stable_id, write_immutable


@dataclass(frozen=True)
class AnalysisPassport:
    payload_json: str

    def __post_init__(self):
        value = json.loads(self.payload_json)
        required = {
            "software_version",
            "git_commit",
            "source_code_sha256",
            "timestamp",
            "as_of",
            "filing_vintages",
            "mapping_version",
            "institutions",
            "peer_definition",
            "variables",
            "transformations",
            "drr_configuration",
            "baseline_configuration",
            "robustness_configuration",
            "random_seeds",
            "source_hashes",
            "output_hashes",
        }
        if required - set(value):
            raise ValueError("Incomplete analysis passport")
        sha256_hex(value["source_code_sha256"])
        if not value["source_hashes"]:
            raise ValueError("Analysis passport requires at least one source hash")
        for digest in value["source_hashes"]:
            sha256_hex(digest)
        for digest in value["output_hashes"].values():
            sha256_hex(digest)
        object.__setattr__(self, "payload_json", canonical_json(value))

    @property
    def analysis_id(self):
        return stable_id(json.loads(self.payload_json))

    @property
    def payload(self):
        return json.loads(self.payload_json)

    @classmethod
    def create(cls, **payload):
        return cls(canonical_json(payload))

    def export(self, directory):
        return write_immutable(
            Path(directory) / f"passport-{self.analysis_id}.json",
            canonical_json(dict(analysis_id=self.analysis_id, **self.payload)) + "\n",
        )


def verify_monitoring_snapshot(snapshot):
    """Verify the passport, analytical payload and review-state content hashes."""
    try:
        payload = dict(snapshot["passport"])
        expected_id = payload.pop("analysis_id")
        passport = AnalysisPassport.create(**payload)
        valid = (
            passport.analysis_id == expected_id
            and stable_id(snapshot["state"]) == snapshot["state_id"]
            and snapshot["as_of"] == snapshot["state"]["as_of"] == payload["as_of"]
            and stable_id({k: v for k, v in snapshot.items() if k not in {"passport", "judgment"}})
            == payload["output_hashes"]["monitoring"]
        )
    except (KeyError, TypeError, ValueError):
        raise ValueError("Monitoring snapshot integrity check failed") from None
    if not valid:
        raise ValueError("Monitoring snapshot integrity check failed")
    return passport


def software_identity():
    try:
        version = importlib.metadata.version("drr-framework")
    except importlib.metadata.PackageNotFoundError:
        version = "source-checkout"
    try:
        root = Path(__file__).resolve().parents[3]
        commit = subprocess.check_output(
            ["git", "rev-parse", "HEAD"], cwd=root, text=True, stderr=subprocess.DEVNULL, timeout=3
        ).strip()
        dirty = bool(
            subprocess.check_output(
                ["git", "status", "--porcelain", "--untracked-files=normal"],
                cwd=root,
                text=True,
                stderr=subprocess.DEVNULL,
                timeout=3,
            ).strip()
        )
    except (OSError, subprocess.SubprocessError):
        commit, dirty = "unknown", None
    package = Path(__file__).resolve().parents[1]
    digest = hashlib.sha256()
    for source in sorted(package.rglob("*.py")):
        digest.update(source.relative_to(package).as_posix().encode())
        digest.update(source.read_bytes())
    return {
        "version": version,
        "commit": commit,
        "working_tree_modified": dirty,
        "source_code_sha256": digest.hexdigest(),
    }


def dependency_inventory():
    """Installed-distribution inventory for reproducibility and external scanners."""
    return tuple(
        sorted(
            (d.metadata.get("Name", "unknown"), d.version)
            for d in importlib.metadata.distributions()
        )
    )

"""Preserve scoped observations and disagreement without ranking ways of knowing."""

from dataclasses import dataclass
from enum import Enum
import json
from pathlib import Path
from typing import Optional, Tuple

from .common import canonical, instant, stable_id


class PerspectiveKind(str, Enum):
    INSTITUTIONAL_ASSESSMENT = "institutional_assessment"
    QUANTITATIVE_MODEL = "quantitative_model"
    EXPERT_JUDGMENT = "expert_judgment"
    LOCAL_MEASUREMENT = "local_measurement"
    DISTRIBUTIONAL_INDICATOR = "distributional_indicator"
    LIVED_EXPERIENCE = "lived_experience"
    CONTEXTUAL_EVIDENCE = "contextual_evidence"


@dataclass(frozen=True)
class ScopedPerspective:
    system: str
    kind: PerspectiveKind
    claim: str
    author: str
    population: str
    geography: str
    scale: str
    dimension: str
    period_start: str
    period_end: str
    horizon: str
    available_as_of: str
    evidence_ids: Tuple[str, ...]
    method: str
    limitations: Tuple[str, ...]
    outside_scope: Tuple[str, ...]
    support_assessment: str
    support_assessor: str
    interpretation: str = ""
    confidence: Optional[float] = None
    institution_ids: Tuple[str, ...] = ()

    def __post_init__(self):
        object.__setattr__(self, "kind", PerspectiveKind(self.kind))
        for name in ("evidence_ids", "limitations", "outside_scope"):
            object.__setattr__(self, name, tuple(getattr(self, name)))
        object.__setattr__(self, "institution_ids", tuple(sorted(set(self.institution_ids))))
        for name in (
            "system",
            "claim",
            "author",
            "population",
            "geography",
            "scale",
            "dimension",
            "horizon",
            "method",
            "support_assessor",
        ):
            if not isinstance(getattr(self, name), str) or not getattr(self, name).strip():
                raise ValueError("Perspective requires explicit identity, scope and method")
        for name in ("period_start", "period_end", "available_as_of"):
            object.__setattr__(self, name, instant(getattr(self, name)).isoformat())
        if instant(self.period_start) > instant(self.period_end):
            raise ValueError("Perspective period is reversed")
        if not self.evidence_ids or not self.limitations or not self.outside_scope:
            raise ValueError("Evidence, limitations and representation boundaries are required")
        if self.support_assessment not in {"supported", "mixed", "unsupported", "not_evaluated"}:
            raise ValueError("Invalid attributed support assessment")
        if self.confidence is not None and not 0 <= self.confidence <= 1:
            raise ValueError("Confidence must be finite and in [0,1]")

    @property
    def perspective_id(self):
        return stable_id(self)


@dataclass(frozen=True)
class DocumentedDisagreement:
    perspective_ids: Tuple[str, ...]
    interpretation: str
    recorded_by: str
    available_as_of: str

    def __post_init__(self):
        object.__setattr__(self, "perspective_ids", tuple(sorted(set(self.perspective_ids))))
        object.__setattr__(self, "available_as_of", instant(self.available_as_of).isoformat())
        if (
            len(self.perspective_ids) < 2
            or not self.interpretation.strip()
            or not self.recorded_by.strip()
        ):
            raise ValueError(
                "Disagreement requires distinct perspectives and attributed interpretation"
            )

    @property
    def disagreement_id(self):
        return stable_id(self)


class PerspectiveInventory:
    """Immutable records; append returns a new inventory. No consensus score."""

    def __init__(self, perspectives=(), disagreements=()):
        self._perspectives = tuple(sorted(set(perspectives), key=lambda p: p.perspective_id))
        self._disagreements = tuple(sorted(set(disagreements), key=lambda d: d.disagreement_id))
        by_id = {p.perspective_id: p for p in self._perspectives}
        for disagreement in self._disagreements:
            if not set(disagreement.perspective_ids) <= set(by_id):
                raise ValueError("Disagreement references missing perspectives")
            members = [by_id[i] for i in disagreement.perspective_ids]
            if len({p.system for p in members}) != 1:
                raise ValueError("Disagreement must identify perspectives on the same system")
            if any(
                instant(p.available_as_of) > instant(disagreement.available_as_of) for p in members
            ):
                raise ValueError("Disagreement predates available perspectives")

    def append(self, *perspectives, disagreements=()):
        return type(self)(
            self._perspectives + perspectives, self._disagreements + tuple(disagreements)
        )

    @classmethod
    def from_json(cls, path):
        payload = json.loads(Path(path).read_text(encoding="utf-8"))
        payload = payload if isinstance(payload, dict) else {"perspectives": payload}
        perspectives = []
        for row in payload.get("perspectives", ()):
            values = dict(row)
            values.pop("perspective_id", None)
            perspectives.append(ScopedPerspective(**values))
        disagreements = []
        for row in payload.get("disagreements", ()):
            values = dict(row)
            for key in (
                "disagreement_id",
                "differing_scope_fields",
                "comparison_status",
                "conclusion",
            ):
                values.pop(key, None)
            disagreements.append(DocumentedDisagreement(**values))
        return cls(tuple(perspectives), tuple(disagreements))

    def snapshot(self, ledger=None, *, as_of, observations=()):
        perspectives = [
            p for p in self._perspectives if instant(p.available_as_of) <= instant(as_of)
        ]
        observed_by_id = {o.observation_id: o for o in observations}
        for p in perspectives:
            for oid in p.evidence_ids:
                entry = None
                if ledger is not None:
                    try:
                        entry = ledger.get(oid)
                    except KeyError:
                        entry = None
                if entry is not None:
                    evidence_available = [
                        entry.payload.get("evidence_available_as_of")
                        or max(f["available_as_of"] for f in entry.payload["source_facts"])
                    ]
                elif oid in observed_by_id:
                    evidence_available = [observed_by_id[oid].available_as_of]
                else:
                    raise ValueError("Perspective references missing evidence")
                if any(instant(value) > instant(p.available_as_of) for value in evidence_available):
                    raise ValueError("Perspective leaks future evidence")
        disagreements = []
        by_id = {p.perspective_id: p for p in perspectives}
        for d in self._disagreements:
            if instant(d.available_as_of) > instant(as_of):
                continue
            members = [by_id[i] for i in d.perspective_ids]
            differences = [
                name
                for name in (
                    "population",
                    "geography",
                    "scale",
                    "dimension",
                    "period_start",
                    "period_end",
                    "horizon",
                    "method",
                )
                if len({getattr(p, name) for p in members}) > 1
            ]
            disagreements.append(
                dict(
                    disagreement_id=d.disagreement_id,
                    **canonical(d),
                    differing_scope_fields=differences,
                    comparison_status=(
                        "different_observational_scopes"
                        if differences
                        else "shared_scope_requires_review"
                    ),
                    conclusion="Preserve all referenced perspectives. Scope differences may explain divergence; they do not establish agreement or refute either claim.",
                )
            )
        return dict(
            perspectives=[
                dict(perspective_id=p.perspective_id, **canonical(p)) for p in perspectives
            ],
            disagreements=disagreements,
            principle="A model can be excellent without being exhaustive. Accuracy within a representation does not establish completeness.",
            boundary="Support assessments are attributed judgments, not automatically verified truth. Authority, statistical confidence and lived experience do not determine precedence.",
        )

"""Public policy/reporting context with explicit availability and applicability basis."""

from __future__ import annotations

from dataclasses import dataclass
from enum import Enum
from typing import Optional, Tuple

from .common import day, instant, source_url, stable_id


class ApplicabilityBasis(str, Enum):
    AUTHORITATIVE_APPLICABILITY = "authoritative_applicability"
    ANALYST_INTERPRETATION = "analyst_interpretation"
    POSSIBLE_RELEVANCE = "possible_relevance"


@dataclass(frozen=True)
class PolicyEvent:
    identifier: str
    authority: str
    title: str
    publication_date: str
    effective_date: Optional[str]
    status: str
    institution_classes: Tuple[str, ...]
    forms: Tuple[str, ...]
    metrics: Tuple[str, ...]
    topic: str
    source: str
    available_as_of: str
    analyst_interpretation: str = ""
    confidence: float = 1.0
    applicability: ApplicabilityBasis = ApplicabilityBasis.POSSIBLE_RELEVANCE
    applicability_evidence: str = ""
    comparability_break: bool = False

    def __post_init__(self):
        object.__setattr__(self, "applicability", ApplicabilityBasis(self.applicability))
        for name in ("institution_classes", "forms", "metrics"):
            object.__setattr__(self, name, tuple(getattr(self, name)))
        source_url(self.source)
        if instant(self.available_as_of) < instant(self.publication_date):
            raise ValueError("Policy event cannot be available before publication")
        if self.effective_date:
            day(self.effective_date)
        if not 0 <= self.confidence <= 1:
            raise ValueError("Confidence must be in [0,1]")
        if (
            self.applicability == ApplicabilityBasis.AUTHORITATIVE_APPLICABILITY
            and not self.applicability_evidence
        ):
            raise ValueError("Authoritative applicability requires a quoted/source-specific scope")
        if self.comparability_break and not self.effective_date:
            raise ValueError("Reporting break needs an effective date")

    @property
    def event_id(self):
        return stable_id(self)


class PolicyContext:
    def __init__(self, events=()):
        self.events = tuple(sorted(events, key=lambda e: (e.publication_date, e.event_id)))

    def relevant(self, *, as_of, form=None, metric=None, institution_class=None):
        return tuple(
            e
            for e in self.events
            if instant(e.available_as_of) <= instant(as_of)
            and (not e.forms or form in e.forms)
            and (not e.metrics or metric in e.metrics)
            and (not e.institution_classes or institution_class in e.institution_classes)
        )

    def breakpoints(self, *, as_of, form, metric, dates, institution_class=None):
        points = []
        for event in self.relevant(
            as_of=as_of, form=form, metric=metric, institution_class=institution_class
        ):
            if event.comparability_break:
                first = next((d for d in dates if day(d) >= day(event.effective_date)), None)
                if first:
                    points.append(first)
        return tuple(sorted(set(points)))

"""Deterministic exceptions; questionable observations are never repaired silently."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Optional, Tuple

import numpy as np
import pandas as pd

from .common import stable_id


@dataclass(frozen=True)
class DataQualityException:
    severity: str
    institution: str
    metric: str
    period: str
    issue_type: str
    evidence: Tuple[str, ...]
    likely_explanation: Optional[str] = None
    required_analyst_review: bool = True
    source_links: Tuple[str, ...] = ()
    affected_calculations: Tuple[str, ...] = ()

    @property
    def exception_id(self):
        return stable_id(self)


@dataclass(frozen=True)
class ReconciliationRule:
    """Analyst-supplied comparable-metric identity: total=sum(parts) or ratio=num/den."""

    metric: str
    inputs: Tuple[str, ...]
    operation: str = "sum"
    multiplier: float = 1.0
    tolerance: float = 1e-6

    def __post_init__(self):
        object.__setattr__(self, "inputs", tuple(self.inputs))
        if self.operation not in {"sum", "ratio"} or not self.inputs:
            raise ValueError("Invalid reconciliation rule")
        if self.operation == "ratio" and len(self.inputs) != 2:
            raise ValueError("Ratio needs exactly two inputs")
        if (
            not np.isfinite(self.multiplier)
            or not np.isfinite(self.tolerance)
            or self.tolerance < 0
        ):
            raise ValueError("Invalid reconciliation multiplier/tolerance")


def reconcile_dataset(dataset, *, rules=(), extreme_change=0.5, carry_forward_periods=4):
    if extreme_change <= 0 or carry_forward_periods < 2:
        raise ValueError("Invalid reconciliation thresholds")
    issues = []
    records = {(o.metric, o.reporting_period): o for o in dataset.observations}
    frame = dataset.frame

    def add(kind, metric, period, severity="warning", explanation=None, inputs=()):
        observations = [
            records[(m, p)] for m, p in ((metric, period), *inputs) if (m, p) in records
        ]
        issues.append(
            DataQualityException(
                severity,
                dataset.institution_id,
                metric,
                period,
                kind,
                tuple(o.observation_id for o in observations),
                explanation,
                True,
                tuple(sorted({o.source for o in observations})),
                (f"{metric}:change", f"{metric}:DRR"),
            )
        )

    for metric in dataset.variable_names:
        series = frame[metric]
        run = 1
        for i, (period, value) in enumerate(series.items()):
            if pd.isna(value):
                add(
                    (
                        "missing_quarter"
                        if period not in {o.reporting_period for o in dataset.observations}
                        else "missing_value"
                    ),
                    metric,
                    period,
                    "important",
                )
                run = 1
                continue
            o = records.get((metric, period))
            if o and o.amendment_date:
                add(
                    "amended_filing",
                    metric,
                    period,
                    "info",
                    "Source labels this observation as an amendment",
                )
            if i == 0:
                continue
            prior_period, prior_value = series.index[i - 1], series.iloc[i - 1]
            prior = records.get((metric, prior_period))
            evidence = ((metric, prior_period),)
            if o and prior:
                for field, kind in (
                    ("unit", "unit_change"),
                    ("definition_version", "definition_change"),
                    ("perimeter_version", "perimeter_change"),
                ):
                    if getattr(o, field) != getattr(prior, field):
                        add(
                            kind, metric, period, "important", f"Reported {field} changed", evidence
                        )
            if pd.isna(prior_value):
                continue
            if value == 0 and prior_value != 0:
                add("unexpected_zero", metric, period, inputs=evidence)
            if prior_value != 0 and abs((value - prior_value) / prior_value) >= extreme_change:
                add("extreme_qoq", metric, period, inputs=evidence)
            run = run + 1 if value == prior_value else 1
            if run >= carry_forward_periods:
                add(
                    "suspicious_carry_forward",
                    metric,
                    period,
                    explanation=f"{run} consecutive identical reported values",
                    inputs=evidence,
                )
        if dataset.dates:
            age = (
                pd.Period(dataset.available_as_of[:10], freq="Q").ordinal
                - pd.Period(dataset.dates[-1], freq="Q").ordinal
            )
            if age > 1:
                add(
                    "stale_series",
                    metric,
                    dataset.dates[-1],
                    explanation=f"Latest reporting period is {age} quarters before review",
                )
    for rule in rules:
        if any(m not in frame.columns for m in (rule.metric, *rule.inputs)):
            raise ValueError("Reconciliation rule references an unknown metric")
        for period, row in frame.iterrows():
            inputs = row[list(rule.inputs)].to_numpy(dtype=float)
            if not np.isfinite(inputs).all() or pd.isna(row[rule.metric]):
                continue
            expected = (
                float(inputs.sum())
                if rule.operation == "sum"
                else None if inputs[1] == 0 else float(inputs[0] / inputs[1])
            )
            if expected is None:
                add(
                    "broken_ratio",
                    rule.metric,
                    period,
                    "important",
                    "Denominator is zero",
                    tuple((m, period) for m in rule.inputs),
                )
            elif abs(row[rule.metric] - expected * rule.multiplier) > rule.tolerance:
                add(
                    "inconsistent_total" if rule.operation == "sum" else "broken_ratio",
                    rule.metric,
                    period,
                    "important",
                    f"Expected {expected*rule.multiplier:g} from explicit {rule.operation} rule",
                    tuple((m, period) for m in rule.inputs),
                )
    return tuple(sorted(issues, key=lambda e: (e.period, e.metric, e.issue_type)))


def reconcile_store(store, as_of):
    """Report duplicates/conflicts before attempting a matrix pivot."""
    groups = {}
    for o in store.known_records(as_of):
        groups.setdefault((o.key, o.filing_date), []).append(o)
    result = []
    for (_, _), rows in sorted(groups.items()):
        if len(rows) < 2:
            continue
        o = rows[0]
        conflict = (
            len({(r.value, r.unit, r.definition_version, r.perimeter_version) for r in rows}) > 1
        )
        result.append(
            DataQualityException(
                "important" if conflict else "warning",
                o.institution_id,
                o.metric,
                o.reporting_period,
                "source_conflict" if conflict else "duplicate_record",
                tuple(r.observation_id for r in rows),
                source_links=tuple(sorted({r.source for r in rows})),
            )
        )
    return tuple(result)

"""Explain changes to the exact observations held by two review states."""

from __future__ import annotations

import math

from .common import canonical, instant


def build_revision_audit(store, previous, current, delta):
    """Return traceable same-period revisions, never quarter-to-quarter changes.

    The previous state's IDs are authoritative: reconstructing its cutoff from a
    different input store could silently substitute evidence the analyst never saw.
    Missing historical records and comparability breaks remain explicit.
    """
    if previous is None:
        return ()
    if instant(current.as_of) < instant(previous.as_of):
        raise ValueError("Current review precedes previous state")
    before, after = dict(previous.observations), dict(current.observations)
    records = {o.observation_id: o for o in store.known_records(current.as_of)}
    rows = []
    for key in sorted(before.keys() & after.keys()):
        if before[key] == after[key]:
            continue
        old, new = records.get(before[key]), records.get(after[key])
        for record, cutoff in ((old, previous.as_of), (new, current.as_of)):
            if record and (
                "|".join(record.key) != key or instant(record.available_as_of) > instant(cutoff)
            ):
                raise ValueError("Review observation does not match its identity or cutoff")
        previous_fact = dict(observation_id=old.observation_id, **canonical(old)) if old else None
        current_fact = dict(observation_id=new.observation_id, **canonical(new)) if new else None
        changed_fields = (
            tuple(k for k in canonical(old) if getattr(old, k) != getattr(new, k))
            if old and new
            else ()
        )
        raw_change = percent_change = None
        if not old or not new:
            status = "source_unavailable"
            limitation = "An exact observation from the review state is absent from this store."
        elif any(
            k in changed_fields
            for k in ("unit", "definition_version", "perimeter_version", "provenance")
        ):
            status = "incomparable"
            limitation = "Units, definitions, reporting perimeter or provenance changed; no numerical revision is inferred."
        elif old.value is None or new.value is None:
            status = "missing_value"
            limitation = "A reported value is null; no numerical revision is inferred."
        else:
            status = "comparable"
            raw_change = new.value - old.value
            percent_change = raw_change / abs(old.value) * 100 if old.value != 0 else None
            limitation = (
                "Prior value is zero; percent revision is undefined." if old.value == 0 else ""
            )
            if not math.isfinite(raw_change):
                status = "numeric_overflow"
                raw_change = percent_change = None
                limitation = (
                    "The revision exceeds floating-point range; no numerical revision is reported."
                )
            elif percent_change is not None and not math.isfinite(percent_change):
                percent_change = None
                limitation = "The percent revision exceeds floating-point range."
        transitions = []
        record = new or old
        if record:
            for group in (
                "new_signals",
                "strengthened",
                "weakened",
                "changed_evidence",
                "disappeared",
            ):
                for signal in getattr(delta, group):
                    if (
                        signal.institution == record.institution_id
                        and signal.metric == record.metric
                        and signal.key.startswith(f"{record.institution_id}:{record.form}:")
                    ):
                        transitions.append(
                            {"transition": group, "key": signal.key, "claim": signal.claim}
                        )
        rows.append(
            {
                "observation_key": key,
                "previous_observation_id": before[key],
                "current_observation_id": after[key],
                "previous": previous_fact,
                "current": current_fact,
                "changed_fields": changed_fields,
                "comparison_status": status,
                "raw_change": raw_change,
                "percent_change": percent_change,
                "limitation": limitation,
                "concurrent_signal_changes": transitions,
            }
        )
    return tuple(rows)

