"""Append-only public observations and conservative point-in-time reconstruction."""

from __future__ import annotations

import csv
import json
import math
from dataclasses import dataclass, replace
from pathlib import Path
from typing import Optional, Tuple
from enum import Enum

import numpy as np
import pandas as pd

from .common import canonical, canonical_json, day, instant, sha256_hex, source_url, stable_id
from .semantics import SemanticRegistry


class ObservationProvenance(str, Enum):
    RAW_REPORTED = "raw_reported"
    IMPUTED_CAUSAL = "imputed_causal"
    DERIVED_COMPUTED = "derived_computed"
    EXTERNAL_REFERENCE = "external_reference"
    ANALYST_ENTERED = "analyst_entered"
    SYNTHETIC_TEST = "synthetic_test"


@dataclass(frozen=True)
class CalculationLineage:
    formula: str
    input_ids: Tuple[str, ...]
    input_metrics: Tuple[str, ...]
    input_periods: Tuple[str, ...]
    software_version: str
    parameters: Tuple[Tuple[str, str], ...]
    unit: str
    timestamp: str

    def __post_init__(self):
        for name in ("input_ids", "input_metrics", "input_periods"):
            object.__setattr__(self, name, tuple(getattr(self, name)))
        object.__setattr__(self, "parameters", tuple(tuple(p) for p in self.parameters))
        if not self.formula or not self.input_ids or not self.software_version or not self.unit:
            raise ValueError("Derived values require full calculation lineage")
        if len(self.input_ids) != len(self.input_metrics) or len(self.input_ids) != len(
            self.input_periods
        ):
            raise ValueError("Lineage dimensions must match")
        instant(self.timestamp)


@dataclass(frozen=True)
class RegulatoryObservation:
    institution_id: str
    institution_name: str
    form: str
    metric: str
    reporting_period: str
    value: Optional[float]
    unit: str
    original_filing_date: str
    ingestion_date: str
    source_vintage: str
    available_as_of: str
    definition_version: str
    source: str
    provenance: ObservationProvenance = ObservationProvenance.RAW_REPORTED
    amendment_date: Optional[str] = None
    supersedes: Optional[str] = None
    perimeter_version: str = "unspecified"
    lineage: Optional[CalculationLineage] = None
    source_hash: str = ""

    def __post_init__(self):
        object.__setattr__(self, "provenance", ObservationProvenance(self.provenance))
        object.__setattr__(self, "reporting_period", day(self.reporting_period))
        for name in ("original_filing_date", "ingestion_date", "available_as_of", "amendment_date"):
            if getattr(self, name) is not None:
                object.__setattr__(self, name, instant(getattr(self, name)).isoformat())
        if not all(
            (
                self.institution_id,
                self.institution_name,
                self.form,
                self.metric,
                self.unit,
                self.source_vintage,
                self.definition_version,
                self.source,
            )
        ):
            raise ValueError("Observation identity, units, vintage and source are required")
        if self.value is not None:
            if isinstance(self.value, bool) or not math.isfinite(float(self.value)):
                raise ValueError(
                    "Missing observations must be null; infinities and booleans are invalid"
                )
            object.__setattr__(self, "value", float(self.value))
        if instant(self.original_filing_date) < instant(self.reporting_period):
            raise ValueError("A filing cannot precede its reporting period")
        if self.amendment_date and instant(self.amendment_date) < instant(
            self.original_filing_date
        ):
            raise ValueError("Amendment predates original filing")
        if instant(self.available_as_of) < max(
            instant(self.ingestion_date), instant(self.filing_date)
        ):
            raise ValueError("Availability cannot precede ingestion or filing")
        derived = self.provenance in {
            ObservationProvenance.DERIVED_COMPUTED,
            ObservationProvenance.IMPUTED_CAUSAL,
        }
        if derived and self.lineage is None:
            raise ValueError("Derived and imputed observations require lineage")
        if self.lineage and instant(self.lineage.timestamp) > instant(self.available_as_of):
            raise ValueError("Calculation is unavailable until computed")
        if self.provenance == ObservationProvenance.SYNTHETIC_TEST:
            if not self.metric.startswith("SYN_"):
                raise ValueError("Synthetic values require SYN_ metric codes")
        elif self.provenance in {
            ObservationProvenance.RAW_REPORTED,
            ObservationProvenance.EXTERNAL_REFERENCE,
        }:
            source_url(self.source)
            object.__setattr__(self, "source_hash", sha256_hex(self.source_hash))
        elif self.source_hash:
            object.__setattr__(self, "source_hash", sha256_hex(self.source_hash))

    @property
    def filing_date(self):
        return self.amendment_date or self.original_filing_date

    @property
    def key(self):
        return self.institution_id, self.form, self.metric, self.reporting_period

    @property
    def observation_id(self):
        return stable_id(self)

    @classmethod
    def from_dict(cls, row):
        values = dict(row)
        values.pop("observation_id", None)
        if isinstance(values.get("lineage"), dict):
            values["lineage"] = CalculationLineage(**values["lineage"])
        if values.get("value") == "":
            values["value"] = None
        for name in ("amendment_date", "supersedes", "lineage"):
            if values.get(name) == "":
                values[name] = None
        return cls(**values)


@dataclass(frozen=True)
class FilingRevision:
    previous: RegulatoryObservation
    current: RegulatoryObservation
    raw_change: Optional[float]


class VintageStore:
    """Immutable snapshots; appending returns a new store, never mutates history."""

    def __init__(self, observations=()):
        self.observations = tuple(
            sorted(observations, key=lambda o: (o.key, o.filing_date, o.observation_id))
        )
        self._known_cache = {}
        self._as_of_cache = {}
        by_id = {o.observation_id: o for o in self.observations}
        for o in self.observations:
            if o.supersedes:
                parent = by_id.get(o.supersedes)
                if (
                    parent is None
                    or parent.key != o.key
                    or instant(parent.filing_date) >= instant(o.filing_date)
                ):
                    raise ValueError(
                        "Superseded observation must be an earlier filing of the same key"
                    )
            if o.lineage:
                for oid, metric, period in zip(
                    o.lineage.input_ids, o.lineage.input_metrics, o.lineage.input_periods
                ):
                    parent = by_id.get(oid)
                    if (
                        parent is None
                        or parent.metric != metric
                        or parent.reporting_period != day(period)
                    ):
                        raise ValueError("Lineage references a missing or mismatched observation")
                    if instant(parent.available_as_of) > instant(o.available_as_of):
                        raise ValueError("Derived observation leaks future input")
                    if o.provenance == ObservationProvenance.IMPUTED_CAUSAL and (
                        parent.institution_id != o.institution_id
                        or parent.form != o.form
                        or parent.metric != o.metric
                        or parent.reporting_period >= o.reporting_period
                        or parent.definition_version != o.definition_version
                        or parent.unit != o.unit
                        or parent.perimeter_version != o.perimeter_version
                    ):
                        raise ValueError(
                            "Imputation must be trailing, institution-local and comparable"
                        )

    def append(self, *observations):
        return VintageStore(self.observations + tuple(observations))

    def known_records(self, as_of):
        cutoff = instant(as_of)
        key = cutoff.isoformat()
        if key not in self._known_cache:
            if len(self._known_cache) >= 64:
                self._known_cache.pop(next(iter(self._known_cache)))
            self._known_cache[key] = tuple(
                o for o in self.observations if instant(o.available_as_of) <= cutoff
            )
        return self._known_cache[key]

    def as_of(self, as_of):
        key = instant(as_of).isoformat()
        if key in self._as_of_cache:
            return self._as_of_cache[key]
        selected = {}
        for o in self.known_records(as_of):
            old = selected.get(o.key)
            if old is None or instant(o.filing_date) > instant(old.filing_date):
                selected[o.key] = o
            elif (
                instant(o.filing_date) == instant(old.filing_date)
                and o.observation_id != old.observation_id
            ):
                # Same reported facts ingested twice are duplicates, not amendments.
                facts = (o.value, o.unit, o.definition_version, o.perimeter_version, o.provenance)
                old_facts = (
                    old.value,
                    old.unit,
                    old.definition_version,
                    old.perimeter_version,
                    old.provenance,
                )
                if facts != old_facts:
                    raise ValueError(
                        f"Conflicting source facts for {o.key}; analyst reconciliation required"
                    )
        result = tuple(selected[record_key] for record_key in sorted(selected))
        if len(self._as_of_cache) >= 64:
            self._as_of_cache.pop(next(iter(self._as_of_cache)))
        self._as_of_cache[key] = result
        return result

    def get_observation_as_of(self, institution_id, form, metric, period, as_of):
        key = institution_id, form, metric, day(period)
        return next((o for o in self.as_of(as_of) if o.key == key), None)

    def filing_revision_history(self, institution_id, form, metric, period, *, as_of):
        key = institution_id, form, metric, day(period)
        return tuple(o for o in self.known_records(as_of) if o.key == key)

    def compare_vintages(self, previous_as_of, current_as_of):
        if instant(current_as_of) < instant(previous_as_of):
            raise ValueError("Current as-of precedes previous review")
        before = {o.key: o for o in self.as_of(previous_as_of)}
        return tuple(
            FilingRevision(
                before[o.key],
                o,
                (
                    None
                    if before[o.key].value is None or o.value is None
                    else o.value - before[o.key].value
                ),
            )
            for o in self.as_of(current_as_of)
            if o.key in before and o.observation_id != before[o.key].observation_id
        )

    def export_jsonl(self, path):
        output = Path(path)
        from .common import write_immutable

        return write_immutable(output, "".join(canonical_json(o) + "\n" for o in self.observations))

    @classmethod
    def from_file(cls, path):
        """Read normalized local CSV/JSONL; never fetch or infer source fields."""
        path = Path(path)
        with path.open(encoding="utf-8-sig", newline="") as f:
            rows = (
                csv.DictReader(f)
                if path.suffix.lower() == ".csv"
                else (json.loads(line) for line in f if line.strip())
            )
            return cls(tuple(RegulatoryObservation.from_dict(r) for r in rows))


def build_regulatory_dataset(
    cls,
    store: VintageStore,
    registry: SemanticRegistry,
    *,
    institution_id: str,
    form: str,
    as_of: str,
    metrics=None,
    peer_group=None,
    allow_synthetic=False,
):
    records = tuple(
        o
        for o in store.as_of(as_of)
        if o.institution_id == institution_id
        and o.form == form
        and (metrics is None or o.metric in metrics)
    )
    if not records:
        raise ValueError("No observations available for this institution/form/as-of")
    names = tuple(metrics) if metrics is not None else tuple(sorted({o.metric for o in records}))
    if not names or len(set(names)) != len(names):
        raise ValueError("Metrics must be unique and nonempty")
    definitions = {}
    for o in records:
        definition = registry.resolve(
            form,
            o.metric,
            o.reporting_period,
            as_of=as_of,
            version=o.definition_version,
            allow_synthetic=allow_synthetic,
        )
        if o.unit != definition.unit:
            raise ValueError(f"Unit mismatch for {o.metric}: {o.unit} vs {definition.unit}")
        if definition.frequency != "quarterly":
            raise ValueError("This dataset requires quarterly definitions")
        if (
            pd.Timestamp(o.reporting_period)
            != pd.Period(o.reporting_period, freq="Q").end_time.normalize()
        ):
            raise ValueError("Regulatory periods must be quarter ends")
        definitions[f"{o.metric}:{o.definition_version}"] = canonical(definition)
    periods = pd.period_range(
        min(o.reporting_period for o in records), max(o.reporting_period for o in records), freq="Q"
    )
    dates = tuple(p.end_time.date().isoformat() for p in periods)
    frame = pd.DataFrame(index=pd.Index(dates, name="reporting_period"), columns=names, dtype=float)
    for o in records:
        frame.loc[o.reporting_period, o.metric] = np.nan if o.value is None else o.value
    flags = tuple(
        f"missing:{period}:{metric}"
        for period in dates
        for metric in names
        if pd.isna(frame.loc[period, metric])
    )
    return cls(
        frame=frame,
        values=frame.to_numpy(dtype=float),
        variable_names=names,
        dates=dates,
        sampling_rate=4.0,
        metadata={
            "source": "vintage_store",
            "form": form,
            "semantic_registry": registry.version,
            "allow_synthetic": allow_synthetic,
            "transform": "level",
            "standardize": False,
        },
        institution_id=institution_id,
        institution_name=records[-1].institution_name,
        filing_type=form,
        reporting_period=dates[-1],
        filing_vintage=tuple(sorted({o.source_vintage for o in records})),
        retrieved_at=max(o.ingestion_date for o in records),
        available_as_of=instant(as_of).isoformat(),
        peer_group=peer_group,
        provenance={o.observation_id: o.provenance.value for o in records},
        source_citations=tuple(sorted({o.source for o in records})),
        source_hashes=tuple(sorted({o.source_hash for o in records if o.source_hash})),
        metric_metadata=definitions,
        institution_metadata={"perimeter_versions": sorted({o.perimeter_version for o in records})},
        data_quality_flags=flags,
        imputation_metadata=tuple(
            canonical(o.lineage)
            for o in records
            if o.provenance == ObservationProvenance.IMPUTED_CAUSAL
        ),
        reporting_definition_version=tuple(sorted({o.definition_version for o in records})),
        observations=records,
        _store=store,
        _registry=registry,
    )

"""Temporal statistics for sequences of directed rooting-score matrices."""

from __future__ import annotations

from dataclasses import dataclass

import numpy as np


def _adjacency(matrix: np.ndarray) -> np.ndarray:
    value = np.maximum(np.asarray(matrix, dtype=float), 0.0).copy()
    if value.ndim != 2 or value.shape[0] != value.shape[1] or not np.all(np.isfinite(value)):
        raise ValueError("adjacency must be a finite square matrix")
    np.fill_diagonal(value, 0.0)
    return value


def root_distribution(adjacency: np.ndarray) -> np.ndarray:
    """Normalize non-negative outgoing influence; use uniform mass if empty."""
    outflow = _adjacency(adjacency).sum(axis=1)
    total = float(outflow.sum())
    return outflow / total if total > 0 else np.full(len(outflow), 1.0 / len(outflow))


def root_migration(previous: np.ndarray, current: np.ndarray) -> float:
    """Base-2 Jensen-Shannon divergence of consecutive root distributions [0, 1]."""
    p, q = root_distribution(previous), root_distribution(current)
    if p.shape != q.shape:
        raise ValueError("graphs must have equal size")
    midpoint = 0.5 * (p + q)

    def kl(a: np.ndarray) -> float:
        mask = a > 0
        return float(np.sum(a[mask] * np.log2(a[mask] / midpoint[mask])))

    return float(np.clip(0.5 * (kl(p) + kl(q)), 0.0, 1.0))


def topology_drift(previous: np.ndarray, current: np.ndarray) -> float:
    """Scale-invariant angular Frobenius distance in [0, 1]."""
    p, q = _adjacency(previous), _adjacency(current)
    if p.shape != q.shape:
        raise ValueError("graphs must have equal size")
    if np.array_equal(p, q):
        return 0.0
    pn, qn = np.linalg.norm(p), np.linalg.norm(q)
    if pn == 0 and qn == 0:
        return 0.0
    if pn == 0 or qn == 0:
        return 1.0
    similarity = float(np.sum(p * q) / (pn * qn))
    return float(np.clip(1.0 - similarity, 0.0, 1.0))


@dataclass(frozen=True)
class RootingTopologySummary:
    inflow: np.ndarray
    outflow: np.ndarray
    root_share: np.ndarray
    density: float
    root_concentration: float
    rooting_entropy: float


def summarize_topology(adjacency: np.ndarray) -> RootingTopologySummary:
    matrix = _adjacency(adjacency)
    share = root_distribution(matrix)
    positive = share > 0
    entropy = -np.sum(share[positive] * np.log(share[positive]))
    normalized = float(entropy / np.log(len(share))) if len(share) > 1 else 0.0
    possible = matrix.shape[0] * (matrix.shape[0] - 1)
    return RootingTopologySummary(
        inflow=matrix.sum(axis=0),
        outflow=matrix.sum(axis=1),
        root_share=share,
        density=float(np.count_nonzero(matrix) / possible) if possible else 0.0,
        root_concentration=float(np.sum(share**2)),
        rooting_entropy=normalized,
    )

"""Cirq integration: workload inference from ``cirq.Result`` objects."""

from __future__ import annotations

from collections.abc import Callable, Iterable
from datetime import datetime
from typing import Any

from ..inferred import FlipTally, QubitIdeal, flip_estimates, tally_marginal
from ..models import Estimate, utcnow

_DETERMINISTIC_TOL = 1e-9


def default_qubit_index(q) -> int:
    """LineQubit -> x. Other qubit types need an explicit ``qubit_index``."""
    if hasattr(q, "x") and not hasattr(q, "row"):
        return int(q.x)
    raise ValueError(f"no default integer index for {q!r}; pass qubit_index=")


def canonical_gate_name(op) -> str:
    """Qiskit-style name for a Cirq gate, so that exact contexts agree across
    frameworks: X -> x, X**0.5 -> sx, H -> h, Y -> y, Ry -> ry, Rz/Z**t -> rz,
    CNOT -> cx, CZ -> cz; otherwise the gate class name in lower case."""
    import cirq

    g = op.gate
    if isinstance(g, cirq.Rx):
        return "rx"
    if isinstance(g, cirq.XPowGate):
        e = g.exponent % 2
        if abs(e - 1) < 1e-9:
            return "x"
        if abs(e - 0.5) < 1e-9:
            return "sx"
        return "sxdg" if abs(e - 1.5) < 1e-9 else "rx"
    if isinstance(g, cirq.HPowGate):
        return "h"
    if isinstance(g, cirq.Ry):
        return "ry"
    if isinstance(g, cirq.YPowGate):
        return "y" if abs(g.exponent % 2 - 1) < 1e-9 else "ry"
    if isinstance(g, (cirq.Rz, cirq.ZPowGate)):
        return "rz"
    if isinstance(g, cirq.CXPowGate):
        return "cx"
    if isinstance(g, cirq.CZPowGate):
        return "cz"
    return type(g).__name__.lower()


def _drop_waits(circuit):
    import cirq

    return cirq.Circuit(
        cirq.Moment(op for op in m.operations if not isinstance(op.gate, cirq.WaitGate)) for m in circuit
    )


def analyze_circuit(circuit, max_sim_qubits: int = 16, context_mode: str = "bucket"):
    """Return ({cirq qubit: (measurement key, column)}, {cirq qubit: QubitIdeal})."""
    import cirq
    import numpy as np

    measured: dict[Any, tuple[str, int]] = {}
    n_1q: dict[Any, int] = {}
    n_2q: dict[Any, int] = {}
    names: dict[Any, dict[str, int]] = {}
    idle_ns: dict[Any, float] = {}
    for op in circuit.all_operations():
        if cirq.is_measurement(op):
            key = cirq.measurement_key_name(op)
            for col, q in enumerate(op.qubits):
                measured[q] = (key, col)
        elif isinstance(op.gate, cirq.WaitGate):
            for q in op.qubits:
                idle_ns[q] = idle_ns.get(q, 0.0) + float(op.gate.duration.total_nanos())
        else:
            counter = n_1q if len(op.qubits) == 1 else n_2q
            name = canonical_gate_name(op)
            for q in op.qubits:
                counter[q] = counter.get(q, 0) + 1
                names.setdefault(q, {})[name] = names.get(q, {}).get(name, 0) + 1

    def ideal_for(q, bit, reason=""):
        return QubitIdeal(
            bit,
            n_1q.get(q, 0),
            n_2q.get(q, 0),
            reason,
            tuple(sorted(names.get(q, {}).items())),
            idle_ns.get(q, 0.0),
            0,
            context_mode,
        )

    problem = ""
    if cirq.is_parameterized(circuit):
        problem = "circuit has unresolved parameters"
    elif not circuit.are_all_measurements_terminal():
        problem = "mid-circuit measurement"
    elif not cirq.has_unitary(_drop_waits(cirq.drop_terminal_measurements(circuit))):
        problem = "circuit contains non-unitary operations"
    elif len(circuit.all_qubits()) > max_sim_qubits:
        problem = f"{len(circuit.all_qubits())} qubits > max_sim_qubits={max_sim_qubits}"
    if problem:
        return measured, {q: ideal_for(q, None, problem) for q in measured}

    unitary_part = _drop_waits(cirq.drop_terminal_measurements(circuit))
    order = sorted(circuit.all_qubits())
    state = cirq.final_state_vector(unitary_part, qubit_order=order, dtype=np.complex128)
    probs = np.abs(state) ** 2
    n = len(order)
    ideal = {}
    for q in measured:
        i = order.index(q)
        # Cirq is big-endian: qubit i is bit (n - 1 - i) of the basis index.
        mask = 1 << (n - 1 - i)
        p1 = float(probs[[b for b in range(2**n) if b & mask]].sum())
        if p1 < _DETERMINISTIC_TOL:
            ideal[q] = ideal_for(q, 0)
        elif p1 > 1 - _DETERMINISTIC_TOL:
            ideal[q] = ideal_for(q, 1)
        else:
            ideal[q] = ideal_for(q, None, f"ideal outcome not deterministic (p1={p1:.3f})")
    return measured, ideal


def infer_from_results(
    circuits: Iterable[Any],
    results: Iterable[Any],
    timestamp: datetime | None = None,
    source: str = "cirq",
    qubit_index: Callable[[Any], int] = default_qubit_index,
    min_shots: int = 200,
    max_sim_qubits: int = 16,
    context_mode: str = "bucket",
) -> list[Estimate]:
    timestamp = timestamp or utcnow()
    tallies: dict[tuple[int, str], FlipTally] = {}
    unidentified: dict[int, str] = {}
    owner: dict[int, Any] = {}
    for circuit, res in zip(circuits, results, strict=True):
        measured, ideal = analyze_circuit(circuit, max_sim_qubits, context_mode)
        for q, (key, col) in measured.items():
            qi = qubit_index(q)
            if not isinstance(qi, int) or isinstance(qi, bool) or qi < 0:
                raise ValueError(f"qubit_index({q!r}) returned {qi!r}; need a non-negative int")
            if owner.setdefault(qi, q) != q:
                raise ValueError(f"inconsistent qubit identifiers: {owner[qi]!r} and {q!r} both map to index {qi}")
            bits = _measured_bits(res, key, col, q)
            if ideal[q].bit is None:
                unidentified.setdefault(qi, ideal[q].reason)
                continue
            tally_marginal(tallies, qi, ideal[q], int(bits.shape[0]), int(bits.sum()))
    return flip_estimates(tallies, unidentified, timestamp, source, min_shots)


# --------------------------------------------------------------------------- readout probes


def readout_probe_circuits(qubits, key: str = "m"):
    """Two Cirq circuits that prepare every qubit in |0> and in |1> (one X
    each) and measure them under ``key`` (see ``qnp.measured``)."""
    import cirq

    qs = list(qubits)
    if not qs or len(set(qs)) != len(qs):
        raise ValueError(f"need distinct qubits, got {qs!r}")
    return [cirq.Circuit(cirq.measure(*qs, key=key)), cirq.Circuit(cirq.X.on_each(*qs), cirq.measure(*qs, key=key))]


def readout_probe_preparations(circuit) -> dict[Any, tuple[int, tuple[str, int]]] | None:
    """If ``circuit`` is a readout probe (only X gates and terminal
    measurements, at most one X per qubit, no waits), ``{qubit: (prepared
    bit, (measurement key, column))}``; otherwise None. Same rule as the
    Qiskit adapter. Moments are time steps, so a qubit prepared in |1> must
    be measured in the moment right after its X: an empty moment or another
    qubit's measurement in between would leave it waiting, and decaying."""
    import cirq

    if cirq.is_parameterized(circuit):
        return None
    prepared: dict[Any, int] = {}  # qubit -> moment of its X
    measured: dict[Any, tuple[str, int]] = {}
    for i, moment in enumerate(circuit):
        for op in moment.operations:
            if cirq.is_measurement(op):
                key = cirq.measurement_key_name(op)
                for col, q in enumerate(op.qubits):
                    if q in measured or prepared.get(q, i - 1) != i - 1:
                        return None
                    measured[q] = (key, col)
                continue
            if len(op.qubits) != 1 or canonical_gate_name(op) != "x":
                return None
            q = op.qubits[0]
            if q in measured or q in prepared:
                return None
            prepared[q] = i
    if not measured:
        return None
    return {q: (int(q in prepared), m) for q, m in measured.items()}


def _measured_bits(res, key: str, col: int, q) -> Any:
    import numpy as np

    if key not in res.measurements:
        raise ValueError(f"result has no measurement key {key!r}: results do not belong to this circuit")
    data = res.measurements[key]
    if data.ndim != 2 or col >= data.shape[1]:
        raise ValueError(f"measurement {key!r} has shape {data.shape}; expected a column for {q!r}")
    if not np.isin(data, (0, 1)).all():
        raise ValueError(f"measurement {key!r} contains values other than 0/1")
    return data[:, col]


def _check_qubit_identity(circuits, qubit_index: Callable[[Any], int]) -> None:
    """Every measured qubit maps to a non-negative int, and no two distinct
    qubits share an index, across all circuits of the batch."""
    import cirq

    owner: dict[int, Any] = {}
    for circuit in circuits:
        for op in circuit.all_operations():
            if not cirq.is_measurement(op):
                continue
            for q in op.qubits:
                qi = qubit_index(q)
                if not isinstance(qi, int) or isinstance(qi, bool) or qi < 0:
                    raise ValueError(f"qubit_index({q!r}) returned {qi!r}; need a non-negative int")
                if owner.setdefault(qi, q) != q:
                    raise ValueError(f"inconsistent qubit identifiers: {owner[qi]!r} and {q!r} both map to index {qi}")


def estimates_from_results(
    circuits: Iterable[Any],
    results: Iterable[Any],
    timestamp: datetime | None = None,
    source: str = "cirq",
    qubit_index: Callable[[Any], int] = default_qubit_index,
    min_shots: int = 200,
    max_sim_qubits: int = 16,
    context_mode: str = "exact",
    readout_probes: str = "auto",
) -> list[Estimate]:
    """MEASURED ``readout_error`` from readout probes and INFERRED effective
    flip rates from the other circuits of one batch (the Cirq counterpart of
    ``qiskit_adapter.estimates_from_results``)."""
    from ..measured import estimate_readout

    if readout_probes not in ("auto", "off"):
        raise ValueError(f"readout_probes must be 'auto' or 'off', got {readout_probes!r}")
    timestamp = timestamp or utcnow()
    circuits, results = list(circuits), list(results)
    if len(circuits) != len(results):
        raise ValueError(f"{len(circuits)} circuits but {len(results)} results")
    _check_qubit_identity(circuits, qubit_index)
    work_c, work_r = [], []
    tallies: dict[tuple[int, int], list[int]] = {}
    for circuit, res in zip(circuits, results, strict=True):
        preps = readout_probe_preparations(circuit) if readout_probes == "auto" else None
        if preps is None:
            work_c.append(circuit)
            work_r.append(res)
            continue
        for q, (bit, (key, col)) in preps.items():
            bits = _measured_bits(res, key, col, q)
            ones, shots = int(bits.sum()), int(bits.shape[0])
            t = tallies.setdefault((qubit_index(q), bit), [0, 0])
            t[0] += ones if bit == 0 else shots - ones
            t[1] += shots
    out = infer_from_results(work_c, work_r, timestamp, source, qubit_index, min_shots, max_sim_qubits, context_mode)
    for (q, bit), (k, n) in sorted(tallies.items()):
        out.append(estimate_readout(q, bit, k, n, timestamp, f"{source}:readout-probe", min_shots))
    return out

"""Qiskit integration: workload inference from Sampler/legacy results, and
OBSERVED calibration from a BackendV2 Target or IBM BackendProperties."""

from __future__ import annotations

from collections.abc import Callable, Iterable, Mapping
from datetime import datetime
from typing import Any

from ..inferred import FlipTally, QubitIdeal, flip_estimates, tally_marginal
from ..models import Estimate, Metric, Provenance, insufficient, utcnow

_SKIP = {"barrier", "delay"}
_DETERMINISTIC_TOL = 1e-9


class CircuitAnalysis:
    """Noiseless prediction for each measured qubit of one circuit.

    ``measured`` maps physical qubit -> (register name, index in register,
    global clbit index).
    """

    def __init__(self, measured: dict[int, tuple[str, int, int]], ideal: dict[int, QubitIdeal]):
        self.measured = measured
        self.ideal = ideal


_UNIT_NS = {"s": 1e9, "ms": 1e6, "us": 1e3, "ns": 1.0, "ps": 1e-3}


def analyze_circuit(circuit, max_sim_qubits: int = 16, context_mode: str = "bucket") -> CircuitAnalysis:
    from qiskit import QuantumCircuit
    from qiskit.circuit import ControlFlowOp
    from qiskit.quantum_info import Statevector

    measured: dict[int, tuple[str, int, int]] = {}
    n_1q: dict[int, int] = {}
    n_2q: dict[int, int] = {}
    names: dict[int, dict[str, int]] = {}
    idle_ns: dict[int, float] = {}
    idle_dt: dict[int, int] = {}
    gates: list[tuple[Any, list[int]]] = []
    problem = ""

    if circuit.parameters:
        problem = "circuit has unbound parameters"
    for inst in circuit.data:
        op = inst.operation
        qs = [circuit.find_bit(q).index for q in inst.qubits]
        if op.name == "delay":
            unit = getattr(op, "unit", "dt")
            dur = op.duration if getattr(op, "duration", None) is not None else op.params[0]
            for q in qs:
                if unit == "dt":
                    idle_dt[q] = idle_dt.get(q, 0) + int(dur)
                elif unit in _UNIT_NS:
                    idle_ns[q] = idle_ns.get(q, 0.0) + float(dur) * _UNIT_NS[unit]
                else:
                    raise ValueError(f"unsupported delay unit {unit!r}")
            continue
        if op.name in _SKIP:
            continue
        if any(q in measured for q in qs):
            problem = problem or "mid-circuit measurement or operation after measurement"
        if isinstance(op, ControlFlowOp):
            problem = problem or f"control flow ({op.name}) not supported"
        elif op.name == "measure":
            c = inst.clbits[0]
            loc = circuit.find_bit(c)
            reg, idx = (loc.registers[0][0].name, loc.registers[0][1]) if loc.registers else ("", loc.index)
            measured[qs[0]] = (reg, idx, loc.index)
        elif op.name == "reset":
            problem = problem or "reset is not supported by the ideal simulator"
        else:
            gates.append((op, qs))
            counter = n_1q if len(qs) == 1 else n_2q
            for q in qs:
                counter[q] = counter.get(q, 0) + 1
                names.setdefault(q, {})[op.name] = names.get(q, {}).get(op.name, 0) + 1

    def ideal_for(q: int, bit: int | None, reason: str = "") -> QubitIdeal:
        return QubitIdeal(
            bit,
            n_1q.get(q, 0),
            n_2q.get(q, 0),
            reason,
            tuple(sorted(names.get(q, {}).items())),
            idle_ns.get(q, 0.0),
            idle_dt.get(q, 0),
            context_mode,
        )

    if problem:
        return CircuitAnalysis(measured, {q: ideal_for(q, None, problem) for q in measured})

    active = sorted({q for _, qs in gates for q in qs} | set(measured))
    if len(active) > max_sim_qubits:
        reason = f"{len(active)} active qubits > max_sim_qubits={max_sim_qubits}"
        return CircuitAnalysis(measured, {q: ideal_for(q, None, reason) for q in measured})

    index = {q: i for i, q in enumerate(active)}
    reduced = QuantumCircuit(len(active))
    for op, qs in gates:
        reduced.append(op, [index[q] for q in qs])
    try:
        sv = Statevector.from_instruction(reduced)
    except Exception as exc:  # non-unitary or unsupported instruction
        reason = f"ideal simulation failed: {exc}"
        return CircuitAnalysis(measured, {q: ideal_for(q, None, reason) for q in measured})

    ideal: dict[int, QubitIdeal] = {}
    for q in measured:
        p1 = float(sv.probabilities([index[q]])[1])
        if p1 < _DETERMINISTIC_TOL:
            ideal[q] = ideal_for(q, 0)
        elif p1 > 1 - _DETERMINISTIC_TOL:
            ideal[q] = ideal_for(q, 1)
        else:
            ideal[q] = ideal_for(q, None, f"ideal outcome not deterministic (p1={p1:.3f})")
    return CircuitAnalysis(measured, ideal)


def _ones_by_position(counts: Mapping[str, int]) -> tuple[int, dict[int, int]]:
    """Shots and per-bit-position ones from little-endian bitstring counts.

    Raises ``ValueError`` on malformed results: non-binary keys, keys of
    different lengths, negative or non-integer counts, or no shots."""
    if not isinstance(counts, Mapping) or not counts:
        raise ValueError(f"counts must be a non-empty mapping, got {type(counts).__name__}")
    shots = 0
    ones: dict[int, int] = {}
    width = None
    for key, c in counts.items():
        if not isinstance(key, str):
            raise ValueError(f"count keys must be bitstrings, got {key!r}")
        bits = key.replace(" ", "")
        if not bits or set(bits) - {"0", "1"}:
            raise ValueError(f"malformed bitstring key {key!r} (hex keys are not supported; pass bitstring counts)")
        if width is None:
            width = len(bits)
        elif len(bits) != width:
            raise ValueError(f"inconsistent bitstring lengths in counts ({width} vs {len(bits)})")
        if isinstance(c, bool) or int(c) != c:
            raise ValueError(f"count for {key!r} must be an integer, got {c!r}")
        c = int(c)
        if c < 0:
            raise ValueError(f"negative count {c} for {key!r}")
        shots += c
        for pos, ch in enumerate(reversed(bits)):
            if ch == "1":
                ones[pos] = ones.get(pos, 0) + c
    if shots == 0:
        raise ValueError("counts contain no shots")
    return shots, ones


def _bit_lookup(
    circuit, res, measured: Mapping[int, tuple[str, int, int]]
) -> Callable[[str, int, int], tuple[int, int] | None]:
    """``(register, index in register, global clbit) -> (shots, ones)`` for one
    circuit's result, or None when the result has no usable data for that bit.

    ``res`` is a SamplerV2 pub result (``.data`` with per-register BitArrays)
    or a counts dict as returned by ``Result.get_counts(i)``."""
    if hasattr(res, "data"):  # SamplerV2 pub result
        per_reg: dict[str, tuple[int, dict[int, int]] | None] = {}
        for name in {reg for reg, _, _ in measured.values()}:
            bitarray = getattr(res.data, name, None)
            if bitarray is None or bitarray.shape != ():
                per_reg[name] = None
            else:
                per_reg[name] = _ones_by_position(bitarray.get_counts())
        return lambda reg, idx, gidx: (
            None if (reg_tally := per_reg.get(reg)) is None else (reg_tally[0], reg_tally[1].get(idx, 0))
        )
    shots, ones = _ones_by_position(res)
    width = len(next(iter(res)).replace(" ", ""))
    if width != circuit.num_clbits:
        raise ValueError(
            f"counts have {width} bits but the circuit has {circuit.num_clbits} classical bits: "
            "results do not belong to this circuit"
        )
    return lambda reg, idx, gidx: (shots, ones.get(gidx, 0))


def infer_from_results(
    circuits: Iterable[Any],
    results: Iterable[Any],
    timestamp: datetime | None = None,
    source: str = "qiskit",
    min_shots: int = 200,
    max_sim_qubits: int = 16,
    context_mode: str = "bucket",
) -> list[Estimate]:
    """INFERRED effective-flip estimates from one batch (e.g. one job).

    Every circuit is treated as workload (v0.2 behaviour); see
    ``estimates_from_results`` for the v0.3 entry point that separates
    readout probes. ``results`` items may be SamplerV2 pub results (``.data``
    with per-register BitArrays) or plain counts dicts as returned by
    ``Result.get_counts(i)``. Circuits must be the ones actually executed
    (post-transpilation, physical qubit indices), otherwise qubit labels are
    logical, not physical.
    """
    timestamp = timestamp or utcnow()
    tallies: dict[tuple[int, str], FlipTally] = {}
    unidentified: dict[int, str] = {}
    for circuit, res in zip(circuits, results, strict=True):
        an = analyze_circuit(circuit, max_sim_qubits, context_mode)
        lookup = _bit_lookup(circuit, res, an.measured)
        for q, (reg, idx, gidx) in an.measured.items():
            ideal = an.ideal[q]
            if ideal.bit is None:
                unidentified.setdefault(q, ideal.reason)
                continue
            got = lookup(reg, idx, gidx)
            if got is None:
                unidentified.setdefault(q, "result for register missing or parameter-swept")
                continue
            tally_marginal(tallies, q, ideal, *got)
    return flip_estimates(tallies, unidentified, timestamp, source, min_shots)


# --------------------------------------------------------------------------- readout probes

_PROBE_OPS = ("x", "measure", "barrier")


def readout_probe_preparations(circuit) -> dict[int, tuple[int, tuple[str, int, int]]] | None:
    """If ``circuit`` is a readout probe, ``{qubit: (prepared bit, (register,
    index in register, global clbit))}`` for every measured qubit; else None.

    A readout probe consists only of X gates, barriers and terminal
    measurements, with at most one X per qubit and each measured qubit read
    into its own classical bit, so each measured qubit is prepared in a
    definite basis state and read out immediately. Anything else (another
    gate, a delay, a reset, control flow, parameters, an operation after a
    measurement, a barrier that holds a qubit still to be measured until
    another qubit's measurement has ended) makes the circuit workload: a
    prepared |1> left waiting decays, and its error would depend on the
    circuit. ``qnp.measured.readout_probe_circuits`` and the ``probe`` plans
    of ``qnp.hardware`` build such circuits."""
    if circuit.parameters:
        return None
    prepared: dict[int, int] = {}
    measured: dict[int, tuple[str, int, int]] = {}
    clbits: set[int] = set()
    to_measure = {circuit.find_bit(i.qubits[0]).index for i in circuit.data if i.operation.name == "measure"}
    for inst in circuit.data:
        name = inst.operation.name
        if name not in _PROBE_OPS:
            return None
        if name == "barrier":
            held = {circuit.find_bit(x).index for x in inst.qubits}
            if held & measured.keys() and held & (to_measure - measured.keys()):
                return None  # a later measurement waits for an earlier one
            continue
        (q,) = (circuit.find_bit(x).index for x in inst.qubits)
        if q in measured:
            return None  # operation after the measurement
        if name == "x":
            if prepared.get(q):
                return None  # two X gates: not a preparation
            prepared[q] = 1
            continue
        loc = circuit.find_bit(inst.clbits[0])
        if loc.index in clbits:
            return None  # two qubits read into one classical bit
        clbits.add(loc.index)
        reg, idx = (loc.registers[0][0].name, loc.registers[0][1]) if loc.registers else ("", loc.index)
        measured[q] = (reg, idx, loc.index)
    if not measured:
        return None
    return {q: (prepared.get(q, 0), m) for q, m in measured.items()}


def estimates_from_results(
    circuits: Iterable[Any],
    results: Iterable[Any],
    timestamp: datetime | None = None,
    source: str = "qiskit",
    min_shots: int = 200,
    max_sim_qubits: int = 16,
    context_mode: str = "exact",
    readout_probes: str = "auto",
) -> list[Estimate]:
    """Estimates from one batch (e.g. one job): MEASURED ``readout_error`` from
    the readout probes it contains and INFERRED effective flip rates from the
    rest (``infer_from_results``).

    ``readout_probes="auto"`` recognises probes by their structure
    (``readout_probe_preparations``) and pools their counts per (qubit,
    prepared bit); ``"off"`` treats every circuit as workload (v0.2).
    Contexts default to ``exact``: bucketed contexts pool circuits whose noise
    differs, which v0.2 Experiment E showed raises false alerts when the
    workload changes."""
    from ..measured import READOUT_CONTEXTS, estimate_readout

    if readout_probes not in ("auto", "off"):
        raise ValueError(f"readout_probes must be 'auto' or 'off', got {readout_probes!r}")
    timestamp = timestamp or utcnow()
    work_c, work_r = [], []
    tallies: dict[tuple[int, int], list[int]] = {}
    missing: dict[tuple[int, int], str] = {}
    for circuit, res in zip(circuits, results, strict=True):
        preps = readout_probe_preparations(circuit) if readout_probes == "auto" else None
        if preps is None:
            work_c.append(circuit)
            work_r.append(res)
            continue
        lookup = _bit_lookup(circuit, res, {q: m for q, (_, m) in preps.items()})
        for q, (bit, (reg, idx, gidx)) in preps.items():
            got = lookup(reg, idx, gidx)
            if got is None:
                missing.setdefault((q, bit), "result for register missing or parameter-swept")
                continue
            shots, ones = got
            t = tallies.setdefault((q, bit), [0, 0])
            t[0] += ones if bit == 0 else shots - ones
            t[1] += shots
    out = infer_from_results(work_c, work_r, timestamp, source, min_shots, max_sim_qubits, context_mode)
    probe_source = f"{source}:readout-probe"
    for (q, bit), (k, n) in sorted(tallies.items()):
        out.append(estimate_readout(q, bit, k, n, timestamp, probe_source, min_shots))
    for (q, bit), reason in sorted(missing.items()):
        if (q, bit) not in tallies:
            out.append(
                insufficient(
                    Metric.READOUT_ERROR,
                    (q,),
                    Provenance.MEASURED,
                    reason,
                    timestamp,
                    context=READOUT_CONTEXTS[bit],
                    source=probe_source,
                )
            )
    return out


# --------------------------------------------------------------------------- OBSERVED

_OBSERVED_ASSUMPTIONS = ("vendor-reported value; measurement method and uncertainty not provided",)


def observe_target(target, timestamp: datetime | None = None, source: str = "qiskit-target") -> list[Estimate]:
    """OBSERVED estimates from a Qiskit ``Target`` (T1, T2, measure and gate errors).

    A Target carries no calibration timestamp; pass the time the calibration
    was taken if you know it, otherwise ingestion time is used.
    """
    timestamp = timestamp or utcnow()
    out: list[Estimate] = []
    qprops = target.qubit_properties or []
    for q in range(target.num_qubits):
        props = qprops[q] if q < len(qprops) else None
        for metric, attr in ((Metric.T1, "t1"), (Metric.T2, "t2")):
            val = getattr(props, attr, None) if props is not None else None
            if val is None:
                out.append(
                    insufficient(
                        metric,
                        (q,),
                        Provenance.OBSERVED,
                        f"backend reports no {attr.upper()}",
                        timestamp,
                        source=source,
                    )
                )
            else:
                out.append(
                    Estimate(
                        metric,
                        (q,),
                        Provenance.OBSERVED,
                        timestamp,
                        value=float(val),
                        source=source,
                        assumptions=_OBSERVED_ASSUMPTIONS,
                    )
                )
    for name in target.operation_names:
        if name in _SKIP or name in ("reset", "id"):
            continue
        for qargs, iprops in (target[name] or {}).items():
            if qargs is None or iprops is None or iprops.error is None:
                continue
            metric = Metric.READOUT_ERROR if name == "measure" else Metric.GATE_ERROR
            out.append(
                Estimate(
                    metric,
                    tuple(qargs),
                    Provenance.OBSERVED,
                    timestamp,
                    value=float(iprops.error),
                    context="" if name == "measure" else name,
                    source=source,
                    assumptions=_OBSERVED_ASSUMPTIONS,
                )
            )
    return out


def observe_backend(backend, source: str | None = None) -> list[Estimate]:
    """OBSERVED estimates from a BackendV2. Uses ``backend.properties()``'s
    ``last_update_date`` as the timestamp when available (IBM Runtime)."""
    ts = None
    props = getattr(backend, "properties", None)
    if callable(props):
        try:
            p = props()
            ts = getattr(p, "last_update_date", None)
        except Exception:
            ts = None
    return observe_target(backend.target, ts, source or f"qiskit:{backend.name}")

"""Alert rendering: JSON for control systems, text for humans."""

from __future__ import annotations

import json
from collections.abc import Iterable

from .models import Alert, AlertLevel

_ORDER = {AlertLevel.CRITICAL: 0, AlertLevel.WARNING: 1, AlertLevel.INFO: 2}


def sort_alerts(alerts: Iterable[Alert]) -> list[Alert]:
    return sorted(alerts, key=lambda a: (_ORDER[a.level], a.qubits, a.metric.value, a.context))


def to_json(alerts: Iterable[Alert], indent: int | None = 2) -> str:
    return json.dumps([a.to_dict() for a in sort_alerts(alerts)], indent=indent, default=str)


def format_text(alerts: Iterable[Alert]) -> str:
    lines = [f"[{a.level.value:<8}] ({a.provenance.value}) {a.message}" for a in sort_alerts(alerts)]
    return "\n".join(lines) if lines else "No alerts."

"""IBM Quantum validation pathway: read-only by default, budgeted, auditable.

Nothing in this module submits a job unless *all* of the following hold:

1. the session was created with ``dry_run=False`` **and** ``allow_submission=True``;
2. the call passes ``authorize=True`` for that specific plan;
3. the plan fits the session's ``JobBudget`` (jobs, shots, circuits,
   estimated QPU seconds), counting everything already submitted.

Reading calibration data (``backend.properties()``, ``backend.target``) is
always allowed and never consumes QPU time. No function here triggers, or
can trigger, a physical recalibration: Qiskit Runtime exposes no such call,
and the profiler's ``mark_recalibrated`` only records that one happened.

Every snapshot and submission records backend identity and version, the
per-property calibration timestamps reported by the backend, execution
timestamps from ``job.metrics()``, physical qubit indices and the software
versions in use.

Vendor calibration values are *not* ground truth: they are point estimates
from the vendor's own procedure (method, fit model and uncertainty not
reported), taken at a time that may be hours before the job, and often on a
schedule unrelated to the workload. See docs/HARDWARE_VALIDATION.md.
"""

from __future__ import annotations

import platform
import sys
from collections.abc import Mapping, Sequence
from dataclasses import asdict, dataclass, field
from datetime import datetime, timezone
from importlib import metadata
from typing import Any

import numpy as np

from .measured import DecaySweepPlan
from .models import Estimate, Metric, Provenance, insufficient

__all__ = [
    "BudgetExceeded",
    "CharacterizationPlan",
    "HardwareSession",
    "JobBudget",
    "SubmissionRefused",
    "align_delays",
    "backend_snapshot",
    "delay_grid_seconds",
    "estimates_from_sweep_job",
    "estimates_from_t1_job",
    "observe_ibm_backend",
    "plan_characterization",
    "software_versions",
]

VENDOR_ASSUMPTIONS = (
    "vendor-reported value; measurement method, fit model and uncertainty not provided",
    "timestamp is the vendor's calibration time for this property, not the execution time of any job",
)


class SubmissionRefused(RuntimeError):
    """Raised when a job would be submitted without explicit authorization."""


class BudgetExceeded(RuntimeError):
    """Raised when a plan does not fit the remaining job budget."""


def software_versions() -> dict[str, str | None]:
    out: dict[str, str | None] = {"python": sys.version.split()[0], "platform": platform.platform()}
    for name in ("quantum-noise-profiler", "qiskit", "qiskit-ibm-runtime", "qiskit-aer", "numpy", "scipy"):
        try:
            out[name] = metadata.version(name)
        except metadata.PackageNotFoundError:
            out[name] = None
    return out


def _iso(x) -> str | None:
    if x is None:
        return None
    if isinstance(x, datetime):
        if x.tzinfo is None:
            raise ValueError(f"backend reported a naive timestamp {x!r}")
        return x.isoformat()
    return str(x)


def _is_local(backend) -> bool:
    """True for fake/local backends (no QPU time is consumed)."""
    mod = type(backend).__module__
    return "fake_provider" in mod or "qiskit_aer" in mod or mod.startswith("qiskit.providers.fake")


# --------------------------------------------------------------------------- read-only snapshot


def backend_snapshot(backend, qubits: Sequence[int] | None = None) -> dict[str, Any]:
    """Read-only record of what the backend reports about itself.

    Missing metadata is recorded as missing (``None`` plus an entry in
    ``missing``), never filled in."""
    retrieved = datetime.now(timezone.utc)
    snap: dict[str, Any] = {
        "retrieved_at": retrieved.isoformat(),
        "backend_name": getattr(backend, "name", None),
        "backend_version": getattr(backend, "backend_version", None),
        "backend_class": f"{type(backend).__module__}.{type(backend).__name__}",
        "local_simulation": _is_local(backend),
        "num_qubits": getattr(backend, "num_qubits", None),
        "software": software_versions(),
        "missing": [],
        "qubits": {},
        "gates": {},
    }
    cfg = None
    try:
        cfg = backend.configuration()
    except Exception:  # BackendV2 without a configuration
        snap["missing"].append("configuration")
    if cfg is not None:
        snap["processor_type"] = getattr(cfg, "processor_type", None)
        snap["dt_s"] = getattr(cfg, "dt", None)
        snap["default_rep_delay_s"] = getattr(cfg, "default_rep_delay", None)
    props = None
    try:
        props = backend.properties()
    except Exception:
        props = None
    if props is None:
        snap["missing"].append("properties")
        snap["last_update_date"] = None
    else:
        snap["last_update_date"] = _iso(getattr(props, "last_update_date", None))
    n = snap["num_qubits"] or 0
    qs = list(range(n)) if qubits is None else [_physical_index(q) for q in qubits]
    for q in qs:
        if not 0 <= q < n:
            raise ValueError(f"physical qubit {q} does not exist on {snap['backend_name']} ({n} qubits)")
        entry: dict[str, Any] = {}
        if props is not None:
            try:
                for key, (val, ts) in props.qubit_property(q).items():
                    entry[key] = {"value": float(val), "calibrated_at": _iso(ts)}
            except Exception as exc:
                entry["error"] = f"qubit_property failed: {exc}"
        tq = (backend.target.qubit_properties or [None] * n)[q] if hasattr(backend, "target") else None
        if tq is not None:
            entry["target_t1_s"] = getattr(tq, "t1", None)
            entry["target_t2_s"] = getattr(tq, "t2", None)
        snap["qubits"][str(q)] = entry
    if props is not None:
        for g in getattr(props, "gates", []) or []:
            qa = tuple(g.qubits)
            if qubits is not None and not set(qa) <= set(qs):
                continue
            rec = {p.name: {"value": float(p.value), "calibrated_at": _iso(p.date)} for p in g.parameters}
            snap["gates"][f"{g.gate}{list(qa)}"] = rec
    return snap


def observe_ibm_backend(backend, qubits: Sequence[int] | None = None, source: str | None = None) -> list[Estimate]:
    """OBSERVED estimates with each property's own calibration timestamp.

    Unlike ``observe_backend`` (which stamps every value with
    ``last_update_date``), this uses the per-property dates that IBM
    ``BackendProperties`` carries, and records the asymmetric readout
    probabilities P(1|0) and P(0|1) as separate READOUT_ERROR contexts."""
    snap = backend_snapshot(backend, qubits)
    src = source or f"ibm:{snap['backend_name']}@{snap['backend_version']}"
    now = datetime.now(timezone.utc)
    out: list[Estimate] = []
    mapping = {
        "T1": (Metric.T1, ""),
        "T2": (Metric.T2, ""),
        "readout_error": (Metric.READOUT_ERROR, ""),
        "prob_meas1_prep0": (Metric.READOUT_ERROR, "p(1|0)"),
        "prob_meas0_prep1": (Metric.READOUT_ERROR, "p(0|1)"),
    }
    for qs, entry in snap["qubits"].items():
        q = int(qs)
        for key, (metric, ctx) in mapping.items():
            rec = entry.get(key)
            if rec is None:
                if not ctx:
                    out.append(
                        insufficient(
                            metric, (q,), Provenance.OBSERVED, f"backend reports no {key}", now, source=src, context=ctx
                        )
                    )
                continue
            ts = datetime.fromisoformat(rec["calibrated_at"]) if rec["calibrated_at"] else now
            val = rec["value"]
            if not np.isfinite(val) or (metric in (Metric.T1, Metric.T2) and val <= 0):
                out.append(
                    insufficient(
                        metric,
                        (q,),
                        Provenance.OBSERVED,
                        f"backend reports invalid {key}={val}",
                        ts,
                        source=src,
                        context=ctx,
                    )
                )
                continue
            out.append(
                Estimate(
                    metric,
                    (q,),
                    Provenance.OBSERVED,
                    ts,
                    value=float(val),
                    context=ctx,
                    source=src,
                    assumptions=VENDOR_ASSUMPTIONS,
                )
            )
    return out


# --------------------------------------------------------------------------- budgets and plans


@dataclass
class JobBudget:
    max_jobs: int = 0
    max_total_shots: int = 0
    max_circuits_per_job: int = 300
    max_estimated_qpu_seconds: float = 0.0

    def __post_init__(self) -> None:
        for name in ("max_jobs", "max_total_shots", "max_circuits_per_job"):
            v = getattr(self, name)
            if not isinstance(v, int) or v < 0:
                raise ValueError(f"{name} must be a non-negative int")
        if self.max_estimated_qpu_seconds < 0:
            raise ValueError("max_estimated_qpu_seconds must be >= 0")


@dataclass
class CharacterizationPlan:
    kind: str
    backend_name: str
    physical_qubits: list[int]
    delays_s: list[float]
    shots: int
    circuits: list[Any] = field(repr=False)
    estimated_qpu_seconds: float = 0.0
    notes: list[str] = field(default_factory=list)
    # acquisition plan of each qubit's t1 / t2_echo sweep (random delay order,
    # ground references); the circuits follow them, qubit after qubit
    sweeps: dict[int, DecaySweepPlan] | None = None
    parallel: bool = False  # probes: all qubits in the same two circuits

    @property
    def sweep(self) -> DecaySweepPlan | None:
        """The sweep plan shared by every qubit (None if they differ or for probes)."""
        if not self.sweeps:
            return None
        plans = list(self.sweeps.values())
        return plans[0] if all(p == plans[0] for p in plans) else None

    @property
    def n_circuits(self) -> int:
        return len(self.circuits)

    @property
    def total_shots(self) -> int:
        return self.n_circuits * self.shots

    def summary(self) -> dict[str, Any]:
        d = {k: v for k, v in asdict(self).items() if k not in ("circuits", "sweeps")}
        d.update(n_circuits=self.n_circuits, total_shots=self.total_shots)
        d["sweep"] = None if self.sweep is None else self.sweep.to_dict()
        d["sweeps"] = None if not self.sweeps else {str(q): p.to_dict() for q, p in self.sweeps.items()}
        return d


def _estimate_seconds(backend, circuits, shots: int) -> float:
    """Crude upper estimate of QPU time: per shot, the longest circuit
    duration plus the repetition delay and measurement; per job, a fixed
    overhead. It is a budgeting guard, not a billing prediction."""
    try:
        rep = float(backend.configuration().default_rep_delay)
    except Exception:
        rep = 250e-6
    try:
        meas = float(backend.target["measure"][(0,)].duration or 1e-6)
    except Exception:
        meas = 2e-6
    per_circ = []
    for c in circuits:
        d = sum(
            float(inst.operation.duration or 0.0) if getattr(inst.operation, "unit", "s") == "s" else 0.0
            for inst in c.data
            if inst.operation.name == "delay"
        )
        per_circ.append(d + meas + rep)
    return float(sum(per_circ) * shots + 5.0)


def delay_grid_seconds(backend) -> float | None:
    """Smallest delay step the backend accepts: dt times the least common
    multiple of its granularity and pulse/acquire alignment (IBM backends
    reject delays off this grid). None if the backend reports no dt."""
    import math

    target = getattr(backend, "target", None)
    dt = getattr(target, "dt", None) or getattr(backend, "dt", None)
    if not dt:
        return None
    try:
        tc = target.timing_constraints()  # type: ignore[union-attr]
        step = math.lcm(int(tc.granularity), int(tc.pulse_alignment), int(tc.acquire_alignment))
    except Exception:
        step = 1
    return float(dt) * step


def align_delays(backend, delays_s: Sequence[float], parts: int = 1) -> list[float]:
    """Round each delay to the backend's delay grid (``parts`` equal pieces
    each on the grid, e.g. 2 for the two halves of a Hahn echo), so that the
    delays the device executes are the ones the fit uses."""
    grid = delay_grid_seconds(backend)
    if grid is None:
        return [float(d) for d in delays_s]
    step = grid * parts
    return [float(round(float(d) / step) * step) for d in delays_s]


def _physical_index(q) -> int:
    """A physical qubit index exactly as given: a non-boolean integer. Floats,
    strings and booleans are rejected rather than coerced, so a job can never
    be laid out on a different qubit than the caller wrote."""
    if isinstance(q, bool) or not isinstance(q, (int, np.integer)):
        raise ValueError(f"physical qubit identifiers must be integers, got {q!r} ({type(q).__name__})")
    return int(q)


def plan_characterization(
    backend,
    kind: str,
    physical_qubits: Sequence[int],
    delays_s: Sequence[float] | Mapping[int, Sequence[float]] = (),
    shots: int = 1000,
    *,
    n_references: int = 5,
    randomize: bool = True,
    seed: int | None = None,
    parallel: bool = False,
) -> CharacterizationPlan:
    """Build (but do not run) ISA circuits for T1, Hahn-echo T2 or basis-state
    probes on explicit physical qubits.

    Sweeps follow ``qnp.measured.decay_sweep_plan(delays, n_references,
    randomize, seed)``: delays in random order with interleaved ground
    references, so that readout drift during the sweep is detectable
    (``n_references=0, randomize=False`` is the v0.2 design). ``delays_s``
    may map each physical qubit to its own delays (e.g. scaled to its vendor
    T1). ``parallel=True`` (probes only) prepares and reads every qubit in
    the same two circuits (``qnp.measured.readout_probe_circuits``)."""
    from qiskit import QuantumCircuit, transpile

    from .measured import decay_plan_circuits, decay_sweep_plan, readout_probe_circuits

    if kind not in ("t1", "t2_echo", "probe"):
        raise ValueError("kind must be 't1', 't2_echo' or 'probe'")
    if shots <= 0 or not isinstance(shots, int):
        raise ValueError("shots must be a positive int")
    if parallel and kind != "probe":
        raise ValueError("parallel=True is only supported for probes")
    n = backend.num_qubits
    qs = [_physical_index(q) for q in physical_qubits]
    if len(set(qs)) != len(qs) or any(not 0 <= q < n for q in qs):
        raise ValueError(f"invalid physical qubits {physical_qubits} for a {n}-qubit backend")
    per_qubit = isinstance(delays_s, Mapping)
    if isinstance(delays_s, Mapping):
        if set(delays_s) != set(qs):
            raise ValueError("per-qubit delays must be given for exactly the planned qubits")
        delays_of = {q: [float(x) for x in delays_s[q]] for q in qs}
    else:
        delays_of = {q: [float(x) for x in delays_s] for q in qs}
    if kind != "probe" and any(len(d) < 3 or any(x < 0 for x in d) for d in delays_of.values()):
        raise ValueError("decay characterization needs >= 3 non-negative delays")
    grid = delay_grid_seconds(backend)
    if kind != "probe":
        delays_of = {q: align_delays(backend, d, 2 if kind == "t2_echo" else 1) for q, d in delays_of.items()}
        if any(len(set(d)) < 3 for d in delays_of.values()):
            raise ValueError("fewer than 3 distinct delays remain on the backend's delay grid")
    sweeps = None if kind == "probe" else {q: decay_sweep_plan(delays_of[q], n_references, randomize, seed) for q in qs}
    circuits = []
    if parallel:
        circuits = transpile(
            readout_probe_circuits(qs, num_qubits=n), backend, initial_layout=list(range(n)), optimization_level=0
        )
        for c in circuits:
            c.metadata = {**(c.metadata or {}), "physical_qubits": qs}
    for q in [] if parallel else qs:
        if sweeps is not None:
            logical = decay_plan_circuits(sweeps[q], kind)
        else:
            z = QuantumCircuit(1, 1, metadata={"qnp": "probe", "prep": 0})
            z.measure(0, 0)
            o = QuantumCircuit(1, 1, metadata={"qnp": "probe", "prep": 1})
            o.x(0)
            o.measure(0, 0)
            logical = [z, o]
        isa = transpile(logical, backend, initial_layout=[q], optimization_level=0)
        for c in isa:
            c.metadata = {**(c.metadata or {}), "physical_qubit": q}
        circuits += isa
    notes = []
    if kind != "probe" and grid is not None:
        notes.append(f"delays rounded to the backend's delay grid ({grid:.4g} s); the fit uses the rounded delays")
    if kind == "t2_echo":
        notes.append("Hahn echo T2 is not T2* (Ramsey); IBM's reported T2 is Hahn echo")
    if sweeps is not None and not all(p.randomized for p in sweeps.values()):
        notes.append("delays acquired in delay order: measurement drift during the sweep cannot be detected")
    common = [] if per_qubit or not qs else delays_of[qs[0]]
    plan = CharacterizationPlan(kind, backend.name, qs, common, shots, circuits, 0.0, notes, sweeps, parallel)
    plan.estimated_qpu_seconds = _estimate_seconds(backend, circuits, shots)
    return plan


# --------------------------------------------------------------------------- session


@dataclass
class HardwareSession:
    """Guards every interaction with a (possibly real) backend.

    Defaults are the safe ones: ``dry_run=True``, ``allow_submission=False``,
    a zero budget."""

    backend: Any
    dry_run: bool = True
    allow_submission: bool = False
    budget: JobBudget = field(default_factory=JobBudget)
    log: list[dict[str, Any]] = field(default_factory=list)
    _jobs: int = 0
    _shots: int = 0
    _seconds: float = 0.0

    def snapshot(self, qubits: Sequence[int] | None = None) -> dict[str, Any]:
        snap = backend_snapshot(self.backend, qubits)
        self.log.append(
            {
                "event": "snapshot",
                "at": snap["retrieved_at"],
                "backend": snap["backend_name"],
                "last_update_date": snap["last_update_date"],
            }
        )
        return snap

    def check_budget(self, plan: CharacterizationPlan) -> None:
        b = self.budget
        problems = []
        if self._jobs + 1 > b.max_jobs:
            problems.append(f"jobs {self._jobs + 1} > max_jobs {b.max_jobs}")
        if self._shots + plan.total_shots > b.max_total_shots:
            problems.append(f"shots {self._shots + plan.total_shots} > max_total_shots {b.max_total_shots}")
        if plan.n_circuits > b.max_circuits_per_job:
            problems.append(f"circuits {plan.n_circuits} > max_circuits_per_job {b.max_circuits_per_job}")
        if self._seconds + plan.estimated_qpu_seconds > b.max_estimated_qpu_seconds:
            problems.append(
                f"estimated QPU s {self._seconds + plan.estimated_qpu_seconds:.1f} > {b.max_estimated_qpu_seconds}"
            )
        if problems:
            raise BudgetExceeded("; ".join(problems))

    def submit(self, plan: CharacterizationPlan, authorize: bool = False) -> dict[str, Any]:
        """Run a characterization plan, or describe what would run.

        In dry-run mode (the default) nothing is sent; the returned record
        says what would have been submitted and whether it fits the budget."""
        record: dict[str, Any] = {
            "plan": plan.summary(),
            "software": software_versions(),
            "requested_at": datetime.now(timezone.utc).isoformat(),
        }
        try:
            self.check_budget(plan)
            record["budget_ok"] = True
        except BudgetExceeded as exc:
            record["budget_ok"] = False
            record["budget_problem"] = str(exc)
        if self.dry_run:
            record["status"] = "dry_run"
            self.log.append({"event": "dry_run", **record})
            return record
        if not self.allow_submission:
            raise SubmissionRefused("session does not allow submission (allow_submission=False)")
        if not authorize:
            raise SubmissionRefused("submission requires authorize=True for this plan")
        if not record["budget_ok"]:
            raise BudgetExceeded(record["budget_problem"])
        from qiskit_ibm_runtime import SamplerV2

        record["snapshot_before"] = backend_snapshot(self.backend, plan.physical_qubits)
        sampler = SamplerV2(mode=self.backend)
        job = sampler.run(plan.circuits, shots=plan.shots)
        self._jobs += 1
        self._shots += plan.total_shots
        self._seconds += plan.estimated_qpu_seconds
        record["job_id"] = job.job_id()
        record["status"] = "submitted"
        record["local_simulation"] = _is_local(self.backend)
        self.log.append({"event": "submitted", "job_id": record["job_id"], "plan": plan.summary()})
        record["job"] = job
        return record


def execution_timestamps(job) -> dict[str, bool | str | None]:
    """Execution timestamps from ``job.metrics()`` when the service provides
    them. Local/fake jobs have none; that is reported, not invented."""
    try:
        m = job.metrics()
    except Exception as exc:
        return {"available": False, "reason": f"job.metrics() failed: {exc}"}
    ts = (m or {}).get("timestamps") or {}
    return {
        "available": bool(ts),
        "created": ts.get("created"),
        "running": ts.get("running"),
        "finished": ts.get("finished"),
    }


def _ones(pub) -> int:
    bits = next(iter(pub.data.values())) if hasattr(pub.data, "values") else pub.data.c
    return sum(v for k, v in bits.get_counts().items() if k.endswith("1"))


def estimates_from_sweep_job(plan: CharacterizationPlan, result, timestamp: datetime) -> list[Estimate]:
    """MEASURED T1 or Hahn-echo T2 per physical qubit from a SamplerV2 result
    of a ``t1`` or ``t2_echo`` plan, with the drift checks of its sweep plan."""
    from .measured import estimate_t1_from_plan, estimate_t2_echo_from_plan

    if plan.kind not in ("t1", "t2_echo") or not plan.sweeps:
        raise ValueError("plan is not a decay-sweep plan")
    if timestamp.tzinfo is None:
        raise ValueError("timestamp must be timezone-aware")
    fn = estimate_t1_from_plan if plan.kind == "t1" else estimate_t2_echo_from_plan
    out, offset = [], 0
    for q in plan.physical_qubits:
        sw = plan.sweeps[q]
        ones = [_ones(result[offset + j]) for j in range(len(sw.slots))]
        offset += len(sw.slots)
        out.append(fn(q, sw, ones, plan.shots, timestamp, source=f"qnp-{plan.kind}@{plan.backend_name}"))
    return out


def estimates_from_t1_job(plan: CharacterizationPlan, result, timestamp: datetime) -> list[Estimate]:
    """MEASURED T1 per physical qubit from a SamplerV2 result of a t1 plan."""
    if plan.kind != "t1":
        raise ValueError("plan is not a T1 plan")
    return estimates_from_sweep_job(plan, result, timestamp)

"""Configurable simulated noise for validation experiments (Qiskit Aer and Cirq).

What is modelled (per qubit unless stated):

* thermal relaxation with T1, T2 (T2 <= 2 T1) during gates and during
  explicit ``delay`` instructions (Aer ``RelaxationNoisePass``);
* amplitude damping and pure dephasing as separate channels (via T1 and the
  pure-dephasing time T_phi, 1/T2 = 1/(2 T1) + 1/T_phi);
* depolarizing noise per gate, configurable by gate name (gate-dependent);
* two-qubit depolarizing noise per coupler;
* asymmetric readout error P(read 1 | 0) != P(read 0 | 1);
* time variation of any parameter across batches (``qnp.sim`` schedules:
  ramps, steps, Ornstein-Uhlenbeck correlated disturbances, telegraph
  two-level-system switching), missing observations and irregular
  observation intervals.

What is *not* modelled, and therefore not validated by any experiment that
uses this module: leakage outside the qubit subspace, coherent (unitary)
over-rotation and crosstalk, non-Markovian 1/f dephasing within a circuit
(the echo cancels nothing here: Aer's T2 is Markovian), measurement-induced
state transitions, thermal excited-state population, correlated errors
*within* a circuit across qubits, and calibration-dependent changes of gate
durations. The simulator does not reproduce the behaviour of any specific
superconducting, trapped-ion or neutral-atom device; parameter values are
chosen to be in a plausible range, not fitted to hardware.
"""

from __future__ import annotations

from collections.abc import Iterable, Mapping
from dataclasses import dataclass, field, replace
from datetime import datetime, timedelta, timezone
from typing import Any, cast

import numpy as np

ONE_Q_NOISY = ("x", "sx", "sxdg", "h", "ry", "rx", "u", "u3", "y")
TWO_Q_NOISY = ("cx", "cz", "ecr")
DEFAULT_GATE_TIMES = {
    "sxdg": 35.5e-9,
    "x": 35.5e-9,
    "sx": 35.5e-9,
    "h": 35.5e-9,
    "ry": 35.5e-9,
    "rx": 35.5e-9,
    "u": 35.5e-9,
    "u3": 35.5e-9,
    "y": 35.5e-9,
    "rz": 0.0,
    "cx": 300e-9,
    "cz": 300e-9,
    "ecr": 300e-9,
}


@dataclass(frozen=True)
class QubitNoise:
    t1_s: float | None = None
    t2_s: float | None = None
    p_read1_given0: float = 0.0
    p_read0_given1: float = 0.0
    depol_1q: float = 0.0  # Qiskit depolarizing parameter lambda: rho -> (1-l) rho + l I/2

    def __post_init__(self) -> None:
        for name in ("p_read1_given0", "p_read0_given1", "depol_1q"):
            v = getattr(self, name)
            if not 0 <= v <= 1:
                raise ValueError(f"{name} must be in [0, 1], got {v}")
        if (self.t1_s is None) != (self.t2_s is None):
            raise ValueError("give both t1_s and t2_s, or neither")
        if self.t1_s is not None:
            t2_s = cast(float, self.t2_s)  # given together with t1_s (checked above)
            if self.t1_s <= 0 or t2_s <= 0:
                raise ValueError("T1 and T2 must be positive")
            if t2_s > 2 * self.t1_s * (1 + 1e-12):
                raise ValueError(f"T2={self.t2_s} > 2*T1={2 * self.t1_s} is unphysical")

    @property
    def t_phi_s(self) -> float | None:
        """Pure-dephasing time: 1/T_phi = 1/T2 - 1/(2 T1); inf if T2 == 2 T1."""
        if self.t1_s is None:
            return None
        rate = 1 / cast(float, self.t2_s) - 1 / (2 * self.t1_s)  # t2_s is set whenever t1_s is
        return float("inf") if rate <= 0 else 1 / rate


@dataclass(frozen=True)
class DeviceNoise:
    qubits: Mapping[int, QubitNoise]
    depol_2q: float = 0.0
    depol_2q_per_pair: Mapping[tuple[int, int], float] = field(default_factory=dict)
    gate_scale: Mapping[str, float] = field(default_factory=dict)  # gate-dependent multiplier on depol_1q
    gate_times: Mapping[str, float] = field(default_factory=lambda: dict(DEFAULT_GATE_TIMES))
    relax_during_gates: bool = True

    def with_qubit(self, q: int, **changes: Any) -> DeviceNoise:
        qs = dict(self.qubits)
        qs[q] = replace(qs.get(q, QubitNoise()), **changes)
        return replace(self, qubits=qs)


def readout_only(p_by_qubit: Mapping[int, float], asymmetry: float = 0.0) -> DeviceNoise:
    """Symmetric (asymmetry=0) or asymmetric readout error only. With
    asymmetry a, P(0|1) = p (1 + a) and P(1|0) = p (1 - a)."""
    return DeviceNoise(
        {
            q: QubitNoise(p_read1_given0=p * (1 - asymmetry), p_read0_given1=p * (1 + asymmetry))
            for q, p in p_by_qubit.items()
        }
    )


# --------------------------------------------------------------------------- Qiskit Aer


def aer_noise_model(device: DeviceNoise):
    from qiskit_aer.noise import NoiseModel, ReadoutError, depolarizing_error, thermal_relaxation_error

    nm = NoiseModel(basis_gates=sorted(set(ONE_Q_NOISY) | set(TWO_Q_NOISY) | {"rz", "id", "delay", "measure"}))
    for q, qn in device.qubits.items():
        for g in ONE_Q_NOISY:
            err = None
            lam = qn.depol_1q * device.gate_scale.get(g, 1.0)
            if lam > 0:
                err = depolarizing_error(min(lam, 1.0), 1)
            t = device.gate_times.get(g, 0.0)
            if device.relax_during_gates and qn.t1_s is not None and t > 0:
                th = thermal_relaxation_error(qn.t1_s, qn.t2_s, t)
                err = th if err is None else err.compose(th)
            if err is not None:
                nm.add_quantum_error(err, g, [q])
        if qn.p_read1_given0 > 0 or qn.p_read0_given1 > 0:
            nm.add_readout_error(
                ReadoutError([[1 - qn.p_read1_given0, qn.p_read1_given0], [qn.p_read0_given1, 1 - qn.p_read0_given1]]),
                [q],
            )
    pairs = set(device.depol_2q_per_pair)
    qs = sorted(device.qubits)
    # Every ordered pair gets two-qubit-gate noise when there is any to add:
    # depolarizing (global or per pair) or thermal relaxation during the gate.
    # (Before 2026-10-13 pairs were only added when depol_2q > 0, which silently
    # dropped 2q-gate relaxation in Aer while the Cirq builder kept it.)
    any_relax = device.relax_during_gates and any(device.qubits[q].t1_s for q in qs)
    if device.depol_2q > 0 or any_relax:
        pairs |= {(a, b) for a in qs for b in qs if a != b}
    for a, b in sorted(pairs):
        lam = device.depol_2q_per_pair.get((a, b), device.depol_2q)
        for g in TWO_Q_NOISY:
            err = depolarizing_error(lam, 2) if lam > 0 else None
            t = device.gate_times.get(g, 0.0)
            qa, qb = device.qubits.get(a), device.qubits.get(b)
            if device.relax_during_gates and t > 0 and qa and qb and qa.t1_s and qb.t1_s:
                th = thermal_relaxation_error(qb.t1_s, qb.t2_s, t).expand(thermal_relaxation_error(qa.t1_s, qa.t2_s, t))
                err = th if err is None else err.compose(th)
            if err is not None:
                nm.add_quantum_error(err, g, [a, b])
    return nm


def add_delay_relaxation(circuits, device: DeviceNoise):
    """Insert thermal relaxation on ``delay`` instructions (durations in seconds)."""
    from qiskit.circuit import Delay
    from qiskit_aer.noise import RelaxationNoisePass

    n = max(max(device.qubits) + 1, max(c.num_qubits for c in circuits))
    t1s = [device.qubits[q].t1_s if q in device.qubits and device.qubits[q].t1_s else float("inf") for q in range(n)]
    t2s = [device.qubits[q].t2_s if q in device.qubits and device.qubits[q].t2_s else float("inf") for q in range(n)]
    p = RelaxationNoisePass(t1s, t2s, dt=None, op_types=[Delay])
    return [p(c) for c in circuits]


def aer_run_counts(circuits, device: DeviceNoise, shots: int, seed: int) -> list[dict[str, int]]:
    """Run circuits on Aer under ``device`` noise; returns counts dicts."""
    from qiskit_aer import AerSimulator

    sim = AerSimulator(noise_model=aer_noise_model(device))
    circs = circuits
    if any(inst.operation.name == "delay" for c in circuits for inst in c.data):
        circs = add_delay_relaxation(circuits, device)
    res = sim.run(circs, shots=shots, seed_simulator=seed).result()
    return [res.get_counts(i) for i in range(len(circs))]


# --------------------------------------------------------------------------- Cirq


def _readout_kraus(p10: float, p01: float):
    """Classical asymmetric readout as a channel before a Z measurement.
    p01 = P(read 1 | 0), p10 = P(read 0 | 1)."""
    k0 = np.array([[np.sqrt(1 - p01), 0], [0, np.sqrt(1 - p10)]])
    k1 = np.array([[0, np.sqrt(p10)], [0, 0]])
    k2 = np.array([[0, 0], [np.sqrt(p01), 0]])
    return (k0, k1, k2)


def _cirq_relaxation_ops(q, qn: QubitNoise, t: float):
    import cirq

    if qn.t1_s is None or t <= 0:
        return []
    ops = [cirq.amplitude_damp(1 - np.exp(-t / qn.t1_s)).on(q)]
    tphi = qn.t_phi_s
    if tphi is not None and np.isfinite(tphi):
        ops.append(cirq.phase_damp(1 - np.exp(-2 * t / tphi)).on(q))
    return ops


def cirq_noisy_circuit(circuit, device: DeviceNoise, index_of=lambda q: q.x):
    """Return a copy of ``circuit`` with the device's noise channels inserted.

    Gate names follow Qiskit's convention through a small map (X -> x,
    X**0.5 -> sx, H -> h, Ry -> ry, CNOT -> cx, CZ -> cz); ``cirq.WaitGate``
    plays the role of ``delay``. Depolarizing parameters are converted from
    Qiskit's lambda to Cirq's p (p = 3 lambda / 4 for one qubit,
    15 lambda / 16 for two)."""
    import cirq

    from .adapters.cirq_adapter import canonical_gate_name as gname

    out = []
    for moment in circuit:
        noise_after = []
        for op in moment.operations:
            if cirq.is_measurement(op):
                pre = []
                for q in op.qubits:
                    qn = device.qubits.get(index_of(q))
                    if qn and (qn.p_read1_given0 or qn.p_read0_given1):
                        pre.append(cirq.KrausChannel(_readout_kraus(qn.p_read0_given1, qn.p_read1_given0)).on(q))
                if pre:
                    out.append(cirq.Moment(pre))
                continue
            if isinstance(op.gate, cirq.WaitGate):
                t = op.gate.duration.total_nanos() * 1e-9
                for q in op.qubits:
                    qn = device.qubits.get(index_of(q))
                    if qn:
                        noise_after += _cirq_relaxation_ops(q, qn, t)
                continue
            name = gname(op)
            t = device.gate_times.get(name, 0.0)
            if len(op.qubits) == 1:
                q = op.qubits[0]
                qn = device.qubits.get(index_of(q))
                if qn and name in ONE_Q_NOISY:
                    lam = qn.depol_1q * device.gate_scale.get(name, 1.0)
                    if lam > 0:
                        noise_after.append(cirq.depolarize(3 * lam / 4).on(q))
                    if device.relax_during_gates:
                        noise_after += _cirq_relaxation_ops(q, qn, t)
            elif len(op.qubits) == 2 and name in TWO_Q_NOISY:
                a, b = (index_of(q) for q in op.qubits)
                lam = device.depol_2q_per_pair.get((a, b), device.depol_2q)
                if lam > 0:
                    noise_after.append(cirq.depolarize(15 * lam / 16, n_qubits=2).on(*op.qubits))
                if device.relax_during_gates:
                    for q in op.qubits:
                        qn = device.qubits.get(index_of(q))
                        if qn:
                            noise_after += _cirq_relaxation_ops(q, qn, t)
        out.append(
            cirq.Moment(
                [
                    op
                    for op in moment.operations
                    if not isinstance(op.gate, cirq.WaitGate) and not cirq.is_measurement(op)
                ]
            )
        )
        if noise_after:
            # split into moments without qubit overlap
            while noise_after:
                used: set[Any] = set()
                this, rest = [], []
                for op in noise_after:
                    if used & set(op.qubits):
                        rest.append(op)
                    else:
                        this.append(op)
                        used |= set(op.qubits)
                out.append(cirq.Moment(this))
                noise_after = rest
        # measurement moment re-added after readout noise
        meas = [op for op in moment.operations if cirq.is_measurement(op)]
        if meas:
            out.append(cirq.Moment(meas))
    return cirq.Circuit(m for m in out if len(m.operations))


# --------------------------------------------------------------------------- schedules


def linear_ramp(start: float, end: float, n: int) -> np.ndarray:
    return np.linspace(start, end, n)


def step(base: float, ratio: float, at: int, n: int) -> np.ndarray:
    return np.where(np.arange(n) < at, base, base * ratio)


def ou_log_process(
    base: float, sigma: float, tau_batches: float, n: int, rng: np.random.Generator, n_series: int = 1, rho: float = 0.0
) -> np.ndarray:
    """Correlated disturbances: base * exp(x_t) with x an Ornstein-Uhlenbeck
    process (stationary sd ``sigma``, correlation time ``tau_batches``),
    started in its stationary law. With ``n_series`` > 1, series share a
    common-mode component with correlation ``rho``. Returns (n_series, n)."""
    if tau_batches <= 0 or sigma < 0 or not 0 <= rho <= 1:
        raise ValueError("need tau_batches > 0, sigma >= 0, rho in [0, 1]")
    a = np.exp(-1 / tau_batches)
    innov = np.sqrt(1 - a * a)
    common = np.empty(n)
    own = np.empty((n_series, n))
    common[0] = rng.normal()
    own[:, 0] = rng.normal(size=n_series)
    for t in range(1, n):
        common[t] = a * common[t - 1] + innov * rng.normal()
        own[:, t] = a * own[:, t - 1] + innov * rng.normal(size=n_series)
    x = sigma * (np.sqrt(rho) * common[None, :] + np.sqrt(1 - rho) * own)
    return base * np.exp(x)


def telegraph(low: float, high: float, switch_prob: float, n: int, rng: np.random.Generator) -> np.ndarray:
    """Two-level-system switching: the value flips between ``low`` and ``high``
    with probability ``switch_prob`` per batch (TLS-like T1 fluctuations)."""
    state = rng.random() < 0.5
    out = np.empty(n)
    for t in range(n):
        out[t] = high if state else low
        if rng.random() < switch_prob:
            state = not state
    return out


def missing_mask(n: int, p_missing: float, rng: np.random.Generator, keep_first: int = 0) -> np.ndarray:
    """True where the batch is missing (job failed / not run)."""
    m = rng.random(n) < p_missing
    m[:keep_first] = False
    return m


def irregular_timestamps(
    n: int,
    mean_interval: timedelta,
    jitter: float,
    rng: np.random.Generator,
    t0: datetime = datetime(2026, 1, 1, tzinfo=timezone.utc),
) -> list[datetime]:
    """Strictly increasing timestamps with gamma-distributed gaps
    (coefficient of variation ``jitter``; 0 gives a regular grid)."""
    if jitter < 0:
        raise ValueError("jitter must be >= 0")
    if jitter == 0:
        gaps = np.full(n, mean_interval.total_seconds())
    else:
        k = 1 / jitter**2
        gaps = rng.gamma(k, mean_interval.total_seconds() / k, n)
    gaps = np.maximum(gaps, 1.0)
    t = np.cumsum(np.r_[0.0, gaps[:-1]])
    return [t0 + timedelta(seconds=float(s)) for s in t]


def recalibration_batches(n: int, mean_interval_batches: float, rng: np.random.Generator) -> list[int]:
    """Irregular recalibration events (geometric gaps)."""
    out: list[int] = []
    t = 0
    while True:
        t += int(rng.geometric(1 / mean_interval_batches))
        if t >= n:
            return out
        out.append(t)


def schedule_devices(base: DeviceNoise, changes: Iterable[tuple[int, str, np.ndarray]]) -> list[DeviceNoise]:
    """Per-batch devices: ``changes`` = (qubit, QubitNoise field, values per batch)."""
    changes = list(changes)
    n = len(changes[0][2]) if changes else 0
    out = []
    for i in range(n):
        d = base
        for q, name, values in changes:
            d = d.with_qubit(q, **{name: float(values[i])})
        out.append(d)
    return out


__all__ = [
    "DeviceNoise",
    "QubitNoise",
    "add_delay_relaxation",
    "aer_noise_model",
    "aer_run_counts",
    "cirq_noisy_circuit",
    "irregular_timestamps",
    "linear_ramp",
    "missing_mask",
    "ou_log_process",
    "readout_only",
    "recalibration_batches",
    "schedule_devices",
    "step",
    "telegraph",
]

"""Append-only SQLite store of estimates and recalibration marks."""

from __future__ import annotations

import json
import sqlite3
from collections.abc import Iterable
from datetime import datetime

from .models import Estimate

_SCHEMA = """
CREATE TABLE IF NOT EXISTS estimates (
    id INTEGER PRIMARY KEY,
    metric TEXT NOT NULL, qubits TEXT NOT NULL, context TEXT NOT NULL,
    provenance TEXT NOT NULL, status TEXT NOT NULL, ts TEXT NOT NULL,
    body TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS estimates_series ON estimates (metric, qubits, context, provenance, ts);
CREATE TABLE IF NOT EXISTS recalibrations (
    id INTEGER PRIMARY KEY, ts TEXT NOT NULL, qubits TEXT NOT NULL, note TEXT NOT NULL
);
"""


class EstimateStore:
    def __init__(self, path: str = ":memory:"):
        self.conn = sqlite3.connect(path)
        self.conn.executescript(_SCHEMA)

    def add(self, estimates: Iterable[Estimate]) -> int:
        rows = [
            (
                e.metric.value,
                json.dumps(list(e.qubits)),
                e.context,
                e.provenance.value,
                e.status.value,
                e.timestamp.isoformat(),
                json.dumps(e.to_dict()),
            )
            for e in estimates
        ]
        with self.conn:
            self.conn.executemany(
                "INSERT INTO estimates (metric, qubits, context, provenance, status, ts, body) "
                "VALUES (?, ?, ?, ?, ?, ?, ?)",
                rows,
            )
        return len(rows)

    def all(self) -> list[Estimate]:
        cur = self.conn.execute("SELECT body FROM estimates ORDER BY ts, id")
        return [Estimate.from_dict(json.loads(b)) for (b,) in cur]

    def series(self) -> dict[tuple, list[Estimate]]:
        out: dict[tuple, list[Estimate]] = {}
        for e in self.all():
            out.setdefault(e.series_key, []).append(e)
        return out

    def mark_recalibrated(self, ts: datetime, qubits: Iterable[int] | None = None, note: str = "") -> None:
        """Baselines restart after a recalibration. ``qubits=None`` means all."""
        with self.conn:
            self.conn.execute(
                "INSERT INTO recalibrations (ts, qubits, note) VALUES (?, ?, ?)",
                (ts.isoformat(), json.dumps(None if qubits is None else sorted(qubits)), note),
            )

    def last_recalibration(self, qubits: tuple[int, ...]) -> datetime | None:
        latest = None
        for ts, qs in self.conn.execute("SELECT ts, qubits FROM recalibrations"):
            qs = json.loads(qs)
            if qs is None or set(qubits) & set(qs):
                t = datetime.fromisoformat(ts)
                latest = t if latest is None or t > latest else latest
        return latest

